  };
  useEffect(() => { load(); }, []);

  if (error) return <Gate icon={<ShieldAlert className="h-10 w-10 text-destructive" />} title="Couldn’t load your access" text={error} />;
  if (!me) return <div className="flex min-h-screen items-center justify-center"><Loader2 className="h-8 w-8 animate-spin text-primary" /></div>;
  if (!me.roles.length) {
    return me.canBootstrap ? (
      <Gate icon={<ShieldCheck className="h-10 w-10 text-accent" />} title="Set up league administration"
        text="No Super Administrator exists yet. Claim the role to configure the league, then grant roles to your staff from Users & Roles.">
