            <Route path="/games" element={<GamesPage />} />
            <Route path="/games/:id" element={<GameConsole />} />
            <Route path="/standings" element={<LeagueTables />} />
            <Route path="/assignments" element={<Assignments />} />
            <Route path="/settings" element={<SettingsPage />} />
