export default createEndpoint({
  description: 'Deletes a managed record after permission checks and records it in the audit log',
  inputSchema: z.object({ entity: z.string(), id: z.string() }),
  outputSchema: z.object({ success: z.boolean() }),
  execute: async ({ input, context }) => {
    const def = ENTITIES[input.entity];
    if (!def || def.readOnly || input.entity === 'leagueSettings') throw new Error('This record cannot be deleted.');
    const a = await getAccess(context);
    const full = can(a, def.perm);
    const scoped = !full && !!def.teamField && can(a, 'team') && !!a.teamId && input.entity !== 'teams';
    if (!full && !scoped) throw new Error('You do not have permission to delete this.');
    const client = (zite as unknown as Record<string, { findOne: (p: object) => Promise<Record<string, unknown> | undefined>; delete: (p: object) => Promise<unknown> }>)[def.table];
    const before = await client.findOne({ id: input.id });
    if (!before) throw new Error('Record not found');
    if (scoped && before[def.teamField!] !== a.teamId) throw new Error('That record belongs to another team.');
    if (input.entity === 'games' && !['Scheduled', 'Postponed', 'Canceled'].includes(String(before.status))) {
      throw new Error('Games that have started cannot be deleted — cancel or correct them instead.');
    }
    if (input.entity === 'userRoles' && before.role === 'Super Administrator' && !a.isSuper) throw new Error('Only a Super Administrator can remove Super Administrator access.');
    await client.delete({ id: input.id });
    await audit(a.email, `Deleted ${input.entity}`, input.entity, input.id, before);
    return { success: true };
  },
});

