export default createEndpoint({
  description: 'Lists records of a managed entity for the admin dashboard (permission-checked)',
  inputSchema: z.object({ entity: z.string() }),
  outputSchema: z.object({ records: z.array(z.record(z.any())), scopedTeamId: z.string() }),
  execute: async ({ input, context }) => {
    const def = ENTITIES[input.entity];
    if (!def) throw new Error('Unknown entity');
    const a = await getAccess(context);
    const full = can(a, def.perm) || (input.entity === 'games' && can(a, 'gameops'));
    const scoped = !full && !!def.teamField && can(a, 'team') && !!a.teamId;
    if (!full && !scoped) throw new Error('You do not have permission to view this section.');
    const client = (zite as unknown as Record<string, { findAll: (p: object) => Promise<{ records: Record<string, unknown>[] }> }>)[def.table];
    const { records } = await client.findAll({ limit: 2000 });
    let out = scoped ? records.filter((r) => r[def.teamField!] === a.teamId) : records;
    if (input.entity === 'games') {
      // Same live state + ordering as the public schedule.
      await tickDueGames();
      const { rows } = await zite.sql({ query: `SELECT g.id, v."name" AS venue, g."status" AS status, COALESCE(g."homeScore",0) AS hs, COALESCE(g."awayScore",0) AS vs FROM "Games" g LEFT JOIN "Venues" v ON v.id::text = g."venueId"` });
      const m = new Map(rows.map((r) => [String(r.id), r]));
      out = out.map((g): Record<string, unknown> => {
        const r = m.get(String(g.id));
        const status = String(r?.status ?? g.status ?? 'Scheduled');
        const started = !['Scheduled', 'Postponed', 'Canceled'].includes(status);
        return { ...g, status, venueName: String(r?.venue ?? ''), score: started ? `${r?.vs ?? 0} – ${r?.hs ?? 0}` : '' };
      }).sort((x, y) => String(x.scheduledStart ?? '').localeCompare(String(y.scheduledStart ?? '')));
    }
    if (input.entity === 'auditLogs') {
      out = out.sort((x, y) => String(y.loggedAt ?? '').localeCompare(String(x.loggedAt ?? ''))).slice(0, 1000);
    }
    return { records: out, scopedTeamId: scoped ? a.teamId : '' };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { ENTITIES, cleanRecord } from '../lib/entities';
import { can, getAccess } from '../lib/auth';
import { audit, getSettings } from '../lib/engine';

type Client = {
  findOne: (p: object) => Promise<Record<string, unknown> | undefined>;
  findAll: (p: object) => Promise<{ records: Record<string, unknown>[] }>;
  create: (p: object) => Promise<Record<string, unknown>>;
  update: (p: object) => Promise<unknown>;
};

export default createEndpoint({
  description: 'Creates or updates a managed record, with validation, permission checks and an audit entry',
  inputSchema: z.object({ entity: z.string(), id: z.string().optional(), record: z.record(z.any()) }),
  outputSchema: z.object({ id: z.string() }),
  execute: async ({ input, context }) => {
    const def = ENTITIES[input.entity];
    if (!def || def.readOnly) throw new Error('This section cannot be edited.');
    const a = await getAccess(context);
    const full = can(a, def.perm);
    const scoped = !full && !!def.teamField && can(a, 'team') && !!a.teamId;
    if (!full && !scoped) throw new Error('You do not have permission to edit this.');
    const client = (zite as unknown as Record<string, Client>)[def.table];
    const isCreate = !input.id;
    const rec = cleanRecord(def, input.record, isCreate);
    let before: Record<string, unknown> | undefined;
    if (!isCreate) {
      before = await client.findOne({ id: input.id });
      if (!before) throw new Error('Record not found');
    }

    if (scoped) {
      if (input.entity === 'teams') {
        if (isCreate || input.id !== a.teamId) throw new Error('Team managers can only edit their own team.');
      } else {
        if (before && before[def.teamField!] !== a.teamId) throw new Error('That record belongs to another team.');
        rec[def.teamField!] = a.teamId;
      }
    }

    // Entity-specific rules
    if (input.entity === 'games') {
      const home = (rec.homeTeamId ?? before?.homeTeamId) as string, away = (rec.awayTeamId ?? before?.awayTeamId) as string;
      if (home && home === away) throw new Error('Home and away teams must be different.');
      if (isCreate) {
        const s = await getSettings();
        const t = await zite.teams.findOne({ id: home });
        const { rows } = await zite.sql({ query: 'SELECT COUNT(*) AS c FROM "Games"' });
        rec.status = 'Scheduled';
        rec.gameCode = rec.gameCode || `NFHL-${String(Number(rows[0]?.c ?? 0) + 1).padStart(3, '0')}`;
        rec.seasonId = rec.seasonId || s.currentSeasonId;
        rec.venueId = rec.venueId || t?.venueId || null;
        Object.assign(rec, { homeScore: 0, awayScore: 0, homeShots: 0, awayShots: 0, period: 0, clockRunning: false, clockRemaining: s.periodMinutes * 60 });
      } else if (rec.scheduledStart && before?.scheduledStart && rec.scheduledStart !== new Date(String(before.scheduledStart)).toISOString()) {
        if (!['Scheduled', 'Postponed'].includes(String(before.status))) throw new Error('Only scheduled or postponed games can be rescheduled.');
        if (!before.originalStart) rec.originalStart = before.scheduledStart;
        if (before.status === 'Postponed') rec.status = 'Scheduled';
      }
    }
    if (input.entity === 'userRoles') {
      if (rec.email) rec.email = String(rec.email).toLowerCase().trim();
      const touchingSuper = rec.role === 'Super Administrator' || before?.role === 'Super Administrator';
      if (touchingSuper && !a.isSuper) throw new Error('Only a Super Administrator can grant or change Super Administrator access.');
      if ((rec.role ?? before?.role) === 'Team Manager' && !(rec.teamId ?? before?.teamId)) throw new Error('Team managers must be linked to a team.');
      if (isCreate && rec.active === undefined) rec.active = true;
    }
    if (input.entity === 'articles') {
      if (rec.title && !rec.slug && !before?.slug) rec.slug = String(rec.title).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '') + '-' + Date.now().toString(36);
      if (isCreate && !rec.status) rec.status = 'Draft';
      if (rec.status === 'Published' && !rec.publishAt && !before?.publishAt) rec.publishAt = new Date().toISOString();
      if (rec.status === 'Scheduled' && !(rec.publishAt ?? before?.publishAt)) throw new Error('Scheduled articles need a publish date.');
    }
    if (input.entity === 'contactMessages' && isCreate) throw new Error('Messages are created from the public contact form.');

    let id = input.id ?? '';
    if (input.entity === 'leagueSettings' && isCreate) {
      const existing = (await zite.leagueSettings.findAll({ limit: 1 })).records[0];
      if (existing) id = existing.id;
    }
    if (id) await client.update({ id, record: rec });
    else id = String((await client.create({ record: rec })).id);

    if (input.entity === 'seasons' && rec.isCurrent) {
      const { records } = await zite.seasons.findAll({ limit: 200 });
      for (const s of records) if (s.id !== id && s.isCurrent) await zite.seasons.update({ id: s.id, record: { isCurrent: false } as never });
      const st = (await zite.leagueSettings.findAll({ limit: 1 })).records[0];
      if (st) await zite.leagueSettings.update({ id: st.id, record: { currentSeasonId: id } as never });
    }

    const changes = before ? Object.fromEntries(Object.entries(rec).filter(([k, v]) => JSON.stringify(before![k] ?? null) !== JSON.stringify(v))) : rec;
    await audit(a.email, `${isCreate ? 'Created' : 'Updated'} ${input.entity}`, input.entity, id, changes);
    return { id };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { requirePerm } from '../lib/auth';
import { audit } from '../lib/engine';

export default createEndpoint({
  description: 'Assigns, replaces or removes an official for a game position (keeps assignment history)',
  inputSchema: z.object({
    action: z.enum(['assign', 'remove', 'setSystem', 'setStatus']),
    status: z.string().optional(),
    gameId: z.string(),
    position: z.string().optional(),
    officialId: z.string().optional(),
    assignmentId: z.string().optional(),
    system: z.string().optional(),
  }),
  outputSchema: z.object({ ok: z.boolean(), warnings: z.array(z.string()) }),
  execute: async ({ input, context }) => {
    const a = await requirePerm(context, 'assignments');
    const game = await zite.games.findOne({ id: input.gameId });
    if (!game) throw new Error('Game not found');
    if (['Final', 'Canceled'].includes(game.status ?? '')) throw new Error('Assignments are locked for completed or canceled games.');
    const warnings: string[] = [];
    if (input.action === 'setSystem') {
      if (!['2-Official', '3-Official', '4-Official'].includes(input.system ?? '')) throw new Error('Invalid system');
      await zite.games.update({ id: game.id, record: { officiatingSystem: input.system } as never });
      await audit(a.email, 'Changed officiating system', 'Game', game.id, input.system);
      return { ok: true, warnings };
    }
    const { records } = await zite.officialAssignments.findAll({ filters: { gameId: game.id }, limit: 100 });
    if (input.action === 'setStatus') {
      const x = records.find((r) => r.id === input.assignmentId);
      if (!x) throw new Error('Assignment not found');
      if (!['Pending', 'Accepted', 'Declined'].includes(input.status ?? '')) throw new Error('Invalid status');
      await zite.officialAssignments.update({ id: x.id, record: { status: input.status, respondedAt: new Date().toISOString(), responseNote: `Set by admin (${a.email})` } as never });
      await audit(a.email, `Set assignment status to ${input.status}`, 'OfficialAssignment', x.id, { gameId: game.id, position: x.position });
      return { ok: true, warnings };
    }
    if (input.action === 'remove') {
      const x = records.find((r) => r.id === input.assignmentId);
      if (!x) throw new Error('Assignment not found');
      await zite.officialAssignments.update({ id: x.id, record: { status: 'Removed', respondedAt: new Date().toISOString() } as never });
      await audit(a.email, 'Removed official assignment', 'OfficialAssignment', x.id, { gameId: game.id, position: x.position });
      return { ok: true, warnings };
    }
    if (!input.officialId || !input.position) throw new Error('Choose an official and position.');
    const off = await zite.officials.findOne({ id: input.officialId });
    if (!off || off.active === false) throw new Error('Official not found or inactive.');
    if (input.position.startsWith('Referee') && off.officialType !== 'Referee') warnings.push(`${off.name} is a linesperson assigned to a referee position.`);
    const active = records.filter((r) => !['Replaced', 'Removed', 'Declined'].includes(r.status ?? ''));
    if (active.some((r) => r.officialId === off.id && r.position !== input.position)) throw new Error(`${off.name} already holds another position in this game.`);
    // League-office calendar day (Eastern) so evening games in any arena time zone fall on the same date.
    const day = game.scheduledStart ? new Date(game.scheduledStart).toLocaleDateString('en-CA', { timeZone: 'America/Toronto' }) : '';
    const avail = await zite.officialAvailability.findAll({ filters: { officialId: off.id }, limit: 500 });
    if (avail.records.some((v) => v.date === day && v.status === 'Unavailable')) warnings.push(`${off.name} marked themselves unavailable on ${day}.`);
    const sameDay = await zite.sql({
      query: `SELECT COUNT(*) AS c FROM "OfficialAssignments" oa JOIN "Games" g ON g.id::text = oa."gameId"
        WHERE oa."officialId" = $1 AND oa."gameId" <> $2 AND oa."status" IN ('Pending','Accepted') AND to_char(g."scheduledStart" AT TIME ZONE 'America/Toronto', 'YYYY-MM-DD') = $3`,
      params: [off.id, game.id, day],
    });
    if (Number(sameDay.rows[0]?.c)) warnings.push(`${off.name} is already assigned to another game that day.`);
    for (const r of active.filter((r) => r.position === input.position)) {
      await zite.officialAssignments.update({ id: r.id, record: { status: 'Replaced', respondedAt: new Date().toISOString() } as never });
    }
    for (const r of records.filter((r) => r.position === input.position && r.status === 'Declined')) {
      await zite.officialAssignments.update({ id: r.id, record: { status: 'Replaced' } as never });
    }
    const created = await zite.officialAssignments.create({
      record: { label: `${game.gameCode} · ${input.position}`, gameId: game.id, officialId: off.id, position: input.position, status: 'Pending', assignedByEmail: a.email } as never,
    });
    if (off.user) {
      const user = Array.isArray(off.user) ? off.user[0] : off.user;
      if (user) await zite.notifications.create({ record: { title: 'New game assignment', body: `${game.gameCode} — ${input.position}. Please accept or decline in the Officials Portal.`, user, link: '/officials/portal', kind: 'Assignment', isRead: false } as never });
    }
    await audit(a.email, 'Assigned official', 'OfficialAssignment', created.id, { gameId: game.id, officialId: off.id, position: input.position, warnings });
    return { ok: true, warnings };
  },
});

