    side: z.enum(['home', 'away']).optional(),
    playerId: z.string().optional(),
    eventId: z.string().optional(),
    event: EventInput.optional(),
    review: z.object({
      goalEventId: z.string(),
      callOnIce: z.string(),
      callAfterReview: z.string().optional(),
      reason: z.string().optional(),
      note: z.string().optional(),
      official: z.string().optional(),
    }).optional(),
  }),
  outputSchema: z.object({ ok: z.boolean(), message: z.string() }),
  execute: async ({ input, context }) => {
    const a = await requirePerm(context, 'gameops');
    const s = await getSettings();
    const raw = await zite.games.findOne({ id: input.gameId });
    if (!raw) throw new Error('Game not found');
    let g = await tickGame(raw, s);
    const now = Date.now();
    const nowIso = new Date(now).toISOString();
    const p = Number(g.period || 0);
    const update = async (rec: Record<string, unknown>) => { await zite.games.update({ id: g.id, record: rec as never }); Object.assign(g, rec); };
    const requireStatus = (...st: string[]) => { if (!st.includes(g.status ?? '')) throw new Error(`Not allowed while the game is ${g.status}.`); };
    const log = (action: string, details?: unknown) => audit(a.email, action, 'Game', g.id, details);
    let message = 'Done';

    switch (input.action) {
      case 'warmup':
        requireStatus('Scheduled', 'Postponed');
        await update({ status: 'Warmup', statusNote: 'Warmups underway' });
        await log('Set warmup'); break;
      case 'start': {
        requireStatus('Scheduled', 'Warmup', 'Postponed');
        const pickG = async (tid?: string) => tid ? (await zite.players.findAll({ filters: { teamId: tid, position: 'G' }, limit: 5 })).records[0]?.id ?? '' : '';
        await update({
          status: 'Live', period: 1, clockRemaining: periodLength(1, s), clockRunning: true, clockAnchorAt: nowIso, liveStartedAt: nowIso,
          homeGoalieId: g.homeGoalieId || (await pickG(g.homeTeamId)), awayGoalieId: g.awayGoalieId || (await pickG(g.awayTeamId)),
          statusNote: '', needsReview: false,
        });
        await logEvent(g.id, { eventType: 'Game Start', period: 1, elapsedSeconds: 0, summary: 'Game is underway' }, `manual:${g.id}:start:${nowIso}`);
        await logEvent(g.id, { eventType: 'Period Start', period: 1, elapsedSeconds: 0, summary: 'Start of 1st period' }, `manual:${g.id}:p1:${nowIso}`);
        const [h, aw] = await Promise.all([teamName(g.homeTeamId), teamName(g.awayTeamId)]);
        await notifyFans(g, 'Game Start', 'Game underway', `${aw} at ${h} has started.`);
        await log('Started game manually'); break;
      }
      case 'delayStart':
        requireStatus('Scheduled', 'Warmup');
        if (!input.newStart || Number.isNaN(Date.parse(input.newStart))) throw new Error('Provide a valid new start time.');
        await update({ scheduledStart: new Date(input.newStart).toISOString(), originalStart: g.originalStart || g.scheduledStart, status: 'Scheduled', statusNote: input.reason || 'Delayed start' });
        await log('Delayed start', { newStart: input.newStart, reason: input.reason }); break;
      case 'pause':
        requireStatus('Live', 'Overtime');
        if (!g.clockRunning) throw new Error('Clock is already stopped.');
        await update({ clockRunning: false, clockRemaining: Math.round(clockRemaining(g, now) * 10) / 10, clockAnchorAt: nowIso });
        message = 'Clock paused'; break;
      case 'resume':
        requireStatus('Live', 'Overtime');
        if (g.clockRunning) throw new Error('Clock is already running.');
        if (Number(g.clockRemaining ?? 0) <= 0) throw new Error('Period clock is at 0:00 — change the period or set the clock.');
        await update({ clockRunning: true, clockAnchorAt: nowIso });
        message = 'Clock running'; break;
      case 'setClock': {
        requireStatus('Live', 'Overtime', 'Intermission', 'Suspended');
        const len = periodLength(p, s);
        if (input.seconds === undefined || input.seconds < 0 || input.seconds > len) throw new Error(`Clock must be between 0 and ${len / 60}:00.`);
        await update({ clockRemaining: input.seconds, clockAnchorAt: nowIso });
        await log('Corrected clock', { seconds: input.seconds, period: p }); message = 'Clock corrected'; break;
      }
      case 'setPeriod': {
        requireStatus('Live', 'Overtime', 'Intermission', 'Suspended');
        const np = input.period ?? 0;
        if (np < 1 || np > 4) throw new Error('Period must be 1–4 (use Start shootout for the shootout).');
        await update({ period: np, clockRunning: false, clockRemaining: input.seconds ?? periodLength(np, s), clockAnchorAt: nowIso, status: np === 4 ? 'Overtime' : 'Live', intermissionEndsAt: null });
        await log('Changed period', { period: np }); message = `Now in ${periodLabel(np)}`; break;
      }
      case 'endPeriod': {
        requireStatus('Live', 'Overtime');
        await update({ clockRunning: false, clockRemaining: 0, clockAnchorAt: nowIso });
        await logEvent(g.id, { eventType: 'Period End', period: p, elapsedSeconds: periodLength(p, s), summary: `End of ${periodLabel(p)}${p <= 3 ? ' period' : ''}` }, `manual:${g.id}:pend:${p}:${nowIso}`);
        const [h, aw] = await Promise.all([teamName(g.homeTeamId), teamName(g.awayTeamId)]);
        await notifyFans(g, 'Period End', `End of ${periodLabel(p)}`, `${aw} ${g.awayScore ?? 0} – ${h} ${g.homeScore ?? 0}`);
        await log('Ended period', { period: p }); message = 'Period ended'; break;
      }
      case 'startIntermission': {
        requireStatus('Live', 'Overtime');
        const mins = input.minutes ?? (p === 3 ? 2 : s.intermissionMinutes);
        await update({ status: 'Intermission', clockRunning: false, clockRemaining: 0, clockAnchorAt: nowIso, intermissionEndsAt: new Date(now + mins * 60000).toISOString(), statusNote: `${periodLabel(p)} Intermission` });
        await logEvent(g.id, { eventType: 'Intermission', period: p, elapsedSeconds: periodLength(p, s), summary: `${periodLabel(p)} intermission (${mins} min)` }, `manual:${g.id}:int:${p}:${nowIso}`);
        await log('Started intermission', { minutes: mins }); message = 'Intermission started'; break;
      }
      case 'endIntermission': {
        requireStatus('Intermission');
        const np = Math.min(p + 1, 4);
        if (np === 4 && Number(g.homeScore) !== Number(g.awayScore)) throw new Error('Game is not tied — finalize it instead of starting overtime.');
        await update({ status: np === 4 ? 'Overtime' : 'Live', period: np, clockRemaining: periodLength(np, s), clockRunning: true, clockAnchorAt: nowIso, intermissionEndsAt: null, statusNote: '' });
        if (np === 4) await logEvent(g.id, { eventType: 'Overtime', period: 4, elapsedSeconds: 0, summary: 'Overtime begins (sudden death)' }, `manual:${g.id}:ot:${nowIso}`);
        await logEvent(g.id, { eventType: 'Period Start', period: np, elapsedSeconds: 0, summary: `Start of ${periodLabel(np)}${np <= 3 ? ' period' : ''}` }, `manual:${g.id}:ps:${np}:${nowIso}`);
        message = `${periodLabel(np)} started`; break;
      }
      case 'startOvertime':
        requireStatus('Live', 'Intermission');
        if (p < 3 || Number(g.homeScore) !== Number(g.awayScore)) throw new Error('Overtime requires a tie after regulation.');
        await update({ status: 'Overtime', period: 4, clockRemaining: periodLength(4, s), clockRunning: true, clockAnchorAt: nowIso, intermissionEndsAt: null, statusNote: '' });
        await logEvent(g.id, { eventType: 'Overtime', period: 4, elapsedSeconds: 0, summary: 'Overtime begins (sudden death)' }, `manual:${g.id}:ot:${nowIso}`);
        await log('Started overtime'); break;
      case 'startShootout':
        requireStatus('Overtime', 'Live', 'Intermission');
        if (Number(g.homeScore) !== Number(g.awayScore)) throw new Error('A shootout requires a tied game.');
        await update({ status: 'Shootout', period: 5, clockRunning: false, clockRemaining: 0, clockAnchorAt: nowIso, statusNote: 'Shootout' });
        await logEvent(g.id, { eventType: 'Shootout', period: 5, elapsedSeconds: 0, summary: 'Shootout' }, `manual:${g.id}:so:${nowIso}`);
        await log('Started shootout'); break;
      case 'suspend':
        requireStatus('Live', 'Overtime', 'Intermission', 'Shootout', 'Warmup');
        await update({ status: 'Suspended', clockRunning: false, clockRemaining: Math.round(clockRemaining(g, now)), clockAnchorAt: nowIso, statusNote: input.reason || 'Game suspended', needsReview: true, reviewReason: `Suspended: ${input.reason || 'no reason given'}` });
        await logEvent(g.id, { eventType: 'Suspension', period: Math.max(p, 1), elapsedSeconds: elapsedInPeriod(g, s, now), summary: `Game suspended — ${input.reason || 'stoppage'}` });
        await log('Suspended game', { reason: input.reason }); break;
      case 'resumeSuspended':
        requireStatus('Suspended');
        await update({ status: p >= 5 ? 'Shootout' : p === 4 ? 'Overtime' : 'Live', statusNote: '', needsReview: false, reviewReason: '', clockAnchorAt: nowIso });
        await logEvent(g.id, { eventType: 'Note', period: Math.max(p, 1), elapsedSeconds: elapsedInPeriod(g, s, now), summary: 'Play resumes after suspension' });
        await log('Resumed suspended game'); break;
      case 'postpone':
        requireStatus('Scheduled', 'Warmup', 'Suspended');
        await update({ status: 'Postponed', statusNote: input.reason || 'Postponed', originalStart: g.originalStart || g.scheduledStart, ...(input.newStart ? { scheduledStart: new Date(input.newStart).toISOString(), status: 'Scheduled', statusNote: `Rescheduled — ${input.reason || ''}`.trim() } : {}) });
        await log('Postponed game', { reason: input.reason, newStart: input.newStart }); break;
      case 'cancel':
        requireStatus('Scheduled', 'Warmup', 'Postponed', 'Suspended');
        await update({ status: 'Canceled', clockRunning: false, statusNote: input.reason || 'Canceled' });
        await log('Canceled game', { reason: input.reason }); break;
      case 'finalize': {
        requireStatus(...ACTIVE_STATUSES);
        if (g.clockRunning) await update({ clockRunning: false, clockRemaining: Math.round(clockRemaining(g, now)), clockAnchorAt: nowIso });
        g = await recomputeTotals(g);
        await update(await finalizePatch(g, s, a.email));
        message = 'Game finalized — standings and stats updated'; break;
      }
      case 'reopen':
        requireStatus('Final');
        if (!input.reason?.trim()) throw new Error('A reason is required to reopen a final game.');
        await update({ status: p >= 5 ? 'Shootout' : p === 4 ? 'Overtime' : 'Live', finalizedAt: null, clockRunning: false, statusNote: 'Reopened for correction', needsReview: true, reviewReason: `Reopened: ${input.reason}` });
        await logEvent(g.id, { eventType: 'Note', period: Math.max(p, 1), elapsedSeconds: 99998, summary: 'Result reopened for correction by league office' });
        await log('Reopened final game', { reason: input.reason }); message = 'Game reopened'; break;
      case 'clearReview':
        await update({ needsReview: false, reviewReason: '' });
        await log('Cleared review flag'); break;
      case 'setGoalie': {
        requireStatus('Scheduled', 'Warmup', 'Live', 'Intermission', 'Overtime', 'Shootout', 'Suspended');
        const teamId = input.side === 'home' ? g.homeTeamId : g.awayTeamId;
        const pl = input.playerId ? await zite.players.findOne({ id: input.playerId }) : undefined;
        if (input.playerId && (!pl || pl.teamId !== teamId)) throw new Error('Goalie must be on that team.');
        await update(input.side === 'home' ? { homeGoalieId: input.playerId ?? '' } : { awayGoalieId: input.playerId ?? '' });
        if (ACTIVE_STATUSES.includes(g.status ?? '') && g.status !== 'Warmup') {
          await logEvent(g.id, { eventType: 'Goalie Change', period: Math.max(p, 1), elapsedSeconds: elapsedInPeriod(g, s, now), teamId, playerId: input.playerId ?? '', summary: pl ? `${pl.fullName} in goal` : 'Goalie pulled for extra attacker' }, input.clientKey);
        }
        await log('Goalie change', { side: input.side, playerId: input.playerId }); break;
      }
      case 'recordEvent': {
        const e = input.event;
        if (!e) throw new Error('Missing event');
        if (input.clientKey) {
          const dup = await zite.gameEvents.findAll({ filters: { gameId: g.id, clientKey: input.clientKey }, limit: 1 });
          if (dup.records[0]) return { ok: true, message: 'Already recorded (duplicate ignored)' };
        }
        requireStatus('Live', 'Overtime', 'Intermission', 'Shootout', 'Suspended', 'Warmup');
        const period = e.period ?? Math.max(p, 1);
        const elapsed = e.elapsedSeconds ?? (period === p ? elapsedInPeriod(g, s, now) : 0);
        if (period < 1 || period > 5) throw new Error('Invalid period.');
        if (period <= 4 && (elapsed < 0 || elapsed > periodLength(period, s))) throw new Error('Event time is outside the period.');
        if (period > p && p > 0) throw new Error('Events cannot be recorded in a future period.');
        const teamSide = e.teamId === g.homeTeamId ? 'home' : e.teamId === g.awayTeamId ? 'away' : null;
        const needsTeam = ['Goal', 'Shot', 'Penalty', 'Shootout Attempt', 'Timeout', 'Disallowed Goal'].includes(e.eventType);
        if (needsTeam && !teamSide) throw new Error('Choose the team for this event.');
        const roster = teamSide ? (await zite.players.findAll({ filters: { teamId: e.teamId! }, limit: 100 })).records : [];
        const nameOf = (id?: string) => roster.find((r) => r.id === id)?.fullName ?? '';
        for (const pid of [e.playerId, e.assist1Id, e.assist2Id].filter(Boolean)) {
          if (!roster.find((r) => r.id === pid)) throw new Error('All players must be on the selected team’s roster.');
        }
        if (e.assist1Id && (e.assist1Id === e.playerId || e.assist1Id === e.assist2Id)) throw new Error('Scorer and assists must be different players.');
        if (e.assist2Id && e.assist2Id === e.playerId) throw new Error('Scorer and assists must be different players.');
        const oppGoalie = teamSide === 'home' ? g.awayGoalieId : teamSide === 'away' ? g.homeGoalieId : '';
        const rec: Record<string, unknown> = {
          eventType: e.eventType, period, elapsedSeconds: elapsed, teamId: e.teamId ?? '', playerId: e.playerId ?? '',
          enteredByEmail: a.email,
        };
        if (e.eventType === 'Goal') {
          requireStatus('Live', 'Overtime');
          if (!e.playerId) throw new Error('Select the goal scorer.');
          const events = await getEvents(g.id);
          const pens = activePenalties(g, events, s, absSeconds(period, elapsed, s));
          const own = pens.filter((x) => x.teamId === e.teamId).length, opp = pens.length - own;
          const strength = e.strength || (!oppGoalie ? 'Empty Net' : opp > own ? 'Power Play' : own > opp ? 'Shorthanded' : 'Even Strength');
          const assists = [nameOf(e.assist1Id), nameOf(e.assist2Id)].filter(Boolean);
          Object.assign(rec, { assist1Id: e.assist1Id ?? '', assist2Id: e.assist2Id ?? '', goalieId: oppGoalie ?? '', strength,
            summary: `${strength === 'Even Strength' ? '' : strength + ' '}Goal — ${nameOf(e.playerId)} ${assists.length ? `(${assists.join(', ')})` : '(unassisted)'}`.trim() });
        } else if (e.eventType === 'Shot') {
          requireStatus('Live', 'Overtime');
          Object.assign(rec, { goalieId: oppGoalie ?? '', summary: `Shot on goal — ${nameOf(e.playerId) || 'team'}, saved` });
        } else if (e.eventType === 'Penalty') {
          if (!e.playerId) throw new Error('Select the penalized player.');
          if (!e.infraction?.trim()) throw new Error('Enter the infraction.');
          const type = e.penaltyType || 'Minor';
          const mins = e.penaltyMinutes ?? ({ Minor: 2, 'Double Minor': 4, Major: 5, Misconduct: 10, 'Game Misconduct': 10 } as Record<string, number>)[type] ?? 2;
          Object.assign(rec, { penaltyType: type, penaltyMinutes: mins, infraction: e.infraction.trim(), summary: `${nameOf(e.playerId)} — ${e.infraction.trim()} (${type}, ${mins} min)` });
        } else if (e.eventType === 'Shootout Attempt') {
          requireStatus('Shootout');
          if (!e.playerId) throw new Error('Select the shooter.');
          Object.assign(rec, { period: 5, goalieId: oppGoalie ?? '', shootoutScored: !!e.shootoutScored, summary: `${nameOf(e.playerId)} — ${e.shootoutScored ? 'scores' : 'stopped'}` });
        } else if (e.eventType === 'Injury Stoppage') {
          Object.assign(rec, { playerId: '', summary: e.note?.trim() || 'Play stopped for an injury. Player attended to by medical staff.' });
        } else {
          const labels: Record<string, string> = { 'Official Review': 'Play under official review', 'Disallowed Goal': 'Goal disallowed after review', Delay: 'Delay in play', Timeout: 'Timeout', Note: 'Note' };
          Object.assign(rec, { summary: e.note?.trim() || labels[e.eventType] || e.eventType });
        }
        await logEvent(g.id, rec, input.clientKey);
        if (['Goal', 'Shot', 'Shootout Attempt'].includes(e.eventType)) g = await recomputeTotals(g);
        if (e.eventType === 'Goal') {
          if (period === 4) {
            await update({ clockRunning: false, clockRemaining: Math.round(clockRemaining(g, now)), clockAnchorAt: nowIso, statusNote: 'Overtime winner — finalize when ready' });
          }
          const [h, aw] = await Promise.all([teamName(g.homeTeamId), teamName(g.awayTeamId)]);
          await notifyFans(g, 'Goal', `Goal! ${teamSide === 'home' ? h : aw}`, `${String(rec.summary)} · ${aw} ${g.awayScore} – ${h} ${g.homeScore}`, [e.playerId!]);
        }
        if (e.eventType === 'Penalty') await notifyFans(g, 'Penalty', 'Penalty', String(rec.summary), [e.playerId!]);
        message = `${e.eventType} recorded`; break;
      }
      case 'voidEvent':
      case 'restoreEvent': {
        const ev = input.eventId ? await zite.gameEvents.findOne({ id: input.eventId }) : undefined;
        if (!ev || ev.gameId !== g.id) throw new Error('Event not found');
        if (g.status === 'Final') throw new Error('Reopen the game before correcting events.');
        const isVoid = input.action === 'voidEvent';
        if (isVoid && !input.reason?.trim()) throw new Error('A reason is required.');
        await zite.gameEvents.update({ id: ev.id, record: { isVoid, voidReason: isVoid ? input.reason : '' } as never });
        g = await recomputeTotals(g);
        await log(isVoid ? 'Voided event' : 'Restored event', { eventId: ev.id, summary: ev.summary, reason: input.reason });
        message = isVoid ? 'Event removed from the record' : 'Event restored'; break;
      }
      case 'editEventTime': {
        const ev = input.eventId ? await zite.gameEvents.findOne({ id: input.eventId }) : undefined;
        if (!ev || ev.gameId !== g.id) throw new Error('Event not found');
        if (g.status === 'Final') throw new Error('Reopen the game before correcting events.');
        const per = input.period ?? Number(ev.period);
        if (input.seconds === undefined || input.seconds < 0 || (per <= 4 && input.seconds > periodLength(per, s))) throw new Error('Invalid time.');
        await zite.gameEvents.update({ id: ev.id, record: { period: per, elapsedSeconds: input.seconds } as never });
        await log('Corrected event time', { eventId: ev.id, period: per, elapsedSeconds: input.seconds });
        message = 'Event time corrected'; break;
      }
      case 'reviewGoal': {
        const r = input.review;
        if (!r) throw new Error('Missing review details.');
        const goal = await zite.gameEvents.findOne({ id: r.goalEventId });
        if (!goal || goal.gameId !== g.id || goal.eventType !== 'Goal') throw new Error('Choose a goal from this game.');
        if (g.status === 'Canceled') throw new Error('This game was canceled.');
        const callOnIce = r.callOnIce === 'No Goal' ? 'No Goal' : 'Good Goal';
        const finalCall = r.callAfterReview === 'No Goal' || r.callAfterReview === 'Good Goal' ? r.callAfterReview : '';
        const reason = (r.reason ?? '').trim();
        const note = (r.note ?? '').trim();
        const official = (r.official ?? '').trim();
        const disallow = finalCall === 'No Goal';
        const wasVoid = !!goal.isVoid;
        if (g.status === 'Final' && wasVoid !== disallow) throw new Error('Reopen the game before changing whether the goal counts.');
        if (g.status === 'Final' && !finalCall) throw new Error('A final game needs a final call after review.');
        if (disallow && !reason) throw new Error('Choose the reason the goal was disallowed.');
        const existing = (await zite.goalReviews.findAll({ filters: { goalEventId: goal.id }, limit: 5 })).records[0];
        const [team, scorer] = await Promise.all([teamName(goal.teamId), goal.playerId ? zite.players.findOne({ id: goal.playerId }) : Promise.resolve(undefined)]);
        const scorerName = scorer?.fullName ?? '';
        const who = `${team} goal${scorerName ? ` by ${scorerName}` : ''}`;
        const per = Number(goal.period ?? 1);
        const callText = (c: string) => (c === 'No Goal' ? 'No goal' : 'Good goal');
        const calls = `Call on the ice: ${callText(callOnIce)}.${finalCall ? ` Call after review: ${callText(finalCall)}.` : ''}`;
        const summary = disallow
          ? `No goal — ${who} disallowed after official review (${reason}). ${calls}`
          : finalCall
            ? `Good goal — ${who} confirmed after official review${reason ? ` (${reason})` : ''}. ${calls}`
            : `Goal under official review — ${who}${reason ? ` (${reason})` : ''}. ${calls}`;
        // 1) The goal itself counts only while it stands.
        if (wasVoid !== disallow) {
          await zite.gameEvents.update({ id: goal.id, record: { isVoid: disallow, voidReason: disallow ? `Disallowed after official review — ${reason}` : '' } as never });
        }
        // 2) One public play-by-play entry per review (updated in place when the review is edited).
        const len = per <= 4 ? periodLength(per, s) : 99998;
        const evRec = { eventType: disallow ? 'Disallowed Goal' : 'Official Review', period: per, elapsedSeconds: Math.min(Number(goal.elapsedSeconds ?? 0) + 1, len), teamId: goal.teamId ?? '', summary, isVoid: false, enteredByEmail: a.email };
        let reviewEventId = existing?.reviewEventId ?? '';
        const existingEv = reviewEventId ? await zite.gameEvents.findOne({ id: reviewEventId }) : undefined;
        if (existingEv) await zite.gameEvents.update({ id: existingEv.id, record: evRec as never });
        else reviewEventId = (await logEvent(g.id, evRec)).id;
        // 3) The editable review record.
        const rec = {
          summary: `${periodLabel(per)} ${fmtClock(Number(goal.elapsedSeconds ?? 0))} — ${who}`, gameId: g.id, goalEventId: goal.id, reviewEventId, teamId: goal.teamId ?? '', scorerName,
          period: per, elapsedSeconds: Number(goal.elapsedSeconds ?? 0), callOnIce, callAfterReview: finalCall, reason, publicNote: note, reviewingOfficial: official, enteredByEmail: a.email,
        };
        if (existing) await zite.goalReviews.update({ id: existing.id, record: rec as never });
        else await zite.goalReviews.create({ record: rec as never });
        // 4) Scoreboard, shots and strength are recomputed from the goals that still count.
        g = await recomputeTotals(g);
        const pending = 'Goal under official review';
        if (g.status !== 'Final') {
          if (!finalCall) await update({ statusNote: pending });
          else if (g.statusNote === pending) await update({ statusNote: '' });
          if (per === 4 && ['Overtime', 'Live'].includes(g.status ?? '')) {
            await update({ statusNote: disallow ? 'Goal disallowed — overtime continues' : 'Overtime winner — finalize when ready' });
          }
        }
        if (disallow && (!existing || existing.callAfterReview !== 'No Goal')) {
          const [h, aw] = await Promise.all([teamName(g.homeTeamId), teamName(g.awayTeamId)]);
          await notifyFans(g, 'Goal', 'Goal disallowed', `${who} was disallowed after review · ${aw} ${g.awayScore} – ${h} ${g.homeScore}`);
        }
        await log(existing ? 'Edited goal review' : 'Reviewed goal', { goalEventId: goal.id, callOnIce, callAfterReview: finalCall || 'pending', reason });
        message = disallow ? 'Goal disallowed — removed from the scoreboard' : finalCall ? 'Goal confirmed after review' : 'Goal marked under review';
        break;
      }
      case 'recompute':
        g = await recomputeTotals(g);
        await log('Recomputed totals from event log'); message = 'Totals recomputed'; break;
      default:
        throw new Error('Unknown action');
    }
    return { ok: true, message };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { requirePerm } from '../lib/auth';

const POSITIONS: Record<string, string[]> = {
  '2-Official': ['Referee 1', 'Referee 2'],
  '3-Official': ['Referee 1', 'Linesperson 1', 'Linesperson 2'],
  '4-Official': ['Referee 1', 'Referee 2', 'Linesperson 1', 'Linesperson 2'],
};

export default createEndpoint({
  description: 'Officials assignment board: upcoming games, assignments, responses and scheduling conflicts',
  inputSchema: z.object({ days: z.number().default(30) }),
  outputSchema: z.object({
    games: z.array(z.object({
      id: z.string(), code: z.string(), label: z.string(), start: z.string(), venue: z.string(), system: z.string(),
      positions: z.array(z.string()),
      assignments: z.array(z.object({ id: z.string(), officialId: z.string(), officialName: z.string(), position: z.string(), status: z.string(), note: z.string(), conflicts: z.array(z.string()) })),
    })),
    officials: z.array(z.object({ id: z.string(), name: z.string(), type: z.string(), level: z.string(), unavailable: z.array(z.string()), upcomingCount: z.number() })),
    history: z.array(z.object({ id: z.string(), game: z.string(), official: z.string(), position: z.string(), status: z.string(), at: z.string() })),
  }),
  execute: async ({ input, context }) => {
    await requirePerm(context, 'assignments');
    const until = new Date(Date.now() + input.days * 86400000).toISOString();
    const since = new Date(Date.now() - 6 * 3600000).toISOString();
    const [gamesRes, teams, venues, offs, asg, avail] = await Promise.all([
      zite.sql({ query: `SELECT id FROM "Games" WHERE "scheduledStart" BETWEEN $1 AND $2 AND "status" NOT IN ('Canceled','Final') ORDER BY "scheduledStart" LIMIT 200`, params: [since, until] }),
      zite.teams.findAll({ limit: 200 }), zite.venues.findAll({ limit: 200 }), zite.officials.findAll({ limit: 1000 }),
      zite.officialAssignments.findAll({ limit: 2000 }), zite.officialAvailability.findAll({ limit: 2000 }),
    ]);
    const ids = gamesRes.rows.map((r) => String(r.id));
    const games = ids.length ? (await zite.games.findAll({ filters: { id: { in: ids } } as never, limit: 200 })).records : [];
    const tAbbr = new Map(teams.records.map((t) => [t.id, t.abbreviation ?? '']));
    const vName = new Map(venues.records.map((v) => [v.id, v.name ?? '']));
    const oName = new Map(offs.records.map((o) => [o.id, o.name ?? '']));
    const gameById = new Map(games.map((g) => [g.id, g]));
    const allGames = new Map<string, string>(); // gameId → start (for any assigned game)
    const activeAsg = asg.records.filter((x) => !['Declined', 'Replaced', 'Removed'].includes(x.status ?? ''));
    if (activeAsg.length) {
      const g2 = await zite.sql({ query: `SELECT id, "scheduledStart" AS s FROM "Games" WHERE "scheduledStart" > now() - interval '30 days'` });
      g2.rows.forEach((r) => allGames.set(String(r.id), r.s ? new Date(String(r.s)).toISOString() : ''));
    }
    const day = (iso: string) => (iso ? new Date(iso).toLocaleDateString('en-CA', { timeZone: 'America/Toronto' }) : '');
    const unavailable = (oid: string) => avail.records.filter((v) => v.officialId === oid && v.status === 'Unavailable').map((v) => v.date ?? '');
    const conflictsFor = (x: (typeof asg.records)[number], start: string) => {
      const out: string[] = [];
      if (unavailable(x.officialId ?? '').includes(day(start))) out.push('Marked unavailable this date');
      const others = activeAsg.filter((o) => o.officialId === x.officialId && o.gameId !== x.gameId && day(allGames.get(o.gameId ?? '') ?? '') === day(start));
      if (others.length) out.push('Assigned to another game the same day');
      const dupe = activeAsg.filter((o) => o.officialId === x.officialId && o.gameId === x.gameId && o.id !== x.id);
      if (dupe.length) out.push('Holds two positions in this game');
      return out;
    };
    return {
      games: games.sort((a, b) => String(a.scheduledStart).localeCompare(String(b.scheduledStart))).map((g) => {
        const sys = g.officiatingSystem || '4-Official';
        const start = g.scheduledStart ? new Date(g.scheduledStart).toISOString() : '';
        return {
          id: g.id, code: g.gameCode ?? '', label: `${tAbbr.get(g.awayTeamId ?? '') ?? '?'} @ ${tAbbr.get(g.homeTeamId ?? '') ?? '?'}`, start,
          venue: vName.get(g.venueId ?? '') ?? '', system: sys, positions: POSITIONS[sys] ?? POSITIONS['4-Official'],
          assignments: asg.records.filter((x) => x.gameId === g.id && !['Replaced', 'Removed'].includes(x.status ?? '')).map((x) => ({
            id: x.id, officialId: x.officialId ?? '', officialName: oName.get(x.officialId ?? '') ?? 'Unknown', position: x.position ?? '',
            status: x.status ?? 'Pending', note: x.responseNote ?? '', conflicts: x.status === 'Declined' ? [] : conflictsFor(x, start),
          })),
        };
      }),
      officials: offs.records.filter((o) => o.active !== false).map((o) => ({
        id: o.id, name: o.name ?? '', type: o.officialType ?? '', level: o.level ?? '', unavailable: unavailable(o.id),
        upcomingCount: activeAsg.filter((x) => x.officialId === o.id && (allGames.get(x.gameId ?? '') ?? '') > new Date().toISOString()).length,
      })).sort((a, b) => a.name.localeCompare(b.name)),
      history: asg.records.filter((x) => ['Replaced', 'Removed', 'Declined'].includes(x.status ?? '') || x.respondedAt)
        .map((x) => ({ id: x.id, game: gameById.get(x.gameId ?? '')?.gameCode ?? x.label ?? '', official: oName.get(x.officialId ?? '') ?? '', position: x.position ?? '', status: x.status ?? '', at: x.respondedAt ?? '' }))
        .sort((a, b) => b.at.localeCompare(a.at)).slice(0, 100),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getAccess } from '../lib/auth';
import { tickDueGames } from '../lib/engine';

const G = z.object({ id: z.string(), code: z.string(), home: z.string(), away: z.string(), homeScore: z.number(), awayScore: z.number(), status: z.string(), start: z.string(), note: z.string(), crew: z.number() });

export default createEndpoint({
  description: 'Admin dashboard: league totals, games, alerts and recent activity',
  inputSchema: z.object({}),
  outputSchema: z.object({
    counts: z.object({ teams: z.number(), players: z.number(), officials: z.number(), staff: z.number(), pendingAssignments: z.number(), newMessages: z.number() }),
    today: z.array(G), live: z.array(G), upcoming: z.array(G), recent: z.array(G),
    alerts: z.array(z.object({ level: z.string(), text: z.string(), link: z.string() })),
    activity: z.array(z.object({ action: z.string(), actor: z.string(), entity: z.string(), at: z.string() })),
  }),
  execute: async ({ context }) => {
    const a = await getAccess(context);
    if (!a.roles.length) throw new Error('No admin access.');
    await tickDueGames();
    const counts = await zite.sql({
      query: `SELECT (SELECT COUNT(*) FROM "Teams") AS teams, (SELECT COUNT(*) FROM "Players") AS players,
        (SELECT COUNT(*) FROM "Officials") AS officials, (SELECT COUNT(*) FROM "LeagueStaff") AS staff,
        (SELECT COUNT(*) FROM "OfficialAssignments" oa JOIN "Games" g ON g.id::text = oa."gameId" WHERE oa."status" = 'Pending' AND g."scheduledStart" > now()) AS pending,
        (SELECT COUNT(*) FROM "ContactMessages" WHERE "status" = 'New' OR "status" IS NULL) AS msgs`,
    });
    const { rows } = await zite.sql({
      query: `SELECT g.id, g."gameCode" AS code, h."abbreviation" AS home, aw."abbreviation" AS away, COALESCE(g."homeScore",0) AS hs, COALESCE(g."awayScore",0) AS vs,
        g."status" AS status, g."scheduledStart" AS start, COALESCE(g."statusNote", '') AS note, g."needsReview" AS review, g."reviewReason" AS rr,
        (SELECT COUNT(*) FROM "OfficialAssignments" oa WHERE oa."gameId" = g.id::text AND COALESCE(oa."status",'') <> 'Declined') AS crew
        FROM "Games" g LEFT JOIN "Teams" h ON h.id::text = g."homeTeamId" LEFT JOIN "Teams" aw ON aw.id::text = g."awayTeamId"
        WHERE g."scheduledStart" BETWEEN now() - interval '10 days' AND now() + interval '10 days' OR g."needsReview" = true
        OR g."status" IN ('Live','Intermission','Overtime','Shootout','Suspended','Warmup')
        ORDER BY g."scheduledStart"`,
    });
    const map = (r: Record<string, unknown>) => ({ id: String(r.id), code: String(r.code ?? ''), home: String(r.home ?? '?'), away: String(r.away ?? '?'), homeScore: Number(r.hs), awayScore: Number(r.vs), status: String(r.status ?? ''), start: r.start ? new Date(String(r.start)).toISOString() : '', note: String(r.note ?? ''), crew: Number(r.crew ?? 0) });
    const all = rows.map(map);
    const now = Date.now();
    const dayStart = new Date(); dayStart.setHours(0, 0, 0, 0);
    const dayEnd = dayStart.getTime() + 86400000;
    const live = all.filter((g) => ['Live', 'Intermission', 'Overtime', 'Shootout', 'Suspended', 'Warmup'].includes(g.status));
    const alerts: { level: string; text: string; link: string }[] = [];
    rows.filter((r) => r.review).forEach((r) => alerts.push({ level: 'high', text: `${r.code} needs review: ${r.rr || 'flagged'}`, link: `/games/${r.id}` }));
    const c = counts.rows[0] ?? {};
    if (Number(c.pending)) alerts.push({ level: 'medium', text: `${c.pending} official assignments awaiting a response`, link: '/assignments' });
    const declined = await zite.sql({ query: `SELECT COUNT(*) AS c FROM "OfficialAssignments" oa JOIN "Games" g ON g.id::text = oa."gameId" WHERE oa."status" = 'Declined' AND g."scheduledStart" > now()` });
    if (Number(declined.rows[0]?.c)) alerts.push({ level: 'high', text: `${declined.rows[0]?.c} declined assignments need a replacement official`, link: '/assignments' });
    const short = all.filter((g) => g.status === 'Scheduled' && Date.parse(g.start) > now && g.crew < 4);
    if (short.length) alerts.push({ level: Date.parse(short[0].start) - now < 2 * 86400000 ? 'high' : 'medium', text: `${short.length} upcoming game${short.length > 1 ? 's' : ''} without a full 4-official crew (next: ${short[0].code}, ${short[0].crew}/4)`, link: '/assignments' });
    if (Number(c.msgs)) alerts.push({ level: 'low', text: `${c.msgs} new contact messages`, link: '/messages' });
    const audits = await zite.sql({ query: `SELECT "action", "actorEmail" AS actor, "entityType" AS entity, "loggedAt" AS at FROM "AuditLogs" ORDER BY "loggedAt" DESC LIMIT 12` });
    return {
      counts: { teams: Number(c.teams), players: Number(c.players), officials: Number(c.officials), staff: Number(c.staff), pendingAssignments: Number(c.pending), newMessages: Number(c.msgs) },
      today: all.filter((g) => { const t = Date.parse(g.start); return t >= dayStart.getTime() && t < dayEnd; }),
      live,
      upcoming: all.filter((g) => g.status === 'Scheduled' && Date.parse(g.start) > now).slice(0, 8),
      recent: all.filter((g) => g.status === 'Final').reverse().slice(0, 8),
      alerts,
      activity: audits.rows.map((r) => ({ action: String(r.action ?? ''), actor: String(r.actor ?? ''), entity: String(r.entity ?? ''), at: r.at ? new Date(String(r.at)).toISOString() : '' })),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { requirePerm } from '../lib/auth';
import { absSeconds, activePenalties, elapsedInPeriod, getEvents, getSettings, tickGame } from '../lib/engine';

export default createEndpoint({
  description: 'Full game state for the game operations console (clock, events, rosters, penalties)',
  inputSchema: z.object({ gameId: z.string() }),
  outputSchema: z.object({
    serverNow: z.number(), game: z.record(z.any()), events: z.array(z.record(z.any())),
    homePlayers: z.array(z.record(z.any())), awayPlayers: z.array(z.record(z.any())),
    homeTeam: z.record(z.any()), awayTeam: z.record(z.any()), venueName: z.string(),
    reviews: z.array(z.record(z.any())),
    penalties: z.array(z.record(z.any())), currentAbs: z.number(), periodMinutes: z.number(), otMinutes: z.number(),
  }),
  execute: async ({ input, context }) => {
    await requirePerm(context, 'gameops', 'games');
    const s = await getSettings();
    const raw = await zite.games.findOne({ id: input.gameId });
    if (!raw) throw new Error('Game not found');
    const g = await tickGame(raw, s);
    const now = Date.now();
    const [events, home, away, hp, ap, venue, reviews] = await Promise.all([
      getEvents(g.id),
      zite.teams.findOne({ id: g.homeTeamId ?? '' }), zite.teams.findOne({ id: g.awayTeamId ?? '' }),
      zite.players.findAll({ filters: { teamId: g.homeTeamId ?? '' }, limit: 100 }),
      zite.players.findAll({ filters: { teamId: g.awayTeamId ?? '' }, limit: 100 }),
      g.venueId ? zite.venues.findOne({ id: g.venueId }) : Promise.resolve(undefined),
      zite.goalReviews.findAll({ filters: { gameId: g.id }, limit: 200 }),
    ]);
    const currentAbs = absSeconds(Number(g.period || 1), elapsedInPeriod(g, s, now), s);
    const byNum = (a: { jerseyNumber?: number }, b: { jerseyNumber?: number }) => Number(a.jerseyNumber ?? 0) - Number(b.jerseyNumber ?? 0);
    return {
      serverNow: now, game: g, events,
      homePlayers: hp.records.sort(byNum), awayPlayers: ap.records.sort(byNum),
      homeTeam: (home ?? {}) as Record<string, unknown>, awayTeam: (away ?? {}) as Record<string, unknown>, venueName: venue?.name ?? '',
      reviews: reviews.records as unknown as Record<string, unknown>[],
      penalties: activePenalties(g, events, s, currentAbs), currentAbs,
      periodMinutes: s.periodMinutes, otMinutes: s.otMinutes,
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { getAccess } from '../lib/auth';
import { getSettings, tickDueGames } from '../lib/engine';
import { goalieStats, skaterStats, standings } from '../lib/stats';

export default createEndpoint({
  description: 'Standings and statistics computed from final games, plus the league points configuration',
  inputSchema: z.object({ seasonId: z.string().optional() }),
  outputSchema: z.object({
    seasonId: z.string(),
    points: z.record(z.number()), tiebreakers: z.array(z.string()),
    standings: z.array(z.record(z.any())), skaters: z.array(z.record(z.any())), goalies: z.array(z.record(z.any())),
  }),
  execute: async ({ input, context }) => {
    const a = await getAccess(context);
    if (!a.roles.length) throw new Error('No admin access.');
    const s = await getSettings();
    await tickDueGames(s);
    const seasonId = input.seasonId || s.currentSeasonId;
    const [st, sk, gk] = await Promise.all([standings(seasonId, s), skaterStats(seasonId), goalieStats(seasonId)]);
    return { seasonId, points: s.points, tiebreakers: s.tiebreakers, standings: st, skaters: sk, goalies: gk };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getAccess } from '../lib/auth';

export default createEndpoint({
  description: 'Reference lists (teams, players, venues, seasons, officials, staff, games) for admin pickers',
  inputSchema: z.object({}),
  outputSchema: z.object({
    teams: z.array(z.object({ id: z.string(), name: z.string(), abbreviation: z.string(), primaryColor: z.string(), venueId: z.string() })),
    players: z.array(z.object({ id: z.string(), name: z.string(), teamId: z.string(), position: z.string(), num: z.number() })),
    venues: z.array(z.object({ id: z.string(), name: z.string() })),
    seasons: z.array(z.object({ id: z.string(), name: z.string(), isCurrent: z.boolean() })),
    officials: z.array(z.object({ id: z.string(), name: z.string(), type: z.string() })),
    staff: z.array(z.object({ id: z.string(), name: z.string() })),
    games: z.array(z.object({ id: z.string(), label: z.string(), start: z.string() })),
  }),
  execute: async ({ context }) => {
    const a = await getAccess(context);
    if (!a.roles.length) throw new Error('No admin access.');
    const [teams, players, venues, seasons, officials, staff, games] = await Promise.all([
      zite.teams.findAll({ limit: 500 }), zite.players.findAll({ limit: 2000 }), zite.venues.findAll({ limit: 500 }),
      zite.seasons.findAll({ limit: 200 }), zite.officials.findAll({ limit: 1000 }), zite.leagueStaff.findAll({ limit: 500 }),
      zite.games.findAll({ limit: 2000 }),
    ]);
    const abbr = new Map(teams.records.map((t) => [t.id, t.abbreviation ?? t.name ?? '']));
    return {
      teams: teams.records.map((t) => ({ id: t.id, name: t.name ?? '', abbreviation: t.abbreviation ?? '', primaryColor: t.primaryColor ?? '#0B2545', venueId: t.venueId ?? '' })).sort((x, y) => x.name.localeCompare(y.name)),
      players: players.records.map((p) => ({ id: p.id, name: p.fullName ?? '', teamId: p.teamId ?? '', position: p.position ?? '', num: Number(p.jerseyNumber ?? 0) })).sort((x, y) => x.name.localeCompare(y.name)),
      venues: venues.records.map((v) => ({ id: v.id, name: v.name ?? '' })),
      seasons: seasons.records.map((s) => ({ id: s.id, name: s.name ?? '', isCurrent: !!s.isCurrent })).sort((x, y) => y.name.localeCompare(x.name)),
      officials: officials.records.map((o) => ({ id: o.id, name: o.name ?? '', type: o.officialType ?? '' })).sort((x, y) => x.name.localeCompare(y.name)),
      staff: staff.records.map((s) => ({ id: s.id, name: s.name ?? '' })),
      games: games.records
        .map((g) => ({ id: g.id, label: `${g.gameCode ?? ''} · ${abbr.get(g.awayTeamId ?? '') ?? '?'} @ ${abbr.get(g.homeTeamId ?? '') ?? '?'}`, start: g.scheduledStart ?? '' }))
        .sort((x, y) => x.start.localeCompare(y.start)),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getAccess } from '../lib/auth';
import { audit } from '../lib/engine';

export default createEndpoint({
  description: 'Returns the signed-in staff member and their roles; bootstraps the first Super Administrator',
  inputSchema: z.object({ claimSuperAdmin: z.boolean().optional() }),
  outputSchema: z.object({
    email: z.string(), name: z.string(), roles: z.array(z.string()), perms: z.array(z.string()),
    teamId: z.string(), isSuper: z.boolean(), canBootstrap: z.boolean(),
  }),
  execute: async ({ input, context }) => {
    const { rows } = await zite.sql({ query: `SELECT COUNT(*) AS c FROM "UserRoles" WHERE "role" = 'Super Administrator'` });
    let canBootstrap = Number(rows[0]?.c ?? 0) === 0;
    if (input.claimSuperAdmin && canBootstrap && context.user?.email) {
      await zite.userRoles.create({ record: { email: context.user.email.toLowerCase(), role: 'Super Administrator', active: true } as never });
      await audit(context.user.email, 'Claimed initial Super Administrator role', 'userRoles', '', '');
      canBootstrap = false;
    }
    const a = await getAccess(context);
    return {
      ...a,
      name: [context.user?.firstName, context.user?.lastName].filter(Boolean).join(' ') || a.email,
      canBootstrap,
    };
  },
});

