import { Input } from '@project/components/ui/input';
import { Textarea } from '@project/components/ui/textarea';
import { Switch } from '@project/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { DatePicker, DateTimePicker } from '@project/components/ui/date-picker';
import { MarkdownEditor } from '@project/components/markdown-editor';
import type { Field } from '../lib/resources';
import { useApp } from '../lib/app-context';

const NONE = '__none__';

export default function FieldInput({ field, value, onChange, lockedTeamId }: { field: Field; value: unknown; onChange: (v: unknown) => void; lockedTeamId?: string }) {
  const { lookups } = useApp();
  const v = value ?? '';
  switch (field.type) {
    case 'textarea':
      return <Textarea rows={4} value={String(v)} onChange={(e) => onChange(e.target.value)} />;
    case 'markdown':
      return <MarkdownEditor content={String(v)} onChange={onChange} className="min-h-[220px] rounded-md border" />;
    case 'number':
      return <Input type="number" value={v === null ? '' : String(v)} onChange={(e) => onChange(e.target.value === '' ? '' : Number(e.target.value))} />;
    case 'bool':
      return <div className="flex h-10 items-center"><Switch checked={!!value} onCheckedChange={onChange} /></div>;
    case 'date':
      return <DatePicker value={v ? new Date(String(v).slice(0, 10) + 'T12:00:00') : undefined} onChange={(d) => onChange(d ? d.toISOString().slice(0, 10) : '')} />;
    case 'datetime':
      return <DateTimePicker value={v ? new Date(String(v)) : undefined} onChange={(d) => onChange(d ? d.toISOString() : '')} />;
    case 'select':
    case 'ref': {
      const opts = field.type === 'select'
        ? (field.options ?? []).map((o) => ({ id: o, name: o }))
        : ((lookups as unknown as Record<string, { id: string; name?: string; label?: string }[]> | null)?.[field.ref!] ?? []).map((x) => ({ id: x.id, name: x.name ?? x.label ?? '' }));
      const locked = field.ref === 'teams' && field.key === 'teamId' && !!lockedTeamId;
      return (
        <Select value={locked ? lockedTeamId : String(v) || NONE} onValueChange={(x) => onChange(x === NONE ? '' : x)} disabled={locked}>
          <SelectTrigger><SelectValue placeholder="Select…" /></SelectTrigger>
          <SelectContent className="max-h-72">
            {!field.required && <SelectItem value={NONE}>— None —</SelectItem>}
            {opts.filter((o) => o.id).map((o) => <SelectItem key={o.id} value={o.id}>{o.name}</SelectItem>)}
          </SelectContent>
        </Select>
      );
    }
    default:
      return <Input value={String(v)} onChange={(e) => onChange(e.target.value)} />;
  }
}

