type Row = Record<string, unknown> & { id: string };
const PAGE = 25;

export default function ResourcePage({ config, rowActions, headerExtra }: { config: ResourceConfig; rowActions?: (row: Row) => ReactNode; headerExtra?: ReactNode }) {
  const { lookups, refreshLookups } = useApp();
  const [rows, setRows] = useState<Row[] | null>(null);
  const [scopedTeam, setScopedTeam] = useState('');
  const [q, setQ] = useState('');
  const [sort, setSort] = useState<{ key: string; dir: 1 | -1 }>({ key: config.columns[0].key, dir: config.columns[0].type === 'datetime' && config.entity !== 'games' ? -1 : 1 });
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState<Row | 'new' | null>(null);
  const [deleting, setDeleting] = useState<Row | null>(null);

  const load = useCallback(async () => {
    try {
      const r = await adminList({ entity: config.entity });
      setRows(r.records as Row[]); setScopedTeam(r.scopedTeamId);
    } catch (e) { toast.error(errMsg(e)); setRows([]); }
  }, [config.entity]);
  useEffect(() => { setRows(null); setPage(0); load(); }, [load]);

  const display = useCallback((row: Row, key: string, ref?: string) => {
    const v = row[key];
    return ref ? refLabel(lookups, ref, v) : Array.isArray(v) ? v.join(', ') : String(v ?? '');
  }, [lookups]);

  const filtered = useMemo(() => {
    if (!rows) return [];
    const ql = q.toLowerCase();
    const list = rows.filter((r) => !ql || config.columns.some((c) => display(r, c.key, c.ref).toLowerCase().includes(ql)));
    return list.sort((a, b) => {
      const col = config.columns.find((c) => c.key === sort.key);
      const av = a[sort.key], bv = b[sort.key];
      if (typeof av === 'number' || typeof bv === 'number') return (Number(av ?? 0) - Number(bv ?? 0)) * sort.dir;
      if (col?.type === 'datetime' || col?.type === 'date') return String(av ?? '').localeCompare(String(bv ?? '')) * sort.dir;
      return display(a, sort.key, col?.ref).localeCompare(display(b, sort.key, col?.ref)) * sort.dir;
    });
  }, [rows, q, sort, config.columns, display]);
  const pages = Math.max(1, Math.ceil(filtered.length / PAGE));
  const visible = filtered.slice(page * PAGE, page * PAGE + PAGE);

  const remove = async () => {
    if (!deleting) return;
    try { await adminDelete({ entity: config.entity, id: deleting.id }); toast.success(`${config.singular} deleted`); setDeleting(null); load(); refreshLookups(); }
    catch (e) { toast.error(errMsg(e)); }
  };

  return (
    <div className="space-y-5">
      <PageHeader title={config.title} description={config.description}>
        {headerExtra}
        {!config.readOnly && !config.noCreate && !(config.entity === 'teams' && scopedTeam) && (
          <Button onClick={() => setEditing('new')}><Plus className="mr-1.5 h-4 w-4" />Add {config.singular.toLowerCase()}</Button>
        )}
      </PageHeader>
      <div className="relative max-w-sm">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <Input className="pl-9" placeholder={`Search ${config.title.toLowerCase()}…`} value={q} onChange={(e) => { setQ(e.target.value); setPage(0); }} />
      </div>
      <div className="overflow-hidden rounded-lg border bg-card shadow-sm">
        <Table>
          <TableHeader>
            <TableRow className="bg-muted/50">
              {config.columns.map((c) => (
                <TableHead key={c.key}>
                  <button className="inline-flex items-center gap-1 text-xs font-semibold uppercase tracking-wide" onClick={() => setSort((s) => ({ key: c.key, dir: s.key === c.key ? (s.dir * -1 as 1 | -1) : 1 }))}>
                    {c.label}<ArrowUpDown className="h-3 w-3 opacity-50" />
                  </button>
                </TableHead>
              ))}
              <TableHead className="w-px" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {!rows && [...Array(6)].map((_, i) => <TableRow key={i}><TableCell colSpan={config.columns.length + 1}><Skeleton className="h-5 w-full" /></TableCell></TableRow>)}
            {rows && visible.length === 0 && <TableRow><TableCell colSpan={config.columns.length + 1} className="py-12 text-center text-muted-foreground">No {config.title.toLowerCase()} found.</TableCell></TableRow>}
            {visible.map((r) => (
              <TableRow key={r.id}>
                {config.columns.map((c) => (
                  <TableCell key={c.key} className="max-w-[320px] truncate">
                    {c.type === 'bool' ? (r[c.key] ? <Badge variant="secondary">Yes</Badge> : <span className="text-muted-foreground">—</span>)
                      : c.type === 'datetime' ? fmtDateTime(r[c.key] as string)
                      : c.type === 'date' ? String(r[c.key] ?? '').slice(0, 10)
                      : c.type === 'badge' && r[c.key] ? <Badge variant="outline">{display(r, c.key)}</Badge>
                      : display(r, c.key, c.ref)}
                  </TableCell>
                ))}
                <TableCell className="whitespace-nowrap text-right">
                  {rowActions?.(r)}
                  {!config.readOnly && config.fields.length > 0 && <Button size="icon" variant="ghost" aria-label="Edit" onClick={() => setEditing(r)}><Pencil className="h-4 w-4" /></Button>}
                  {!config.readOnly && !['leagueSettings'].includes(config.entity) && !(config.entity === 'teams' && scopedTeam) && (
                    <Button size="icon" variant="ghost" aria-label="Delete" onClick={() => setDeleting(r)}><Trash2 className="h-4 w-4 text-destructive" /></Button>
                  )}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </div>
      <div className="flex items-center justify-between text-sm text-muted-foreground">
        <span>{filtered.length} records</span>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" disabled={page === 0} onClick={() => setPage((p) => p - 1)}>Previous</Button>
          <span>Page {page + 1} of {pages}</span>
          <Button variant="outline" size="sm" disabled={page >= pages - 1} onClick={() => setPage((p) => p + 1)}>Next</Button>
        </div>
      </div>
      {editing && <EditDialog config={config} row={editing === 'new' ? null : editing} scopedTeam={scopedTeam} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); load(); refreshLookups(); }} />}
      <AlertDialog open={!!deleting} onOpenChange={(o) => !o && setDeleting(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this {config.singular.toLowerCase()}?</AlertDialogTitle>
            <AlertDialogDescription>This can’t be undone. The deletion is recorded in the audit log.</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter><AlertDialogCancel>Cancel</AlertDialogCancel><AlertDialogAction onClick={remove} className="bg-destructive text-destructive-foreground">Delete</AlertDialogAction></AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

function EditDialog({ config, row, scopedTeam, onClose, onSaved }: { config: ResourceConfig; row: Row | null; scopedTeam: string; onClose: () => void; onSaved: () => void }) {
  const [form, setForm] = useState<Record<string, unknown>>(() => {
    if (row) return Object.fromEntries(config.fields.map((f) => [f.key, row[f.key] ?? (f.type === 'bool' ? false : '')]));
    const init: Record<string, unknown> = Object.fromEntries(config.fields.map((f) => [f.key, f.type === 'bool' ? ['active', 'isVisible', 'isPublic'].includes(f.key) : '']));
    if (scopedTeam && 'teamId' in init) init.teamId = scopedTeam;
    return init;
  });
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);

  const validate = () => {
    const e: Record<string, string> = {};
    for (const f of config.fields) {
      const v = form[f.key];
      if (f.required && (v === '' || v === null || v === undefined)) e[f.key] = `${f.label} is required`;
      if (f.type !== 'bool' && f.key.toLowerCase().includes('email') && typeof v === 'string' && v && !/^\S+@\S+\.\S+$/.test(String(v))) e[f.key] = 'Enter a valid email';
      if (f.key.toLowerCase().includes('color') && v && !/^#[0-9a-fA-F]{3,8}$/.test(String(v))) e[f.key] = 'Use a hex color like #0B2545';
    }
    if (config.entity === 'games' && form.homeTeamId && form.homeTeamId === form.awayTeamId) e.homeTeamId = 'Home and away must differ';
    setErrors(e);
    return Object.keys(e).length === 0;
  };
  const save = async () => {
    if (!validate()) return;
    setSaving(true);
    try { await adminSave({ entity: config.entity, id: row?.id, record: form }); toast.success(`${config.singular} saved`); onSaved(); }
    catch (e) { toast.error(errMsg(e)); } finally { setSaving(false); }
  };
  return (
    <Dialog open onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-h-[90vh] max-w-3xl overflow-y-auto">
        <DialogHeader><DialogTitle className="font-display text-2xl uppercase">{row ? 'Edit' : 'New'} {config.singular}</DialogTitle></DialogHeader>
        <div className="grid gap-4 sm:grid-cols-2">
          {config.fields.map((f) => (
            <div key={f.key} className={f.full || f.type === 'textarea' || f.type === 'markdown' ? 'sm:col-span-2' : ''}>
              <Label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-muted-foreground">{f.label}{f.required && <span className="text-accent"> *</span>}</Label>
              <FieldInput field={f} value={form[f.key]} lockedTeamId={scopedTeam} onChange={(v) => { setForm((s) => ({ ...s, [f.key]: v })); setErrors((x) => ({ ...x, [f.key]: '' })); }} />
              {f.help && !errors[f.key] && <p className="mt-1 text-xs text-muted-foreground">{f.help}</p>}
              {errors[f.key] && <p className="mt-1 text-xs text-destructive">{errors[f.key]}</p>}
            </div>
          ))}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button onClick={save} disabled={saving || Object.values(errors).some(Boolean)}>{saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Save</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { useState } from 'react';
import { Pause, Play, Flag, Timer, SkipForward, Ban, CalendarClock, RotateCcw, CheckCircle2, CircleSlash } from 'lucide-react';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Label } from '@project/components/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@project/components/ui/dialog';
import { DateTimePicker } from '@project/components/ui/date-picker';
import { toast } from 'sonner';
import { type Act, type Ops, parseClock } from '../../pages/GameConsole';
import { fmt } from './Scoreboard';

type Prompt = { action: string; title: string; reason?: boolean; reasonRequired?: boolean; date?: boolean; confirm: string; danger?: boolean } | null;

export default function ClockControls({ data, remaining, act }: { data: Ops; remaining: number; act: Act }) {
  const g = data.game;
  const st = String(g.status);
  const p = Number(g.period || 0);
  const [clockText, setClockText] = useState('');
  const [period, setPeriod] = useState('');
  const [intMin, setIntMin] = useState('');
  const [prompt, setPrompt] = useState<Prompt>(null);
  const [reason, setReason] = useState('');
  const [date, setDate] = useState<Date | undefined>();
  const inPlay = ['Live', 'Overtime'].includes(st);
  const pre = ['Scheduled', 'Warmup', 'Postponed'].includes(st);
  const active = ['Warmup', 'Live', 'Intermission', 'Overtime', 'Shootout', 'Suspended'].includes(st);

  const goalie = (side: 'home' | 'away') => {
    const players = (side === 'home' ? data.homePlayers : data.awayPlayers).filter((x) => x.position === 'G');
    const cur = String((side === 'home' ? g.homeGoalieId : g.awayGoalieId) || 'none');
    const team = side === 'home' ? data.homeTeam : data.awayTeam;
    return (
      <div>
        <Label className="mb-1 block text-xs uppercase text-muted-foreground">{String(team.abbreviation)} goalie</Label>
        <Select value={cur} onValueChange={(v) => act('setGoalie', { side, playerId: v === 'none' ? '' : v, clientKey: crypto.randomUUID() })} disabled={['Final', 'Canceled'].includes(st)}>
          <SelectTrigger><SelectValue /></SelectTrigger>
          <SelectContent>
            <SelectItem value="none">Empty net / not set</SelectItem>
            {players.map((x) => <SelectItem key={x.id} value={x.id}>#{x.jerseyNumber} {x.fullName}</SelectItem>)}
          </SelectContent>
        </Select>
      </div>
    );
  };

  const runPrompt = async () => {
    if (!prompt) return;
    if (prompt.reasonRequired && !reason.trim()) return toast.error('Please enter a reason.');
    if (prompt.date && !date && prompt.action === 'delayStart') return toast.error('Choose a new start time.');
    const ok = await act(prompt.action, { reason: reason || undefined, newStart: date?.toISOString() });
    if (ok) { setPrompt(null); setReason(''); setDate(undefined); }
  };

  return (
    <div className="space-y-4 rounded-lg border bg-card p-4 shadow-sm">
      <p className="flex items-center gap-2 font-display text-lg font-bold uppercase text-primary"><Timer className="h-4 w-4" />Clock & game status</p>
      <div className="flex flex-wrap gap-2">
        {pre && <Button onClick={() => act('start')}><Play className="mr-1.5 h-4 w-4" />Start game now</Button>}
        {['Scheduled', 'Postponed'].includes(st) && <Button variant="outline" onClick={() => act('warmup')}>Warmup</Button>}
        {['Scheduled', 'Warmup'].includes(st) && <Button variant="outline" onClick={() => setPrompt({ action: 'delayStart', title: 'Delay start', reason: true, date: true, confirm: 'Delay start' })}><CalendarClock className="mr-1.5 h-4 w-4" />Delay start</Button>}
        {inPlay && (g.clockRunning
          ? <Button size="lg" variant="secondary" onClick={() => act('pause')}><Pause className="mr-1.5 h-4 w-4" />Pause</Button>
          : <Button size="lg" onClick={() => act('resume')}><Play className="mr-1.5 h-4 w-4" />Resume</Button>)}
        {inPlay && <Button variant="outline" onClick={() => act('endPeriod')}><Flag className="mr-1.5 h-4 w-4" />End period</Button>}
        {inPlay && !g.clockRunning && <Button variant="outline" onClick={() => act('startIntermission', { minutes: intMin ? Number(intMin) : undefined })}>Start intermission</Button>}
        {st === 'Intermission' && <Button onClick={() => act('endIntermission')}><SkipForward className="mr-1.5 h-4 w-4" />Start next period</Button>}
        {['Live', 'Intermission'].includes(st) && p >= 3 && g.homeScore === g.awayScore && <Button variant="outline" onClick={() => act('startOvertime')}>Start overtime</Button>}
        {['Overtime', 'Live', 'Intermission'].includes(st) && p >= 4 && g.homeScore === g.awayScore && <Button variant="outline" onClick={() => act('startShootout')}>Start shootout</Button>}
        {active && st !== 'Suspended' && <Button variant="outline" onClick={() => setPrompt({ action: 'suspend', title: 'Suspend game', reason: true, reasonRequired: true, confirm: 'Suspend' })}><CircleSlash className="mr-1.5 h-4 w-4" />Suspend</Button>}
        {st === 'Suspended' && <Button onClick={() => act('resumeSuspended')}>Resume play</Button>}
        {active && <Button className="bg-accent text-accent-foreground hover:bg-accent/90" onClick={() => setPrompt({ action: 'finalize', title: 'Finalize game', confirm: 'Finalize' })}><CheckCircle2 className="mr-1.5 h-4 w-4" />Finalize</Button>}
        {st === 'Final' && <Button variant="outline" onClick={() => setPrompt({ action: 'reopen', title: 'Reopen final result', reason: true, reasonRequired: true, confirm: 'Reopen' })}><RotateCcw className="mr-1.5 h-4 w-4" />Reopen / correct</Button>}
        {['Scheduled', 'Warmup', 'Suspended'].includes(st) && <Button variant="outline" onClick={() => setPrompt({ action: 'postpone', title: 'Postpone game', reason: true, reasonRequired: true, date: true, confirm: 'Postpone' })}>Postpone</Button>}
        {['Scheduled', 'Warmup', 'Postponed', 'Suspended'].includes(st) && <Button variant="ghost" className="text-destructive" onClick={() => setPrompt({ action: 'cancel', title: 'Cancel game', reason: true, reasonRequired: true, confirm: 'Cancel game', danger: true })}><Ban className="mr-1.5 h-4 w-4" />Cancel</Button>}
      </div>
      {['Live', 'Overtime', 'Intermission', 'Suspended'].includes(st) && (
        <div className="grid gap-3 border-t pt-4 sm:grid-cols-3">
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Correct clock (now {fmt(remaining)})</Label>
            <div className="flex gap-2">
              <Input placeholder="mm:ss" value={clockText} onChange={(e) => setClockText(e.target.value)} />
              <Button variant="secondary" onClick={() => { const s = parseClock(clockText); if (s === null) return toast.error('Use mm:ss'); act('setClock', { seconds: s }).then((ok) => ok && setClockText('')); }}>Set</Button>
            </div>
          </div>
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Change period</Label>
            <div className="flex gap-2">
              <Select value={period} onValueChange={setPeriod}>
                <SelectTrigger><SelectValue placeholder={`Now: ${p}`} /></SelectTrigger>
                <SelectContent>{[1, 2, 3, 4].map((x) => <SelectItem key={x} value={String(x)}>{x === 4 ? 'Overtime' : `Period ${x}`}</SelectItem>)}</SelectContent>
              </Select>
              <Button variant="secondary" disabled={!period} onClick={() => act('setPeriod', { period: Number(period) }).then((ok) => ok && setPeriod(''))}>Set</Button>
            </div>
          </div>
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Intermission length (min)</Label>
            <Input type="number" min={1} max={30} placeholder="League default" value={intMin} onChange={(e) => setIntMin(e.target.value)} />
          </div>
        </div>
      )}
      <div className="grid gap-3 border-t pt-4 sm:grid-cols-2">{goalie('away')}{goalie('home')}</div>
      <Dialog open={!!prompt} onOpenChange={(o) => !o && setPrompt(null)}>
        <DialogContent>
          <DialogHeader><DialogTitle className="font-display text-2xl uppercase">{prompt?.title}</DialogTitle></DialogHeader>
          {prompt?.action === 'finalize' && <p className="text-sm text-muted-foreground">This stops the clock, locks the box score, credits goaltender decisions and the game-winning goal, and updates standings and statistics.</p>}
          {prompt?.reason && <div><Label className="mb-1 block text-xs uppercase text-muted-foreground">Reason{prompt.reasonRequired ? ' (required — saved to the audit log)' : ''}</Label><Input value={reason} onChange={(e) => setReason(e.target.value)} /></div>}
          {prompt?.date && <div><Label className="mb-1 block text-xs uppercase text-muted-foreground">{prompt.action === 'postpone' ? 'New date (optional — leave blank if TBA)' : 'New start time'}</Label><DateTimePicker value={date} onChange={setDate} /></div>}
          <DialogFooter>
            <Button variant="outline" onClick={() => setPrompt(null)}>Back</Button>
            <Button className={prompt?.danger ? 'bg-destructive text-destructive-foreground' : ''} onClick={runPrompt}>{prompt?.confirm}</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { Flag, Loader2, PlusCircle } from 'lucide-react';
import { toast } from 'sonner';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Label } from '@project/components/ui/label';
import { Tabs, TabsList, TabsTrigger } from '@project/components/ui/tabs';
import { Switch } from '@project/components/ui/switch';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { type Act, type Ops, parseClock } from '../../pages/GameConsole';

const TYPES = ['Goal', 'Shot', 'Penalty', 'Shootout Attempt', 'Other'] as const;
const OTHER = ['Injury Stoppage', 'Official Review', 'Delay', 'Timeout', 'Note'];
const INFRACTIONS = ['Tripping', 'Hooking', 'Slashing', 'Interference', 'Roughing', 'Holding', 'Cross-checking', 'High-sticking', 'Boarding', 'Charging', 'Too many men', 'Delay of game', 'Unsportsmanlike conduct', 'Fighting', 'Head contact'];
const NONE = 'none';

export default function EventEntry({ data, act, onReview }: { data: Ops; act: Act; onReview: () => void }) {
  const g = data.game;
  const [type, setType] = useState<(typeof TYPES)[number]>('Goal');
  const [side, setSide] = useState<'home' | 'away'>('home');
  const [f, setF] = useState<Record<string, string>>({});
  const [scored, setScored] = useState(false);
  const [busy, setBusy] = useState(false);
  const [key, setKey] = useState(() => crypto.randomUUID());
  const teamId = side === 'home' ? String(g.homeTeamId) : String(g.awayTeamId);
  const roster = useMemo(() => (side === 'home' ? data.homePlayers : data.awayPlayers), [side, data]);
  const skaters = roster.filter((p) => type === 'Shootout Attempt' || p.position !== 'G' || type === 'Penalty');
  const set = (k: string, v: string) => setF((s) => ({ ...s, [k]: v === NONE ? '' : v }));

  const pickPlayer = (k: string, label: string, exclude: string[] = []) => (
    <div>
      <Label className="mb-1 block text-xs uppercase text-muted-foreground">{label}</Label>
      <Select value={f[k] || NONE} onValueChange={(v) => set(k, v)}>
        <SelectTrigger><SelectValue /></SelectTrigger>
        <SelectContent className="max-h-72">
          <SelectItem value={NONE}>— None —</SelectItem>
          {skaters.filter((p) => !exclude.includes(p.id)).map((p) => <SelectItem key={p.id} value={p.id}>#{p.jerseyNumber} {p.fullName} ({p.position})</SelectItem>)}
        </SelectContent>
      </Select>
    </div>
  );

  const submit = async () => {
    const eventType = type === 'Other' ? f.otherType || '' : type;
    if (!eventType) return toast.error('Choose the event type.');
    if (['Goal', 'Penalty', 'Shootout Attempt'].includes(eventType) && !f.playerId) return toast.error('Select a player.');
    if (eventType === 'Penalty' && !f.infraction) return toast.error('Choose the infraction.');
    let elapsedSeconds: number | undefined;
    if (f.time) {
      const s = parseClock(f.time);
      if (s === null) return toast.error('Time must be mm:ss (time elapsed in the period).');
      elapsedSeconds = s;
    }
    setBusy(true);
    const ok = await act('recordEvent', {
      clientKey: key,
      event: {
        eventType, teamId: ['Injury Stoppage', 'Official Review', 'Delay', 'Note'].includes(eventType) ? undefined : teamId,
        playerId: f.playerId || undefined, assist1Id: f.assist1Id || undefined, assist2Id: f.assist2Id || undefined,
        strength: f.strength || undefined, penaltyType: f.penaltyType || undefined, infraction: f.infraction || undefined,
        shootoutScored: scored, note: f.note || undefined, elapsedSeconds,
      },
    });
    setBusy(false);
    if (ok) { setF({}); setScored(false); setKey(crypto.randomUUID()); }
  };

  const quickShot = async (s: 'home' | 'away') => {
    await act('recordEvent', { clientKey: crypto.randomUUID(), event: { eventType: 'Shot', teamId: String(s === 'home' ? g.homeTeamId : g.awayTeamId) } });
  };

  return (
    <div className="space-y-4 rounded-lg border bg-card p-4 shadow-sm">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="flex items-center gap-2 font-display text-lg font-bold uppercase text-primary"><PlusCircle className="h-4 w-4" />Record event</p>
        <div className="flex gap-2">
          <Button size="sm" variant="secondary" onClick={() => quickShot('away')}>+ {String(data.awayTeam.abbreviation)} shot</Button>
          <Button size="sm" variant="secondary" onClick={() => quickShot('home')}>+ {String(data.homeTeam.abbreviation)} shot</Button>
        </div>
      </div>
      <Button variant="outline" className="w-full border-accent/50 text-accent hover:bg-accent/10" onClick={onReview}><Flag className="mr-2 h-4 w-4" />Review / disallow a goal</Button>
      <Tabs value={type} onValueChange={(v) => { setType(v as typeof type); setF({}); }}>
        <TabsList className="flex h-auto flex-wrap">{TYPES.map((t) => <TabsTrigger key={t} value={t}>{t === 'Shootout Attempt' ? 'Shootout' : t}</TabsTrigger>)}</TabsList>
      </Tabs>
      {type !== 'Other' && (
        <div className="grid grid-cols-2 gap-2">
          {(['away', 'home'] as const).map((s) => {
            const t = s === 'home' ? data.homeTeam : data.awayTeam;
            return (
              <button key={s} onClick={() => { setSide(s); setF({}); }} className={`rounded-md border-2 px-3 py-2 font-display text-lg font-bold uppercase transition ${side === s ? 'border-primary bg-primary text-primary-foreground' : 'border-border hover:border-primary/40'}`}>
                {String(t.abbreviation)} <span className="text-xs font-medium opacity-70">{s}</span>
              </button>
            );
          })}
        </div>
      )}
      <div className="grid gap-3 sm:grid-cols-2">
        {type === 'Goal' && <>
          {pickPlayer('playerId', 'Scorer *')}
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Strength</Label>
            <Select value={f.strength || NONE} onValueChange={(v) => set('strength', v)}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>
                <SelectItem value={NONE}>Auto (from penalties)</SelectItem>
                {['Even Strength', 'Power Play', 'Shorthanded', 'Empty Net', 'Penalty Shot'].map((x) => <SelectItem key={x} value={x}>{x}</SelectItem>)}
              </SelectContent>
            </Select>
          </div>
          {pickPlayer('assist1Id', 'Primary assist', [f.playerId])}
          {pickPlayer('assist2Id', 'Secondary assist', [f.playerId, f.assist1Id])}
        </>}
        {type === 'Shot' && pickPlayer('playerId', 'Shooter (optional)')}
        {type === 'Penalty' && <>
          {pickPlayer('playerId', 'Player *')}
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Infraction *</Label>
            <Select value={f.infraction || NONE} onValueChange={(v) => set('infraction', v)}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent className="max-h-72"><SelectItem value={NONE}>— Choose —</SelectItem>{INFRACTIONS.map((x) => <SelectItem key={x} value={x}>{x}</SelectItem>)}</SelectContent>
            </Select>
          </div>
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Type</Label>
            <Select value={f.penaltyType || 'Minor'} onValueChange={(v) => set('penaltyType', v)}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent>{['Minor', 'Double Minor', 'Major', 'Misconduct', 'Game Misconduct'].map((x) => <SelectItem key={x} value={x}>{x}</SelectItem>)}</SelectContent>
            </Select>
          </div>
        </>}
        {type === 'Shootout Attempt' && <>
          {pickPlayer('playerId', 'Shooter *')}
          <div className="flex items-end gap-3 pb-2"><Switch checked={scored} onCheckedChange={setScored} /><span className="text-sm font-medium">{scored ? 'Scored' : 'Stopped'}</span></div>
        </>}
        {type === 'Other' && <>
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Event type *</Label>
            <Select value={f.otherType || NONE} onValueChange={(v) => set('otherType', v)}>
              <SelectTrigger><SelectValue /></SelectTrigger>
              <SelectContent><SelectItem value={NONE}>— Choose —</SelectItem>{OTHER.map((x) => <SelectItem key={x} value={x}>{x}</SelectItem>)}</SelectContent>
            </Select>
          </div>
          {['Timeout'].includes(f.otherType ?? '') && (
            <div>
              <Label className="mb-1 block text-xs uppercase text-muted-foreground">Team</Label>
              <Select value={side} onValueChange={(v) => setSide(v as 'home' | 'away')}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent><SelectItem value="away">{String(data.awayTeam.name)}</SelectItem><SelectItem value="home">{String(data.homeTeam.name)}</SelectItem></SelectContent>
              </Select>
            </div>
          )}
          <div className="sm:col-span-2">
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Public description</Label>
            <Input value={f.note ?? ''} onChange={(e) => set('note', e.target.value)} placeholder={f.otherType === 'Injury Stoppage' ? 'Keep it general — e.g. “Play stopped for an injury.” No medical details.' : 'Optional'} />
          </div>
        </>}
        <div>
          <Label className="mb-1 block text-xs uppercase text-muted-foreground">Time elapsed in period (optional)</Label>
          <Input placeholder="mm:ss — defaults to the game clock" value={f.time ?? ''} onChange={(e) => set('time', e.target.value)} />
        </div>
      </div>
      <Button className="w-full" size="lg" onClick={submit} disabled={busy}>{busy && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Record {type === 'Other' ? f.otherType || 'event' : type.toLowerCase()}</Button>
    </div>
  );
}

import { useState } from 'react';
import { Clock, Flag, ListOrdered, RotateCcw, Trash2 } from 'lucide-react';
import { toast } from 'sonner';
import { Button } from '@project/components/ui/button';
import { Badge } from '@project/components/ui/badge';
import { Input } from '@project/components/ui/input';
import { Label } from '@project/components/ui/label';
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@project/components/ui/dialog';
import { type Act, type Ops, parseClock } from '../../pages/GameConsole';
import { fmt, periodLabel } from './Scoreboard';

const COLORS: Record<string, string> = { Goal: 'bg-accent text-accent-foreground', Penalty: 'bg-amber-500 text-white', 'Game Final': 'bg-primary text-primary-foreground' };

export default function EventLog({ data, act, onReview }: { data: Ops; act: Act; onReview: (goalId: string) => void }) {
  const [voiding, setVoiding] = useState<Record<string, unknown> | null>(null);
  const [timing, setTiming] = useState<Record<string, unknown> | null>(null);
  const [text, setText] = useState('');
  const events = [...data.events].reverse();
  const abbr = (tid: unknown) => (tid === data.game.homeTeamId ? data.homeTeam.abbreviation : tid === data.game.awayTeamId ? data.awayTeam.abbreviation : '');
  const final = data.game.status === 'Final';
  const reviewOf = (id: unknown) => data.reviews.find((r) => String(r.goalEventId) === String(id));
  const callText = (c: unknown) => (c === 'No Goal' ? 'No goal' : c === 'Good Goal' ? 'Good goal' : 'Under review');
  return (
    <div className="rounded-lg border bg-card shadow-sm">
      <p className="flex items-center justify-between gap-2 border-b px-4 py-3 font-display text-lg font-bold uppercase text-primary">
        <span className="flex items-center gap-2"><ListOrdered className="h-4 w-4" />Game history ({data.events.length})</span>
        <Button size="sm" variant="ghost" onClick={() => act('recompute')}>Recompute totals</Button>
      </p>
      {final && <p className="border-b bg-muted/50 px-4 py-2 text-xs text-muted-foreground">This game is final. Reopen it to correct events.</p>}
      <ul className="max-h-[900px] divide-y overflow-y-auto">
        {events.length === 0 && <li className="p-6 text-center text-sm text-muted-foreground">No events yet.</li>}
        {events.map((e) => (
          <li key={String(e.id)} className={`flex items-start gap-3 px-4 py-2.5 text-sm ${e.isVoid ? 'opacity-50' : ''}`}>
            <span className="w-16 shrink-0 font-mono text-xs text-muted-foreground">{Number(e.period) >= 5 ? 'SO' : `${periodLabel(Number(e.period))} ${Number(e.elapsedSeconds) > 10000 ? '' : fmt(Number(e.elapsedSeconds))}`}</span>
            <div className="min-w-0 flex-1">
              <div className="flex flex-wrap items-center gap-1.5">
                <Badge className={COLORS[String(e.eventType)] ?? ''} variant={COLORS[String(e.eventType)] ? 'default' : 'outline'}>{String(e.eventType)}</Badge>
                {abbr(e.teamId) ? <span className="text-xs font-bold">{String(abbr(e.teamId))}</span> : null}
                {e.isGameWinner ? <Badge variant="secondary">GWG</Badge> : null}
              </div>
              <p className={`mt-0.5 ${e.isVoid ? 'line-through' : ''}`}>{String(e.summary ?? '')}</p>
              {e.isVoid ? <p className="text-xs text-destructive">Removed: {String(e.voidReason ?? '')}</p> : null}
              {e.eventType === 'Goal' && reviewOf(e.id) ? (
                <p className="mt-1 rounded bg-accent/10 px-2 py-1 text-xs">
                  <b>Official review</b> · On the ice: {callText(reviewOf(e.id)?.callOnIce)} → After review: <b>{callText(reviewOf(e.id)?.callAfterReview)}</b>
                  {reviewOf(e.id)?.reason ? ` · ${String(reviewOf(e.id)?.reason)}` : ''}
                </p>
              ) : null}
              {e.enteredByEmail ? <p className="text-[11px] text-muted-foreground">by {String(e.enteredByEmail)}</p> : null}
            </div>
            <div className="flex shrink-0">
              {e.eventType === 'Goal' && (
                <Button size="icon" variant="ghost" aria-label={reviewOf(e.id) ? 'Edit review' : 'Review or disallow goal'} title={reviewOf(e.id) ? 'Edit review' : 'Review / disallow goal'} onClick={() => onReview(String(e.id))}><Flag className="h-3.5 w-3.5 text-accent" /></Button>
              )}
              {!final && (<>
                <Button size="icon" variant="ghost" aria-label="Edit time" onClick={() => { setTiming(e); setText(fmt(Number(e.elapsedSeconds))); }}><Clock className="h-3.5 w-3.5" /></Button>
                {e.isVoid
                  ? (reviewOf(e.id) ? null : <Button size="icon" variant="ghost" aria-label="Restore" onClick={() => act('restoreEvent', { eventId: String(e.id) })}><RotateCcw className="h-3.5 w-3.5" /></Button>)
                  : <Button size="icon" variant="ghost" aria-label="Remove" onClick={() => { setVoiding(e); setText(''); }}><Trash2 className="h-3.5 w-3.5 text-destructive" /></Button>}
              </>)}
            </div>
          </li>
        ))}
      </ul>
      <Dialog open={!!voiding} onOpenChange={(o) => !o && setVoiding(null)}>
        <DialogContent>
          <DialogHeader><DialogTitle className="font-display text-2xl uppercase">Remove event</DialogTitle></DialogHeader>
          <p className="text-sm text-muted-foreground">{String(voiding?.summary ?? '')}. The event stays in the audit trail but no longer counts toward scores or stats.</p>
          <div><Label className="mb-1 block text-xs uppercase text-muted-foreground">Reason (required)</Label><Input value={text} onChange={(e) => setText(e.target.value)} /></div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setVoiding(null)}>Back</Button>
            <Button className="bg-destructive text-destructive-foreground" onClick={async () => { if (!text.trim()) return toast.error('Enter a reason'); if (await act('voidEvent', { eventId: String(voiding?.id), reason: text })) setVoiding(null); }}>Remove</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
      <Dialog open={!!timing} onOpenChange={(o) => !o && setTiming(null)}>
        <DialogContent>
          <DialogHeader><DialogTitle className="font-display text-2xl uppercase">Correct event time</DialogTitle></DialogHeader>
          <div><Label className="mb-1 block text-xs uppercase text-muted-foreground">Time elapsed in {periodLabel(Number(timing?.period))} (mm:ss)</Label><Input value={text} onChange={(e) => setText(e.target.value)} /></div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setTiming(null)}>Back</Button>
            <Button onClick={async () => { const s = parseClock(text); if (s === null) return toast.error('Use mm:ss'); if (await act('editEventTime', { eventId: String(timing?.id), seconds: s, period: Number(timing?.period) })) setTiming(null); }}>Save</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import { Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Label } from '@project/components/ui/label';
import { Textarea } from '@project/components/ui/textarea';
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from '@project/components/ui/dialog';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import type { Act, Ops } from '../../pages/GameConsole';
import { fmt, periodLabel } from './Scoreboard';

export const REVIEW_REASONS = [
  'Goaltender interference', 'Offside (zone entry)', 'Hand pass', 'High stick', 'Kicking motion', 'Puck did not cross the goal line',
  'Net displaced before the puck crossed', 'Too many men on the ice', 'Incidental contact on the goaltender', 'Other',
];
const PENDING = 'pending';

/** `goalId` undefined → the operator picks the goal; a goal id → reviewing that goal (existing review is loaded for editing). */
export default function GoalReviewDialog({ data, act, open, goalId, onClose }: { data: Ops; act: Act; open: boolean; goalId?: string; onClose: () => void }) {
  const [goal, setGoal] = useState('');
  const [onIce, setOnIce] = useState('Good Goal');
  const [after, setAfter] = useState('No Goal');
  const [reason, setReason] = useState('');
  const [otherReason, setOtherReason] = useState('');
  const [official, setOfficial] = useState('');
  const [note, setNote] = useState('');
  const [busy, setBusy] = useState(false);

  const abbr = (tid: unknown) => (tid === data.game.homeTeamId ? data.homeTeam.abbreviation : data.awayTeam.abbreviation);
  const goals = useMemo(() => data.events.filter((e) => e.eventType === 'Goal'), [data.events]);
  const reviewFor = (id: string) => data.reviews.find((r) => String(r.goalEventId) === id);
  const final = data.game.status === 'Final';

  // Load the existing review (or sensible defaults) whenever the dialog opens or a different goal is chosen.
  useEffect(() => {
    if (!open) return;
    setGoal(goalId ?? '');
  }, [open, goalId]);
  useEffect(() => {
    if (!open) return;
    const r = goal ? reviewFor(goal) : undefined;
    if (r) {
      setOnIce(String(r.callOnIce || 'Good Goal'));
      setAfter(String(r.callAfterReview || PENDING));
      const rs = String(r.reason ?? '');
      if (!rs) { setReason(''); setOtherReason(''); } else if (REVIEW_REASONS.includes(rs)) { setReason(rs); setOtherReason(''); } else { setReason('Other'); setOtherReason(rs); }
      setOfficial(String(r.reviewingOfficial ?? ''));
      setNote(String(r.publicNote ?? ''));
    } else {
      setOnIce('Good Goal'); setAfter('No Goal'); setReason(''); setOtherReason(''); setOfficial(''); setNote('');
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, goal]);

  const finalReason = reason === 'Other' ? otherReason.trim() : reason;
  const disallow = after === 'No Goal';
  const existing = goal ? reviewFor(goal) : undefined;

  const submit = async () => {
    if (!goal) return toast.error('Choose the goal under review.');
    if (disallow && !finalReason) return toast.error('Choose the reason the goal was disallowed.');
    setBusy(true);
    const ok = await act('reviewGoal', {
      review: { goalEventId: goal, callOnIce: onIce, callAfterReview: after === PENDING ? '' : after, reason: finalReason, note: note.trim(), official: official.trim() },
    });
    setBusy(false);
    if (ok) onClose();
  };

  return (
    <Dialog open={open} onOpenChange={(o) => !o && onClose()}>
      <DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-lg">
        <DialogHeader>
          <DialogTitle className="font-display text-2xl uppercase">{existing ? 'Edit official review' : 'Official review'}</DialogTitle>
          <DialogDescription>
            Recording “No goal” takes the goal off the scoreboard, shots and player stats automatically. Fans see both calls in the Game Center.
          </DialogDescription>
        </DialogHeader>
        <div className="space-y-4">
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Goal under review</Label>
            <Select value={goal || undefined} onValueChange={setGoal} disabled={!!goalId}>
              <SelectTrigger><SelectValue placeholder={goals.length ? 'Choose a goal' : 'No goals recorded yet'} /></SelectTrigger>
              <SelectContent className="max-h-72">
                {goals.map((e) => (
                  <SelectItem key={String(e.id)} value={String(e.id)}>
                    {periodLabel(Number(e.period))} {fmt(Number(e.elapsedSeconds))} · {String(abbr(e.teamId))} · {String(e.summary ?? '').replace(/^.*?Goal — /, '')}{reviewFor(String(e.id)) ? ' (reviewed)' : ''}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="grid gap-3 sm:grid-cols-2">
            <div>
              <Label className="mb-1 block text-xs uppercase text-muted-foreground">Call on the ice</Label>
              <Select value={onIce} onValueChange={setOnIce}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent><SelectItem value="Good Goal">Good goal</SelectItem><SelectItem value="No Goal">No goal</SelectItem></SelectContent>
              </Select>
            </div>
            <div>
              <Label className="mb-1 block text-xs uppercase text-muted-foreground">Call after review</Label>
              <Select value={after} onValueChange={setAfter}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  <SelectItem value="No Goal">No goal — disallowed</SelectItem>
                  <SelectItem value="Good Goal">Good goal — stands</SelectItem>
                  {!final && <SelectItem value={PENDING}>Still under review</SelectItem>}
                </SelectContent>
              </Select>
            </div>
          </div>
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Reason{disallow ? ' *' : ' (optional)'}</Label>
            <Select value={reason || undefined} onValueChange={setReason}>
              <SelectTrigger><SelectValue placeholder="Choose a reason" /></SelectTrigger>
              <SelectContent>{REVIEW_REASONS.map((x) => <SelectItem key={x} value={x}>{x}</SelectItem>)}</SelectContent>
            </Select>
            {reason === 'Other' && <Input className="mt-2" placeholder="Describe the reason" value={otherReason} onChange={(e) => setOtherReason(e.target.value)} />}
          </div>
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Referee announcing the decision (optional)</Label>
            <Input value={official} onChange={(e) => setOfficial(e.target.value)} placeholder="e.g. Referee Marcus Delaney" />
          </div>
          <div>
            <Label className="mb-1 block text-xs uppercase text-muted-foreground">Public note (optional)</Label>
            <Textarea rows={2} value={note} onChange={(e) => setNote(e.target.value)} placeholder="Shown to fans with the review. Keep it factual." />
          </div>
          {final && <p className="rounded-md border bg-muted/50 p-2 text-xs text-muted-foreground">This game is final. You can edit the wording, but reopen the game first to change whether the goal counts.</p>}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Cancel</Button>
          <Button onClick={submit} disabled={busy || !goals.length}>{busy && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}{existing ? 'Save review' : disallow ? 'Disallow goal' : 'Save review'}</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import { Badge } from '@project/components/ui/badge';
import type { Ops } from '../../pages/GameConsole';

export const periodLabel = (p: number) => (p === 4 ? 'OT' : p >= 5 ? 'SO' : ['—', '1st', '2nd', '3rd'][p] ?? '—');
export const fmt = (sec: number) => { const t = Math.max(0, Math.ceil(sec)); return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`; };

export default function Scoreboard({ data, remaining }: { data: Ops; remaining: number }) {
  const g = data.game;
  const pmin = data.periodMinutes;
  const p = Number(g.period || 0);
  const len = p <= 3 ? pmin * 60 : p === 4 ? data.otMinutes * 60 : 0;
  const before = p <= 1 ? 0 : p <= 4 ? (Math.min(p - 1, 3) * pmin * 60) : 3 * pmin * 60 + data.otMinutes * 60;
  const nowAbs = before + (len - remaining);
  const pens = data.penalties.map((x) => ({ ...x, left: Number(x.expiresAbs) - nowAbs })).filter((x) => x.left > 0);
  const homeP = pens.filter((x) => x.teamId === g.homeTeamId).length, awayP = pens.length - homeP;
  const pp = homeP < awayP ? 'home' : awayP < homeP ? 'away' : null;
  const live = ['Live', 'Overtime'].includes(g.status ?? '');
  const side = (team: Record<string, unknown>, score: number, shots: number, isPP: boolean, so: number) => (
    <div className="flex flex-1 flex-col items-center gap-2 text-center">
      <div className="flex h-16 w-16 items-center justify-center rounded-full border-4 font-display text-xl font-extrabold text-white" style={{ background: String(team.primaryColor || '#0B2545'), borderColor: String(team.secondaryColor || '#fff') }}>
        {String(team.abbreviation ?? '?')}
      </div>
      <p className="font-display text-lg font-bold uppercase leading-tight text-white/90">{String(team.name ?? '')}</p>
      <p className="font-display text-7xl font-extrabold leading-none text-white tabular">{score}</p>
      <p className="text-xs uppercase tracking-widest text-white/60">SOG {shots}{p >= 5 ? ` · SO ${so}` : ''}</p>
      {isPP && <Badge className="bg-accent text-accent-foreground">POWER PLAY</Badge>}
    </div>
  );
  return (
    <div className="overflow-hidden rounded-xl bg-primary text-primary-foreground shadow-lg">
      <div className="flex items-stretch gap-2 px-4 py-6 sm:px-10">
        {side(data.awayTeam, Number(g.awayScore ?? 0), Number(g.awayShots ?? 0), pp === 'away', Number(g.shootoutAwayGoals ?? 0))}
        <div className="flex min-w-[150px] flex-col items-center justify-center gap-2">
          <Badge variant="outline" className={`border-white/30 uppercase text-white ${live ? 'bg-accent' : ''}`}>{live && <span className="mr-1.5 h-1.5 w-1.5 animate-pulse rounded-full bg-white" />}{g.status}</Badge>
          <p className="font-display text-xl font-bold uppercase text-white/80">{p ? periodLabel(p) : 'Pre-game'}</p>
          <p className={`font-mono text-5xl font-bold tabular ${g.clockRunning ? 'text-white' : 'text-white/60'}`}>
            {g.status === 'Intermission' && g.intermissionEndsAt ? fmt(Math.max(0, (Date.parse(g.intermissionEndsAt) - Date.now()) / 1000)) : fmt(remaining)}
          </p>
          <p className="text-[11px] uppercase tracking-widest text-white/50">{g.status === 'Intermission' ? 'Intermission' : g.clockRunning ? 'Clock running' : 'Clock stopped'}</p>
          {g.statusNote && <p className="max-w-[180px] text-center text-xs text-white/70">{g.statusNote}</p>}
        </div>
        {side(data.homeTeam, Number(g.homeScore ?? 0), Number(g.homeShots ?? 0), pp === 'home', Number(g.shootoutHomeGoals ?? 0))}
      </div>
      {pens.length > 0 && (
        <div className="flex flex-wrap justify-center gap-2 border-t border-white/10 bg-black/20 px-4 py-2.5">
          {pens.map((x) => {
            const pl = [...data.homePlayers, ...data.awayPlayers].find((pp) => pp.id === x.playerId);
            const team = x.teamId === g.homeTeamId ? data.homeTeam : data.awayTeam;
            return (
              <span key={String(x.id)} className="rounded bg-white/10 px-2.5 py-1 font-mono text-xs text-white">
                {String(team.abbreviation)} #{pl?.jerseyNumber ?? '?'} {String(x.infraction)} · <b>{fmt(x.left)}</b>
              </span>
            );
          })}
        </div>
      )}
    </div>
  );
}

