import { createContext, useCallback, useContext, useEffect, useState, type ReactNode } from 'react';
import { getLookups, type GetLookupsOutputType, getMe, type GetMeOutputType } from 'zitejs/api';

type Ctx = {
  me: GetMeOutputType;
  lookups: GetLookupsOutputType | null;
  refreshLookups: () => Promise<void>;
  can: (perm: string) => boolean;
};

const AppCtx = createContext<Ctx | null>(null);

export function AppProvider({ me, children }: { me: GetMeOutputType; children: ReactNode }) {
  const [lookups, setLookups] = useState<GetLookupsOutputType | null>(null);
  const refreshLookups = useCallback(async () => {
    try { setLookups(await getLookups({})); } catch { /* surfaced by pages */ }
  }, []);
  useEffect(() => { refreshLookups(); }, [refreshLookups]);
  const can = (perm: string) => me.isSuper || me.perms.includes(perm);
  return <AppCtx.Provider value={{ me, lookups, refreshLookups, can }}>{children}</AppCtx.Provider>;
}

export function useApp() {
  const c = useContext(AppCtx);
  if (!c) throw new Error('useApp outside provider');
  return c;
}

export { getMe };

export function refLabel(lookups: GetLookupsOutputType | null, ref: string, id: unknown): string {
  if (!id || !lookups) return '';
  const list = (lookups as unknown as Record<string, { id: string; name?: string; label?: string }[]>)[ref] ?? [];
  const item = list.find((x) => x.id === id);
  return item ? item.name ?? item.label ?? '' : '';
}

export function fmtDateTime(iso?: string | null) {
  if (!iso) return '';
  return new Date(iso).toLocaleString(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
}

export function errMsg(e: unknown) {
  const x = e as { userFacingMessage?: string; message?: string };
  return x?.userFacingMessage || x?.message || 'Something went wrong';
}

import { zite } from 'zitejs/db';
import { ZiteError, type ZiteRequestContext } from 'zitejs/backend';

export const ROLE_PERMS: Record<string, string[]> = {
  'Super Administrator': ['*'],
  'League Administrator': ['games', 'gameops', 'teams', 'players', 'venues', 'seasons', 'officials', 'assignments', 'staff', 'news', 'awards', 'sponsors', 'settings', 'roles', 'audit', 'messages', 'faqs'],
  'Hockey Operations Administrator': ['games', 'gameops', 'teams', 'players', 'venues', 'seasons', 'awards', 'audit'],
  'Officiating Administrator': ['officials', 'assignments', 'audit'],
  'Team Manager': ['team'],
  'Game Operations Staff': ['gameops'],
  'League Staff Member': ['news', 'faqs', 'messages'],
  Official: [],
};

export type Access = { email: string; roles: string[]; perms: string[]; teamId: string; isSuper: boolean };

export async function getAccess(context: ZiteRequestContext): Promise<Access> {
  const email = (context.user?.email ?? '').toLowerCase();
  if (!email) return { email, roles: [], perms: [], teamId: '', isSuper: false };
  const { records } = await zite.userRoles.findAll({ limit: 200 });
  const mine = records.filter((r) => (r.email ?? '').toLowerCase() === email && r.active !== false);
  const roles = [...new Set(mine.map((r) => r.role ?? '').filter(Boolean))];
  const perms = new Set<string>();
  roles.forEach((r) => (ROLE_PERMS[r] ?? []).forEach((p) => perms.add(p)));
  const isSuper = perms.has('*');
  return { email, roles, perms: [...perms], teamId: mine.find((r) => r.role === 'Team Manager')?.teamId ?? '', isSuper };
}

export function can(a: Access, perm: string) {
  return a.isSuper || a.perms.includes(perm);
}

export async function requirePerm(context: ZiteRequestContext, ...anyOf: string[]) {
  const a = await getAccess(context);
  if (!anyOf.some((p) => can(a, p))) {
    throw new ZiteError({ code: 'FORBIDDEN', message: `Missing permission: ${anyOf.join(' or ')}`, userFacingMessage: 'You do not have permission to do that.' });
  }
  return a;
}

// Shared game engine. The same file lives in both NFHL apps (src/lib/engine.ts).
// The game clock is "anchor based": remaining seconds are stored together with the
// timestamp they were measured at, so every visitor computes the same time and the
// clock keeps running with nobody watching. tickGame() applies any due status
// transitions (auto start, period ends, intermissions, auto-final) idempotently.
import { zite } from 'zitejs/db';

export type Game = NonNullable<Awaited<ReturnType<typeof zite.games.findOne>>>;
export type GameEvent = NonNullable<Awaited<ReturnType<typeof zite.gameEvents.findOne>>>;

export const ACTIVE_STATUSES = ['Warmup', 'Live', 'Intermission', 'Overtime', 'Shootout', 'Suspended'];

export type Settings = Awaited<ReturnType<typeof getSettings>>;

export async function getSettings() {
  const { records } = await zite.leagueSettings.findAll({ limit: 1 });
  const s = records[0];
  return {
    id: s?.id ?? '',
    leagueName: s?.leagueName || 'Northern Frontier Hockey League',
    shortName: s?.shortName || 'NFHL',
    tagline: s?.tagline || '',
    periodMinutes: s?.periodMinutes || 20,
    otMinutes: s?.otMinutes || 5,
    intermissionMinutes: s?.intermissionMinutes ?? 18,
    autoFinalHours: s?.autoFinalHours || 2,
    currentSeasonId: s?.currentSeasonId || '',
    points: {
      win: s?.pointsWin ?? 2,
      otWin: s?.pointsOtWin ?? 2,
      soWin: s?.pointsSoWin ?? 2,
      regLoss: s?.pointsRegLoss ?? 0,
      otLoss: s?.pointsOtLoss ?? 1,
      soLoss: s?.pointsSoLoss ?? 1,
    },
    tiebreakers: (s?.tiebreakers || 'points,pointsPct,regulationWins,wins,goalDiff,goalsFor')
      .split(',').map((x) => x.trim()).filter(Boolean),
    logoUrl: s?.logoUrl || '',
    contactEmail: s?.contactEmail || '',
    contactPhone: s?.contactPhone || '',
    address: s?.address || '',
    socialLinks: s?.socialLinks || '',
    demoMode: s?.demoMode ?? true,
  };
}

export function periodLength(period: number, s: Settings) {
  if (period <= 3) return s.periodMinutes * 60;
  if (period === 4) return s.otMinutes * 60;
  return 0;
}

export function absSeconds(period: number, elapsed: number, s: Settings) {
  let t = 0;
  for (let p = 1; p < period; p++) t += periodLength(p, s);
  return t + elapsed;
}

export function clockRemaining(g: Game, nowMs: number) {
  const base = Number(g.clockRemaining ?? 0);
  if (g.clockRunning && g.clockAnchorAt) {
    return Math.max(0, base - (nowMs - Date.parse(g.clockAnchorAt)) / 1000);
  }
  return Math.max(0, base);
}

export function elapsedInPeriod(g: Game, s: Settings, nowMs: number) {
  const len = periodLength(Number(g.period || 1), s);
  return Math.max(0, Math.round(len - clockRemaining(g, nowMs)));
}

export function fmtClock(sec: number) {
  const t = Math.max(0, Math.ceil(sec));
  return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`;
}

export function periodLabel(p: number) {
  return p === 4 ? 'OT' : p >= 5 ? 'SO' : ['', '1st', '2nd', '3rd'][p] ?? `P${p}`;
}

export async function audit(actorEmail: string, action: string, entityType: string, entityId: string, details?: unknown) {
  await zite.auditLogs.create({
    record: {
      action, actorEmail, entityType, entityId,
      details: details === undefined ? '' : typeof details === 'string' ? details : JSON.stringify(details),
    } as never,
  });
}

/** Creates an event once — events carrying a clientKey are never duplicated. */
export async function logEvent(gameId: string, rec: Partial<Record<string, unknown>>, key?: string) {
  if (key) {
    const { records } = await zite.gameEvents.findAll({ filters: { gameId, clientKey: key }, limit: 1 });
    if (records[0]) return records[0];
  }
  return zite.gameEvents.create({ record: { gameId, clientKey: key ?? '', isVoid: false, ...rec } as never });
}

export async function notifyFans(g: Game, kind: string, title: string, body: string, playerIds: string[] = []) {
  try {
    const teamIds = [g.homeTeamId, g.awayTeamId].filter(Boolean) as string[];
    const { records } = await zite.favorites.findAll({ filters: { teamId: { in: teamIds } }, limit: 2000 });
    let all = records;
    if (playerIds.length) {
      const p = await zite.favorites.findAll({ filters: { playerId: { in: playerIds } }, limit: 2000 });
      all = all.concat(p.records);
    }
    const users = new Set<string>();
    for (const f of all) {
      if (!(f.alerts ?? []).includes(kind)) continue;
      const u = Array.isArray(f.user) ? f.user[0] : f.user;
      if (u) users.add(u);
    }
    const recs = [...users].map((user) => ({ title, body, user, link: `/games/${g.id}`, kind, isRead: false }));
    for (let i = 0; i < recs.length; i += 100) {
      await zite.notifications.bulkCreate({ records: recs.slice(i, i + 100) as never });
    }
  } catch (e) {
    console.error('notifyFans failed', e);
  }
}

export async function teamName(id?: string) {
  if (!id) return 'TBD';
  const t = await zite.teams.findOne({ id });
  return t?.name ?? 'TBD';
}

export function isConcluded(g: Game) {
  const p = Number(g.period || 0);
  if (!['Live', 'Overtime'].includes(g.status ?? '')) return false;
  if (g.clockRunning) return false;
  if (p < 3) return false;
  if (Number(g.homeScore ?? 0) === Number(g.awayScore ?? 0)) return false;
  return Number(g.clockRemaining ?? 0) <= 0 || p >= 4;
}

type Patch = Partial<Record<keyof Game, unknown>>;

async function stepOnce(g: Game, s: Settings, now: number): Promise<Patch | null> {
  const id = g.id;
  // 1) Scheduled start reached → Live
  if (g.status === 'Scheduled' && g.scheduledStart && Date.parse(g.scheduledStart) <= now) {
    const startIso = new Date(Date.parse(g.scheduledStart)).toISOString();
    await logEvent(id, { eventType: 'Game Start', period: 1, elapsedSeconds: 0, summary: 'Game is underway' }, `auto:${id}:start:${startIso}`);
    await logEvent(id, { eventType: 'Period Start', period: 1, elapsedSeconds: 0, summary: 'Start of 1st period' }, `auto:${id}:pstart:1:${startIso}`);
    const [h, a] = await Promise.all([teamName(g.homeTeamId), teamName(g.awayTeamId)]);
    await notifyFans(g, 'Game Start', 'Game underway', `${a} at ${h} has started.`);
    const pickG = async (tid?: string) => tid
      ? (await zite.players.findAll({ filters: { teamId: tid, position: 'G' }, limit: 5 })).records[0]?.id ?? '' : '';
    return {
      homeGoalieId: g.homeGoalieId || (await pickG(g.homeTeamId)),
      awayGoalieId: g.awayGoalieId || (await pickG(g.awayTeamId)),
      status: 'Live', period: 1, clockRemaining: periodLength(1, s), clockRunning: true, clockAnchorAt: startIso,
      liveStartedAt: startIso, homeScore: g.homeScore ?? 0, awayScore: g.awayScore ?? 0,
      homeShots: g.homeShots ?? 0, awayShots: g.awayShots ?? 0, statusNote: '',
    };
  }
  const p = Number(g.period || 1);
  // 2) Period clock expired
  if ((g.status === 'Live' || g.status === 'Overtime') && g.clockRunning && g.clockAnchorAt && clockRemaining(g, now) <= 0) {
    const endMs = Date.parse(g.clockAnchorAt) + Number(g.clockRemaining ?? 0) * 1000;
    const endIso = new Date(endMs).toISOString();
    const len = periodLength(p, s);
    await logEvent(id, { eventType: 'Period End', period: p, elapsedSeconds: len, summary: `End of ${periodLabel(p)} period` }, `auto:${id}:pend:${p}:${g.liveStartedAt}`);
    const [h, a] = await Promise.all([teamName(g.homeTeamId), teamName(g.awayTeamId)]);
    await notifyFans(g, 'Period End', `End of ${periodLabel(p)}`, `${a} ${g.awayScore ?? 0} – ${h} ${g.homeScore ?? 0}`);
    const tied = Number(g.homeScore ?? 0) === Number(g.awayScore ?? 0);
    const base: Patch = { clockRunning: false, clockRemaining: 0, clockAnchorAt: endIso };
    if (p < 3) {
      const ends = new Date(endMs + s.intermissionMinutes * 60000).toISOString();
      await logEvent(id, { eventType: 'Intermission', period: p, elapsedSeconds: len, summary: `${periodLabel(p)} intermission` }, `auto:${id}:int:${p}:${g.liveStartedAt}`);
      return { ...base, status: 'Intermission', intermissionEndsAt: ends, statusNote: `${periodLabel(p)} Intermission` };
    }
    if (p === 3 && tied) {
      const ends = new Date(endMs + 2 * 60000).toISOString();
      await logEvent(id, { eventType: 'Intermission', period: 3, elapsedSeconds: len, summary: 'Regulation ends tied — overtime next' }, `auto:${id}:int:3:${g.liveStartedAt}`);
      return { ...base, status: 'Intermission', intermissionEndsAt: ends, statusNote: 'Overtime next' };
    }
    if (p === 4 && tied) {
      await logEvent(id, { eventType: 'Shootout', period: 5, elapsedSeconds: 0, summary: 'Overtime solves nothing — shootout' }, `auto:${id}:so:${g.liveStartedAt}`);
      return { ...base, status: 'Shootout', period: 5, statusNote: 'Shootout' };
    }
    return { ...base, statusNote: p >= 4 ? 'End of overtime' : 'End of regulation' };
  }
  // 3) Intermission over → next period
  if (g.status === 'Intermission' && g.intermissionEndsAt && Date.parse(g.intermissionEndsAt) <= now) {
    const np = p + 1;
    const startIso = new Date(Date.parse(g.intermissionEndsAt)).toISOString();
    if (np === 4) await logEvent(id, { eventType: 'Overtime', period: 4, elapsedSeconds: 0, summary: 'Overtime begins (sudden death)' }, `auto:${id}:ot:${g.liveStartedAt}`);
    await logEvent(id, { eventType: 'Period Start', period: np, elapsedSeconds: 0, summary: `Start of ${periodLabel(np)}${np <= 3 ? ' period' : ''}` }, `auto:${id}:pstart:${np}:${g.liveStartedAt}`);
    return {
      status: np === 4 ? 'Overtime' : 'Live', period: np, clockRemaining: periodLength(np, s), clockRunning: true,
      clockAnchorAt: startIso, intermissionEndsAt: null, statusNote: '',
    };
  }
  // 4) Auto-final N hours after going live
  if (ACTIVE_STATUSES.includes(g.status ?? '') && g.liveStartedAt && now >= Date.parse(g.liveStartedAt) + s.autoFinalHours * 3600000) {
    if (isConcluded(g)) return finalizePatch(g, s, 'system:auto-final', true);
    if (!g.needsReview) {
      const why = g.status === 'Suspended' ? 'game is suspended'
        : g.status === 'Shootout' ? 'shootout not yet resolved'
        : g.status === 'Overtime' || p === 4 ? 'overtime still in progress'
        : g.clockRunning || g.status === 'Intermission' ? 'game still in progress'
        : Number(g.homeScore ?? 0) === Number(g.awayScore ?? 0) ? 'score is tied' : 'game not concluded';
      await audit('system', 'Auto-final skipped — flagged for review', 'Game', id, why);
      return { needsReview: true, reviewReason: `Auto-final at ${s.autoFinalHours}h was skipped: ${why}.` };
    }
  }
  return null;
}

export async function tickGame(g: Game, s: Settings, now = Date.now()): Promise<Game> {
  const cur = { ...g } as Game;
  const patch: Patch = {};
  for (let i = 0; i < 12; i++) {
    const step = await stepOnce(cur, s, now);
    if (!step) break;
    Object.assign(cur, step);
    Object.assign(patch, step);
    if (cur.status === 'Final') break;
  }
  if (Object.keys(patch).length) await zite.games.update({ id: g.id, record: patch as never });
  return cur;
}

/** Ticks every game that could have a due transition. Safe to call often. */
export async function tickDueGames(s?: Settings) {
  const settings = s ?? (await getSettings());
  const { rows } = await zite.sql({
    query: `SELECT id FROM "Games" WHERE ("status" = 'Scheduled' AND "scheduledStart" <= now())
      OR "status" IN ('Live','Intermission','Overtime','Shootout','Suspended','Warmup') LIMIT 50`,
  });
  for (const r of rows) {
    const g = await zite.games.findOne({ id: String(r.id) });
    if (g) await tickGame(g, settings);
  }
  return rows.length;
}

export async function getEvents(gameId: string) {
  const { records } = await zite.gameEvents.findAll({ filters: { gameId }, limit: 2000 });
  return records.sort((a, b) =>
    (Number(a.period ?? 0) - Number(b.period ?? 0)) || (Number(a.elapsedSeconds ?? 0) - Number(b.elapsedSeconds ?? 0)));
}

/** Recomputes score/shots/shootout totals from the (non-void) event log. */
export async function recomputeTotals(g: Game) {
  const events = (await getEvents(g.id)).filter((e) => !e.isVoid);
  const t = { homeScore: 0, awayScore: 0, homeShots: 0, awayShots: 0, shootoutHomeGoals: 0, shootoutAwayGoals: 0 };
  for (const e of events) {
    const home = e.teamId === g.homeTeamId;
    if (e.eventType === 'Goal') {
      if (home) { t.homeScore++; t.homeShots++; } else { t.awayScore++; t.awayShots++; }
    } else if (e.eventType === 'Shot') {
      if (home) t.homeShots++; else t.awayShots++;
    } else if (e.eventType === 'Shootout Attempt' && e.shootoutScored) {
      if (home) t.shootoutHomeGoals++; else t.shootoutAwayGoals++;
    }
  }
  await zite.games.update({ id: g.id, record: t as never });
  return { ...g, ...t } as Game;
}

export async function finalizePatch(g: Game, s: Settings, actor: string, auto = false): Promise<Patch> {
  const events = (await getEvents(g.id)).filter((e) => !e.isVoid);
  const p = Number(g.period || 3);
  const shootout = p >= 5 || g.status === 'Shootout';
  const hs = Number(g.homeScore ?? 0), as = Number(g.awayScore ?? 0);
  const homeWins = shootout ? Number(g.shootoutHomeGoals ?? 0) > Number(g.shootoutAwayGoals ?? 0) : hs > as;
  if (!shootout && hs === as) throw new Error('Cannot finalize a tied game — play overtime or a shootout first.');
  if (shootout && Number(g.shootoutHomeGoals ?? 0) === Number(g.shootoutAwayGoals ?? 0)) throw new Error('Shootout is tied — record more attempts first.');
  const decision = shootout ? 'Shootout' : p === 4 ? 'Overtime' : 'Regulation';
  const winTeam = homeWins ? g.homeTeamId : g.awayTeamId;
  const loserScore = homeWins ? as : hs;
  // Game-winning goal: the winner's goal that put them one past the loser's final total
  const winGoals = events.filter((e) => e.eventType === 'Goal' && e.teamId === winTeam);
  const gwg = shootout ? undefined : winGoals[loserScore];
  for (const e of events.filter((e) => e.eventType === 'Goal')) {
    const should = gwg?.id === e.id;
    if (!!e.isGameWinner !== should) await zite.gameEvents.update({ id: e.id, record: { isGameWinner: should } as never });
  }
  const finalizedAt = new Date().toISOString();
  await logEvent(g.id, { eventType: 'Game Final', period: Math.min(p, 5), elapsedSeconds: 99999, summary: `Final${decision !== 'Regulation' ? ` (${decision === 'Overtime' ? 'OT' : 'SO'})` : ''}` },
    auto ? `auto:${g.id}:final:${g.liveStartedAt}` : `final:${g.id}:${finalizedAt}`);
  const [h, a] = await Promise.all([teamName(g.homeTeamId), teamName(g.awayTeamId)]);
  await notifyFans(g, 'Final Score', 'Final score', `${a} ${as} – ${h} ${hs}${decision !== 'Regulation' ? ` (${decision === 'Overtime' ? 'OT' : 'SO'})` : ''}`);
  await audit(actor, auto ? 'Game auto-finalized' : 'Game finalized', 'Game', g.id, { decision, homeScore: hs, awayScore: as });
  return {
    status: 'Final', clockRunning: false, finalizedAt, decision,
    winningGoalieId: (homeWins ? g.homeGoalieId : g.awayGoalieId) || null,
    losingGoalieId: (homeWins ? g.awayGoalieId : g.homeGoalieId) || null,
    needsReview: false, reviewReason: '', intermissionEndsAt: null,
    statusNote: decision === 'Regulation' ? 'Final' : `Final/${decision === 'Overtime' ? 'OT' : 'SO'}`,
  };
}

export type ActivePenalty = {
  id: string; teamId: string; playerId: string; infraction: string; minutes: number;
  startAbs: number; expiresAbs: number;
};

/** Penalties still being served at `nowAbs`. Minors end early on an opposing power-play goal. */
export function activePenalties(g: Game, events: GameEvent[], s: Settings, nowAbs: number): ActivePenalty[] {
  const live = events.filter((e) => !e.isVoid);
  const goals = live.filter((e) => e.eventType === 'Goal').map((e) => ({ team: e.teamId, abs: absSeconds(Number(e.period), Number(e.elapsedSeconds), s) }));
  const out: ActivePenalty[] = [];
  const used = new Set<number>();
  const pens = live.filter((e) => e.eventType === 'Penalty' && ['Minor', 'Double Minor', 'Major'].includes(e.penaltyType ?? 'Minor'))
    .map((e) => ({ e, start: absSeconds(Number(e.period), Number(e.elapsedSeconds), s) }))
    .sort((a, b) => a.start - b.start);
  for (const { e, start } of pens) {
    const minutes = Number(e.penaltyMinutes || (e.penaltyType === 'Major' ? 5 : e.penaltyType === 'Double Minor' ? 4 : 2));
    let expires = start + minutes * 60;
    if ((e.penaltyType ?? 'Minor') === 'Minor') {
      const gi = goals.findIndex((x, i) => !used.has(i) && x.team !== e.teamId && x.abs > start && x.abs < expires);
      if (gi >= 0) { used.add(gi); expires = goals[gi].abs; }
    }
    if (start <= nowAbs && expires > nowAbs) {
      out.push({ id: e.id, teamId: e.teamId ?? '', playerId: e.playerId ?? '', infraction: e.infraction ?? 'Penalty', minutes, startAbs: start, expiresAbs: expires });
    }
  }
  return out;
}

