/** Coerces and validates incoming values against the entity's field types. Unknown fields are dropped. */
export function cleanRecord(def: EntityDef, input: Record<string, unknown>, isCreate: boolean) {
  const out: Record<string, unknown> = {};
  for (const [k, type] of Object.entries(def.fields)) {
    if (!(k in input)) continue;
    const v = input[k];
    if (v === null || v === undefined || v === '') { out[k] = type === 'bool' ? false : null; continue; }
    if (type === 'number') {
      const n = Number(v);
      if (!Number.isFinite(n)) throw new Error(`"${k}" must be a number`);
      out[k] = n;
    } else if (type === 'bool') out[k] = v === true || v === 'true';
    else if (type === 'date' || type === 'datetime') {
      if (Number.isNaN(Date.parse(String(v)))) throw new Error(`"${k}" must be a valid date`);
      out[k] = type === 'date' ? String(v).slice(0, 10) : new Date(String(v)).toISOString();
    } else out[k] = String(v).slice(0, 20000);
  }
  for (const r of def.required ?? []) {
    if (isCreate && (out[r] === undefined || out[r] === null)) throw new Error(`"${r}" is required`);
    if (!isCreate && r in out && out[r] === null) throw new Error(`"${r}" is required`);
  }
  return out;
}

