          {!b && [...Array(4)].map((_, i) => <Skeleton key={i} className="h-40" />)}
          {b?.games.length === 0 && <p className="rounded-lg border bg-card p-8 text-center text-muted-foreground">No games in this window.</p>}
          {b?.games.map((g) => <GameCard key={g.id} g={g} officials={b.officials} call={call} />)}
        </TabsContent>
        <TabsContent value="officials">
          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
