export type Ops = GetGameOpsOutputType;
export type Act = (action: string, extra?: Partial<GameActionInputType>) => Promise<boolean>;

export function parseClock(s: string): number | null {
  const m = s.trim().match(/^(\d{1,2}):(\d{2})$/);
  if (!m || Number(m[2]) > 59) return null;
  return Number(m[1]) * 60 + Number(m[2]);
}

/** Server-synchronized clock: corrects for the difference between this device and the server. */
export function useLiveRemaining(data: Ops | null) {
  const offset = useRef(0);
  const [now, setNow] = useState(Date.now());
  useEffect(() => { if (data) offset.current = data.serverNow - Date.now(); }, [data]);
  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 250); return () => clearInterval(t); }, []);
  if (!data) return { remaining: 0, serverNow: now };
  const g = data.game;
  const serverNow = now + offset.current;
  const base = Number(g.clockRemaining ?? 0);
  const remaining = g.clockRunning && g.clockAnchorAt ? Math.max(0, base - (serverNow - Date.parse(g.clockAnchorAt)) / 1000) : base;
  return { remaining, serverNow };
}

export default function GameConsole() {
  const { id = '' } = useParams();
  const [data, setData] = useState<Ops | null>(null);
  const [error, setError] = useState('');
  const [review, setReview] = useState<{ goalId?: string } | null>(null);
  const load = useCallback(async () => {
    try { setData(await getGameOps({ gameId: id })); setError(''); } catch (e) { setError(errMsg(e)); }
  }, [id]);
  useEffect(() => { load(); const t = setInterval(load, 3000); return () => clearInterval(t); }, [load]);
  const act: Act = async (action, extra = {}) => {
    try {
      const r = await gameAction({ gameId: id, action, ...extra });
      toast.success(r.message); await load(); return true;
    } catch (e) { toast.error(errMsg(e)); return false; }
  };
  const clock = useLiveRemaining(data);

  if (error && !data) return <div className="rounded-lg border bg-card p-8 text-center text-destructive">{error}</div>;
  if (!data) return <div className="space-y-4"><Skeleton className="h-48" /><Skeleton className="h-96" /></div>;
  const g = data.game;
  return (
    <div className="space-y-5">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <Link to="/games" className="inline-flex items-center gap-1 text-sm text-muted-foreground hover:text-foreground"><ArrowLeft className="h-4 w-4" />All games</Link>
        <p className="text-sm text-muted-foreground">{g.gameCode} · {data.venueName} · {fmtDateTime(g.scheduledStart)} · {g.gameType}{g.isDemo ? ' · Demo data' : ''}</p>
      </div>
      {g.needsReview && (
        <div className="flex flex-wrap items-center justify-between gap-3 rounded-lg border border-accent/40 bg-accent/10 p-4 text-sm">
          <span className="flex items-center gap-2 font-medium"><AlertTriangle className="h-4 w-4 text-accent" />Flagged for review: {g.reviewReason}</span>
          <button className="text-sm font-semibold text-accent underline" onClick={() => act('clearReview')}>Mark reviewed</button>
        </div>
      )}
      <Scoreboard data={data} remaining={clock.remaining} />
      <div className="grid gap-5 xl:grid-cols-[1fr_1.1fr]">
        <div className="space-y-5">
          <ClockControls data={data} remaining={clock.remaining} act={act} />
          <EventEntry data={data} act={act} onReview={() => setReview({})} />
        </div>
        <EventLog data={data} act={act} onReview={(goalId) => setReview({ goalId })} />
      </div>
      <GoalReviewDialog data={data} act={act} open={!!review} goalId={review?.goalId} onClose={() => setReview(null)} />
    </div>
  );
}

