type Row = Record<string, unknown>;

function SortTable({ rows, cols, initial }: { rows: Row[]; cols: { key: string; label: string; fmt?: (r: Row) => string }[]; initial: string }) {
  const [sort, setSort] = useState({ key: initial, dir: -1 });
  const sorted = useMemo(() => [...rows].sort((a, b) => {
    const av = a[sort.key], bv = b[sort.key];
    return (typeof av === 'number' ? (av - Number(bv)) : String(av).localeCompare(String(bv))) * sort.dir;
  }), [rows, sort]);
  return (
    <div className="overflow-x-auto rounded-lg border bg-card">
      <table className="w-full text-sm tabular">
        <thead className="bg-muted/50"><tr>{cols.map((c) => (
          <th key={c.key} className="cursor-pointer whitespace-nowrap px-3 py-2 text-left text-xs font-semibold uppercase tracking-wide" onClick={() => setSort((s) => ({ key: c.key, dir: s.key === c.key ? -s.dir : -1 }))}>
            {c.label}{sort.key === c.key ? (sort.dir < 0 ? ' ↓' : ' ↑') : ''}
          </th>))}</tr></thead>
        <tbody>{sorted.map((r, i) => <tr key={i} className="border-t">{cols.map((c) => <td key={c.key} className="whitespace-nowrap px-3 py-2">{c.fmt ? c.fmt(r) : String(r[c.key] ?? '')}</td>)}</tr>)}</tbody>
      </table>
    </div>
  );
}

