export default function SettingsPage() {
  const [form, setForm] = useState<Record<string, unknown> | null>(null);
  const [saving, setSaving] = useState(false);
  useEffect(() => { adminList({ entity: 'leagueSettings' }).then((r) => setForm(r.records[0] ?? {})).catch((e) => toast.error(errMsg(e))); }, []);
  const save = async () => {
    if (!form) return;
    const allowed = new Set(['pointsWin', 'pointsOtWin', 'pointsSoWin', 'pointsRegLoss', 'pointsOtLoss', 'pointsSoLoss']);
    for (const k of allowed) if (form[k] !== '' && form[k] !== undefined && (Number(form[k]) < 0 || Number(form[k]) > 5)) return toast.error('Point values must be between 0 and 5.');
    if (form.socialLinks) { try { JSON.parse(String(form.socialLinks)); } catch { return toast.error('Social links must be valid JSON.'); } }
    if (Number(form.periodMinutes) < 1 || Number(form.autoFinalHours) < 1) return toast.error('Period length and auto-final hours must be at least 1.');
    setSaving(true);
    const record = Object.fromEntries(SECTIONS.flatMap((s) => s.fields).map((f) => [f.key, form[f.key]]));
    try { await adminSave({ entity: 'leagueSettings', id: (form.id as string) || undefined, record }); toast.success('Settings saved'); }
    catch (e) { toast.error(errMsg(e)); } finally { setSaving(false); }
  };
  return (
    <div className="space-y-5">
      <PageHeader title="League Settings" description="Branding, points system, tiebreakers and game automation.">
        <Button onClick={save} disabled={saving || !form}>{saving && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Save settings</Button>
      </PageHeader>
      {!form ? <Skeleton className="h-96" /> : SECTIONS.map((s) => (
        <section key={s.title} className="rounded-lg border bg-card p-5 shadow-sm">
          <h2 className="font-display text-xl font-bold uppercase text-primary">{s.title}</h2>
          {s.note && <p className="mb-3 text-sm text-muted-foreground">{s.note}</p>}
          <div className="mt-3 grid gap-4 sm:grid-cols-3">
            {s.fields.map((f) => (
              <div key={f.key} className={f.full ? 'sm:col-span-3' : ''}>
                <Label className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-muted-foreground">{f.label}</Label>
                <FieldInput field={f} value={form[f.key]} onChange={(v) => setForm((x) => ({ ...x!, [f.key]: v }))} />
                {f.help && <p className="mt-1 text-xs text-muted-foreground">{f.help}</p>}
              </div>
            ))}
          </div>
        </section>
      ))}
    </div>
  );
}

