import { z } from 'zod';
import { createEndpoint, ZiteError } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { layoutFor, parseSeat, TIER_PRICE } from '../lib/seating';
import { getSettings } from '../lib/engine';

export default createEndpoint({
  description: 'Books selected seats for a game (demo checkout, no charge) and returns the order code',
  inputSchema: z.object({ gameId: z.string(), seatIds: z.array(z.string()), name: z.string(), email: z.string() }),
  outputSchema: z.object({ orderCode: z.string() }),
  execute: async ({ input, context }) => {
    const name = input.name.trim(), email = input.email.trim().toLowerCase();
    const fail = (m: string) => { throw new ZiteError(m); };
    if (!name || !/^\S+@\S+\.\S+$/.test(email)) fail('Enter your name and a valid email.');
    const seats = [...new Set(input.seatIds)];
    if (!seats.length || seats.length > 10) fail('Choose between 1 and 10 seats.');
    const g = await zite.sql({ query: `SELECT g."status" AS s, g."gameCode" AS code, v."capacity" AS c FROM "Games" g LEFT JOIN "Venues" v ON v.id::text = g."venueId" WHERE g.id::text = $1`, params: [input.gameId] });
    const game = g.rows[0];
    if (!game) fail('Game not found.');
    if (!['Scheduled', 'Warmup'].includes(String(game.s))) fail('Tickets are no longer on sale for this game.');
    const layout = layoutFor(Number(game.c ?? 0));
    const st = await getSettings();
    if (!st.ticketsOnSale) fail('Ticket sales are currently paused.');
    Object.assign(TIER_PRICE, st.prices);
    const parsed = seats.map((s) => parseSeat(s, layout));
    if (parsed.some((p) => !p)) fail('One of the selected seats does not exist.');
    const taken = await zite.sql({ query: `SELECT "seatId" FROM "Tickets" WHERE "gameId" = $1 AND COALESCE("status",'Sold') = 'Sold' AND "seatId" = ANY($2)`, params: [input.gameId, seats] });
    if (taken.rows.length) fail(`Sorry, ${taken.rows.length === 1 ? 'a seat you picked was' : 'some seats you picked were'} just sold. Please choose again.`);

    const orderCode = `NF-${Date.now().toString(36).toUpperCase().slice(-5)}${Math.random().toString(36).slice(2, 5).toUpperCase()}`;
    const created = await zite.tickets.bulkCreate({
      records: parsed.map((p) => ({
        seatLabel: p!.label, gameId: input.gameId, seatId: p!.id, section: p!.section, row: p!.row, seatNumber: p!.n,
        price: p!.price, buyerName: name, buyerEmail: email, orderCode, status: 'Sold', buyer: context.user?.id ?? null,
      })) as never,
    });
    // Guard against two buyers grabbing the same seat at the same instant: the earliest ticket wins.
    const dup = await zite.sql({
      query: `SELECT t."seatId" FROM "Tickets" t WHERE t."gameId" = $1 AND t."orderCode" = $2 AND EXISTS (
        SELECT 1 FROM "Tickets" o WHERE o."gameId" = t."gameId" AND o."seatId" = t."seatId" AND o."orderCode" <> t."orderCode" AND COALESCE(o."status",'Sold') = 'Sold' AND o."autonumber_id" < t."autonumber_id")`,
      params: [input.gameId, orderCode],
    });
    if (dup.rows.length) {
      await Promise.all(created.records.map((r: { id: string }) => zite.tickets.delete({ id: r.id })));
      fail('Sorry, a seat you picked was just sold. Please choose again.');
    }
    return { orderCode };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { skaterStats, goalieStats } from '../lib/stats';

const Staff = z.object({ id: z.string(), name: z.string(), title: z.string(), department: z.string(), bio: z.string(), photoUrl: z.string(), email: z.string(), phone: z.string(), isSample: z.boolean() });

const Out = z.object({
    staff: z.array(Staff),
    officials: z.array(z.object({ id: z.string(), name: z.string(), type: z.string(), level: z.string(), hometown: z.string(), years: z.number(), bio: z.string(), photoUrl: z.string(), isLeadership: z.boolean(), title: z.string(), isDemo: z.boolean() })),
    resources: z.array(z.object({ id: z.string(), title: z.string(), kind: z.string(), body: z.string(), url: z.string(), date: z.string() })),
    awards: z.array(z.object({ id: z.string(), title: z.string(), awardType: z.string(), periodLabel: z.string(), playerId: z.string(), playerName: z.string(), teamId: z.string(), date: z.string(), description: z.string() })),
    seasons: z.array(z.object({ id: z.string(), name: z.string(), championName: z.string(), championTeamId: z.string(), mvpName: z.string(), notes: z.string(), isCurrent: z.boolean() })),
    careerLeaders: z.object({ points: z.array(z.record(z.any())), goals: z.array(z.record(z.any())), wins: z.array(z.record(z.any())), shutouts: z.array(z.record(z.any())) }),
    media: z.array(z.object({ id: z.string(), title: z.string(), type: z.string(), url: z.string(), thumbnailUrl: z.string(), caption: z.string(), teamId: z.string(), date: z.string() })),
    faqs: z.array(z.object({ id: z.string(), question: z.string(), answer: z.string(), category: z.string() })),
  });

export default createEndpoint({
  description: 'Public content sections: league staff, officials page, awards, history, media and FAQs',
  inputSchema: z.object({ section: z.enum(['staff', 'officials', 'awards', 'history', 'media', 'faqs']) }),
  outputSchema: Out,
  execute: async ({ input }) => {
    const out = {
      staff: [] as z.infer<typeof Staff>[], officials: [] as never[], resources: [] as never[], awards: [] as never[], seasons: [] as never[],
      careerLeaders: { points: [], goals: [], wins: [], shutouts: [] } as Record<string, Record<string, unknown>[]>, media: [] as never[], faqs: [] as never[],
    } as Record<string, unknown> & { careerLeaders: Record<string, Record<string, unknown>[]> };
    const sec = input.section;
    if (sec === 'staff') {
      const { records } = await zite.leagueStaff.findAll({ limit: 500 });
      out.staff = records.filter((s) => s.isVisible).sort((a, b) => Number(a.sortOrder ?? 0) - Number(b.sortOrder ?? 0)).map((s) => ({
        id: s.id, name: s.name ?? '', title: s.title ?? '', department: s.department ?? 'Administration', bio: s.bio ?? '', photoUrl: s.photoUrl ?? '',
        email: s.showEmail ? s.email ?? '' : '', phone: s.showPhone ? s.phone ?? '' : '', isSample: !!s.isSample,
      }));
    }
    if (sec === 'officials') {
      const [offs, res] = await Promise.all([zite.officials.findAll({ limit: 1000 }), zite.officialResources.findAll({ limit: 200 })]);
      // Never expose private contact details or internal notes here.
      out.officials = offs.records.filter((o) => o.isPublic && o.active !== false).map((o) => ({
        id: o.id, name: o.name ?? '', type: o.officialType ?? '', level: o.level ?? '', hometown: o.hometown ?? '', years: Number(o.yearsExperience ?? 0),
        bio: o.bio ?? '', photoUrl: o.photoUrl ?? '', isLeadership: !!o.isLeadership, title: o.title ?? '', isDemo: !!o.isDemo,
      })) as never[];
      out.resources = res.records.filter((r) => r.isPublic).sort((a, b) => String(b.publishedDate).localeCompare(String(a.publishedDate)))
        .map((r) => ({ id: r.id, title: r.title ?? '', kind: r.kind ?? '', body: r.body ?? '', url: r.url ?? '', date: r.publishedDate ?? '' })) as never[];
    }
    if (sec === 'awards') {
      const [aw, pl] = await Promise.all([zite.awards.findAll({ limit: 500 }), zite.players.findAll({ limit: 2000 })]);
      const pn = new Map(pl.records.map((p) => [p.id, p.fullName ?? '']));
      out.awards = aw.records.sort((a, b) => String(b.awardDate).localeCompare(String(a.awardDate))).map((a) => ({
        id: a.id, title: a.title ?? '', awardType: a.awardType ?? '', periodLabel: a.periodLabel ?? '', playerId: a.playerId ?? '', playerName: pn.get(a.playerId ?? '') ?? '',
        teamId: a.teamId ?? '', date: a.awardDate ?? '', description: a.description ?? '',
      })) as never[];
    }
    if (sec === 'history') {
      const [se, sk, gk] = await Promise.all([zite.seasons.findAll({ limit: 100 }), skaterStats(''), goalieStats('')]);
      out.seasons = se.records.sort((a, b) => String(b.name).localeCompare(String(a.name))).map((s) => ({
        id: s.id, name: s.name ?? '', championName: s.championName ?? '', championTeamId: s.championTeamId ?? '', mvpName: s.mvpName ?? '', notes: s.notes ?? '', isCurrent: !!s.isCurrent,
      })) as never[];
      const top = <T extends Record<string, unknown>>(arr: T[], k: string) => [...arr].sort((a, b) => Number(b[k]) - Number(a[k])).slice(0, 10);
      out.careerLeaders = { points: top(sk, 'pts'), goals: top(sk, 'g'), wins: top(gk, 'w'), shutouts: top(gk, 'so') };
    }
    if (sec === 'media') {
      const { records } = await zite.mediaItems.findAll({ limit: 500 });
      out.media = records.filter((m) => !m.publishedAt || Date.parse(m.publishedAt) <= Date.now()).sort((a, b) => String(b.publishedAt).localeCompare(String(a.publishedAt)))
        .map((m) => ({ id: m.id, title: m.title ?? '', type: m.mediaType ?? 'Photo', url: m.url ?? '', thumbnailUrl: m.thumbnailUrl ?? '', caption: m.caption ?? '', teamId: m.teamId ?? '', date: m.publishedAt ?? '' })) as never[];
    }
    if (sec === 'faqs') {
      const { records } = await zite.faqs.findAll({ limit: 200 });
      out.faqs = records.sort((a, b) => Number(a.sortOrder ?? 0) - Number(b.sortOrder ?? 0)).map((f) => ({ id: f.id, question: f.question ?? '', answer: f.answer ?? '', category: f.category ?? '' })) as never[];
    }
    return out as unknown as z.infer<typeof Out>;
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { absSeconds, activePenalties, elapsedInPeriod, getEvents, getSettings, tickGame } from '../lib/engine';
import { queryArticles } from '../lib/public';

const PlayerLine = z.object({ id: z.string(), name: z.string(), num: z.number(), pos: z.string(), teamId: z.string(), g: z.number(), a: z.number(), pts: z.number(), sog: z.number(), pim: z.number(), ppg: z.number() });
const GoalieLine = z.object({ id: z.string(), name: z.string(), num: z.number(), teamId: z.string(), sa: z.number(), sv: z.number(), ga: z.number(), svPct: z.number(), decision: z.string() });

export default createEndpoint({
  description: 'Game Center data for one game: scoreboard, clock, play-by-play, box score, team/player stats and officials',
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({
    serverNow: z.number(), periodMinutes: z.number(), otMinutes: z.number(),
    game: z.object({
      id: z.string(), code: z.string(), status: z.string(), gameType: z.string(), playoffRound: z.string(), start: z.string(), originalStart: z.string(),
      homeTeamId: z.string(), awayTeamId: z.string(), homeScore: z.number(), awayScore: z.number(), homeShots: z.number(), awayShots: z.number(),
      shootoutHome: z.number(), shootoutAway: z.number(), period: z.number(), clockRunning: z.boolean(), clockRemaining: z.number(), clockAnchorAt: z.string(),
      intermissionEndsAt: z.string(), decision: z.string(), note: z.string(), isDemo: z.boolean(), venue: z.string(), venueCity: z.string(),
      homeGoalieId: z.string(), awayGoalieId: z.string(),
    }),
    events: z.array(z.object({ id: z.string(), type: z.string(), period: z.number(), elapsed: z.number(), teamId: z.string(), summary: z.string(), playerId: z.string(), assist1Id: z.string(), assist2Id: z.string(), strength: z.string(), penaltyMinutes: z.number(), infraction: z.string(), isGameWinner: z.boolean(), shootoutScored: z.boolean() })),
    penalties: z.array(z.object({ id: z.string(), teamId: z.string(), playerId: z.string(), infraction: z.string(), minutes: z.number(), expiresAbs: z.number() })),
    byPeriod: z.array(z.object({ period: z.number(), homeGoals: z.number(), awayGoals: z.number(), homeShots: z.number(), awayShots: z.number() })),
    teamStats: z.object({ home: z.record(z.number()), away: z.record(z.number()) }),
    skaters: z.array(PlayerLine), goalies: z.array(GoalieLine),
    players: z.array(z.object({ id: z.string(), name: z.string(), num: z.number(), pos: z.string(), teamId: z.string() })),
    officials: z.array(z.object({ id: z.string(), name: z.string(), position: z.string(), officialType: z.string(), level: z.string(), hometown: z.string(), years: z.number(), photoUrl: z.string() })),
    reviews: z.array(z.object({ id: z.string(), teamId: z.string(), scorerName: z.string(), period: z.number(), elapsed: z.number(), callOnIce: z.string(), callAfterReview: z.string(), reason: z.string(), note: z.string(), official: z.string() })),
    articles: z.array(z.object({ title: z.string(), slug: z.string(), category: z.string() })),
  }),
  execute: async ({ input }) => {
    const s = await getSettings();
    const raw = await zite.games.findOne({ id: input.id });
    if (!raw) throw new Error('Game not found');
    const g = await tickGame(raw, s);
    const now = Date.now();
    const [allEvents, hp, ap, venue, asg, articles, reviewRecs] = await Promise.all([
      getEvents(g.id),
      zite.players.findAll({ filters: { teamId: g.homeTeamId ?? '' }, limit: 100 }),
      zite.players.findAll({ filters: { teamId: g.awayTeamId ?? '' }, limit: 100 }),
      g.venueId ? zite.venues.findOne({ id: g.venueId }) : Promise.resolve(undefined),
      zite.officialAssignments.findAll({ filters: { gameId: g.id }, limit: 50 }),
      queryArticles(`"gameId" = $1`, [g.id], 4),
      zite.goalReviews.findAll({ filters: { gameId: g.id }, limit: 100 }),
    ]);
    const events = allEvents.filter((e) => !e.isVoid);
    const players = [...hp.records, ...ap.records];
    const pmap = new Map(players.map((p) => [p.id, p]));
    const home = g.homeTeamId ?? '';
    const currentAbs = absSeconds(Number(g.period || 1), elapsedInPeriod(g, s, now), s);

    const maxP = Math.max(3, Math.min(4, ...events.filter((e) => e.eventType === 'Goal' || e.eventType === 'Shot').map((e) => Number(e.period))), Math.min(Number(g.period || 0), 4));
    const byPeriod = Array.from({ length: maxP }, (_, i) => i + 1).map((p) => {
      const pe = events.filter((e) => Number(e.period) === p);
      const cnt = (team: boolean, types: string[]) => pe.filter((e) => types.includes(e.eventType ?? '') && (e.teamId === home) === team).length;
      return { period: p, homeGoals: cnt(true, ['Goal']), awayGoals: cnt(false, ['Goal']), homeShots: cnt(true, ['Goal', 'Shot']), awayShots: cnt(false, ['Goal', 'Shot']) };
    });

    const teamStat = (isHome: boolean) => {
      const tid = isHome ? home : g.awayTeamId;
      const mine = events.filter((e) => e.teamId === tid);
      const opp = events.filter((e) => e.teamId && e.teamId !== tid);
      const ppOpp = opp.filter((e) => e.eventType === 'Penalty' && ['Minor', 'Double Minor', 'Major'].includes(e.penaltyType ?? 'Minor')).length;
      const ppg = mine.filter((e) => e.eventType === 'Goal' && e.strength === 'Power Play').length;
      return {
        goals: mine.filter((e) => e.eventType === 'Goal').length, shots: mine.filter((e) => ['Goal', 'Shot'].includes(e.eventType ?? '')).length,
        ppGoals: ppg, ppOpportunities: ppOpp, shGoals: mine.filter((e) => e.eventType === 'Goal' && e.strength === 'Shorthanded').length,
        pim: mine.filter((e) => e.eventType === 'Penalty').reduce((t, e) => t + Number(e.penaltyMinutes ?? 0), 0),
        penalties: mine.filter((e) => e.eventType === 'Penalty').length,
        saves: opp.filter((e) => e.eventType === 'Shot').length,
      };
    };

    const skaters = players.filter((p) => p.position !== 'G').map((p) => {
      const goals = events.filter((e) => e.eventType === 'Goal' && e.playerId === p.id);
      const a = events.filter((e) => e.eventType === 'Goal' && (e.assist1Id === p.id || e.assist2Id === p.id)).length;
      return {
        id: p.id, name: p.fullName ?? '', num: Number(p.jerseyNumber ?? 0), pos: p.position ?? '', teamId: p.teamId ?? '',
        g: goals.length, a, pts: goals.length + a, ppg: goals.filter((e) => e.strength === 'Power Play').length,
        sog: events.filter((e) => ['Goal', 'Shot'].includes(e.eventType ?? '') && e.playerId === p.id).length,
        pim: events.filter((e) => e.eventType === 'Penalty' && e.playerId === p.id).reduce((t, e) => t + Number(e.penaltyMinutes ?? 0), 0),
      };
    }).filter((x) => x.g || x.a || x.sog || x.pim).sort((x, y) => y.pts - x.pts || y.g - x.g || y.sog - x.sog);

    const goalieIds = new Set([...events.filter((e) => e.goalieId).map((e) => e.goalieId!), g.homeGoalieId, g.awayGoalieId].filter(Boolean) as string[]);
    const goalies = [...goalieIds].map((id) => {
      const p = pmap.get(id);
      const sv = events.filter((e) => e.eventType === 'Shot' && e.goalieId === id).length;
      const ga = events.filter((e) => e.eventType === 'Goal' && e.goalieId === id).length;
      return {
        id, name: p?.fullName ?? 'Goaltender', num: Number(p?.jerseyNumber ?? 0), teamId: p?.teamId ?? '', sa: sv + ga, sv, ga,
        svPct: sv + ga ? +(sv / (sv + ga)).toFixed(3) : 0,
        decision: g.status === 'Final' ? (g.winningGoalieId === id ? 'W' : g.losingGoalieId === id ? (g.decision === 'Regulation' ? 'L' : 'OTL') : '') : '',
      };
    }).filter((x) => x.teamId);

    const offIds = asg.records.filter((x) => x.status === 'Accepted');
    const offs = offIds.length ? (await zite.officials.findAll({ filters: { id: { in: offIds.map((x) => x.officialId ?? '') } } as never, limit: 20 })).records : [];
    const ord = ['Referee 1', 'Referee 2', 'Linesperson 1', 'Linesperson 2'];

    return {
      serverNow: now, periodMinutes: s.periodMinutes, otMinutes: s.otMinutes,
      game: {
        id: g.id, code: g.gameCode ?? '', status: g.status ?? 'Scheduled', gameType: g.gameType ?? '', playoffRound: g.playoffRound ?? '',
        start: g.scheduledStart ? new Date(g.scheduledStart).toISOString() : '', originalStart: g.originalStart ? new Date(g.originalStart).toISOString() : '',
        homeTeamId: home, awayTeamId: g.awayTeamId ?? '', homeScore: Number(g.homeScore ?? 0), awayScore: Number(g.awayScore ?? 0),
        homeShots: Number(g.homeShots ?? 0), awayShots: Number(g.awayShots ?? 0), shootoutHome: Number(g.shootoutHomeGoals ?? 0), shootoutAway: Number(g.shootoutAwayGoals ?? 0),
        period: Number(g.period ?? 0), clockRunning: !!g.clockRunning, clockRemaining: Number(g.clockRemaining ?? 0),
        clockAnchorAt: g.clockAnchorAt ? new Date(g.clockAnchorAt).toISOString() : '', intermissionEndsAt: g.intermissionEndsAt ? new Date(g.intermissionEndsAt).toISOString() : '',
        decision: g.decision ?? '', note: g.statusNote ?? '', isDemo: !!g.isDemo, venue: venue?.name ?? '', venueCity: venue?.city ?? '',
        homeGoalieId: g.homeGoalieId ?? '', awayGoalieId: g.awayGoalieId ?? '',
      },
      events: events.map((e) => ({
        id: e.id, type: e.eventType ?? '', period: Number(e.period ?? 0), elapsed: Number(e.elapsedSeconds ?? 0), teamId: e.teamId ?? '', summary: e.summary ?? '',
        playerId: e.playerId ?? '', assist1Id: e.assist1Id ?? '', assist2Id: e.assist2Id ?? '', strength: e.strength ?? '', penaltyMinutes: Number(e.penaltyMinutes ?? 0),
        infraction: e.infraction ?? '', isGameWinner: !!e.isGameWinner, shootoutScored: !!e.shootoutScored,
      })),
      penalties: activePenalties(g, allEvents, s, currentAbs).map((x) => ({ id: x.id, teamId: x.teamId, playerId: x.playerId, infraction: x.infraction, minutes: x.minutes, expiresAbs: x.expiresAbs })),
      byPeriod, teamStats: { home: teamStat(true), away: teamStat(false) }, skaters, goalies,
      players: players.map((p) => ({ id: p.id, name: p.fullName ?? '', num: Number(p.jerseyNumber ?? 0), pos: p.position ?? '', teamId: p.teamId ?? '' })),
      officials: offIds.sort((a, b) => ord.indexOf(a.position ?? '') - ord.indexOf(b.position ?? ''))
        .map((x) => {
          const o = offs.find((v) => v.id === x.officialId);
          return { id: o?.id ?? '', name: o?.name ?? 'TBA', position: x.position ?? '', officialType: o?.officialType ?? '', level: o?.level ?? '', hometown: o?.hometown ?? '', years: Number(o?.yearsExperience ?? 0), photoUrl: o?.photoUrl ?? '' };
        }),
      reviews: reviewRecs.records.sort((a, b) => (Number(a.period ?? 0) - Number(b.period ?? 0)) || (Number(a.elapsedSeconds ?? 0) - Number(b.elapsedSeconds ?? 0)))
        .map((r) => ({ id: r.id, teamId: r.teamId ?? '', scorerName: r.scorerName ?? '', period: Number(r.period ?? 0), elapsed: Number(r.elapsedSeconds ?? 0), callOnIce: r.callOnIce ?? '', callAfterReview: r.callAfterReview ?? '', reason: r.reason ?? '', note: r.publicNote ?? '', official: r.reviewingOfficial ?? '' })),
      articles: articles.map((a) => ({ title: a.title, slug: a.slug, category: a.category })),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getSettings, tickDueGames } from '../lib/engine';
import { goalieStats, skaterStats, standings } from '../lib/stats';
import { ArticleCard, GameSummary, queryArticles, queryGames } from '../lib/public';

const Leader = z.object({ id: z.string(), name: z.string(), teamId: z.string(), value: z.number(), display: z.string() });

export default createEndpoint({
  description: 'Homepage data: live and upcoming games, results, standings, leaders, news, awards and staff',
  inputSchema: z.object({}),
  outputSchema: z.object({
    serverNow: z.number(),
    live: z.array(GameSummary), today: z.array(GameSummary), upcoming: z.array(GameSummary), recent: z.array(GameSummary), playoffs: z.array(GameSummary),
    puckDrop: z.object({ game: GameSummary, officials: z.array(z.object({ name: z.string(), position: z.string() })) }).nullable(),
    standings: z.array(z.record(z.any())),
    leaders: z.object({ points: z.array(Leader), goals: z.array(Leader), svPct: z.array(Leader), wins: z.array(Leader) }),
    articles: z.array(ArticleCard),
    awards: z.array(z.object({ id: z.string(), awardType: z.string(), periodLabel: z.string(), playerId: z.string(), playerName: z.string(), teamId: z.string(), description: z.string() })),
    staff: z.array(z.object({ id: z.string(), name: z.string(), title: z.string(), photoUrl: z.string(), isSample: z.boolean() })),
    featuredPlayers: z.array(z.object({ id: z.string(), name: z.string(), teamId: z.string(), pos: z.string(), num: z.number(), pts: z.number(), g: z.number(), a: z.number() })),
  }),
  execute: async () => {
    const s = await getSettings();
    await tickDueGames(s);
    const now = Date.now();
    const [around, recent, upcoming, playoffs, st, sk, gk, articles, awards, staff, players] = await Promise.all([
      queryGames(`g."scheduledStart" BETWEEN now() - interval '30 hours' AND now() + interval '30 hours' OR g."status" IN ('Live','Intermission','Overtime','Shootout','Suspended','Warmup')`),
      queryGames(`g."status" = 'Final'`, [], 8, 'DESC'),
      queryGames(`g."status" IN ('Scheduled','Postponed') AND g."scheduledStart" > now()`, [], 10),
      queryGames(`g."gameType" IN ('Playoff','Championship') AND g."scheduledStart" > now() - interval '7 days'`, [], 6),
      standings(s.currentSeasonId, s), skaterStats(s.currentSeasonId), goalieStats(s.currentSeasonId),
      queryArticles('TRUE', [], 7),
      zite.sql({ query: `SELECT id, "awardType" AS t, "periodLabel" AS pl, "playerId" AS pid, "teamId" AS tid, "description" AS d FROM "Awards" ORDER BY "awardDate" DESC NULLS LAST LIMIT 4` }),
      zite.sql({ query: `SELECT id, "name", "title", "photoUrl", "isSample" FROM "LeagueStaff" WHERE "isVisible" = true ORDER BY "sortOrder" ASC NULLS LAST LIMIT 4` }),
      zite.players.findAll({ limit: 2000, fields: ['fullName'] as never }),
    ]);
    const next = upcoming.find((g) => g.status === 'Scheduled') ?? null;
    const crew = next ? (await zite.sql({ query: `SELECT o."name" AS name, oa."position" AS pos FROM "OfficialAssignments" oa JOIN "Officials" o ON o.id::text = oa."officialId" WHERE oa."gameId" = $1 AND COALESCE(oa."status",'') <> 'Declined' ORDER BY oa."position"`, params: [next.id] } as never)).rows : [];
    const pname = new Map(players.records.map((p) => [p.id, p.fullName ?? '']));
    const top = <T extends { id: string; name: string; teamId: string }>(arr: T[], key: keyof T, fmt: (v: number) => string, min?: (x: T) => boolean) =>
      [...arr].filter(min ?? (() => true)).sort((a, b) => Number(b[key]) - Number(a[key])).slice(0, 5)
        .map((x) => ({ id: x.id, name: x.name, teamId: x.teamId, value: Number(x[key]), display: fmt(Number(x[key])) }));
    const dayStart = new Date(); dayStart.setHours(0, 0, 0, 0);
    const startMs = dayStart.getTime() - 4 * 3600000; // tolerate ET vs UTC worker
    const isLive = (g: { status: string }) => ['Live', 'Intermission', 'Overtime', 'Shootout', 'Suspended', 'Warmup'].includes(g.status);
    return {
      serverNow: now,
      live: around.filter(isLive),
      today: around.filter((g) => !isLive(g) && Date.parse(g.start) >= startMs && Date.parse(g.start) < now + 20 * 3600000),
      upcoming, recent, playoffs,
      puckDrop: next ? { game: next, officials: crew.map((r) => ({ name: String(r.name ?? ''), position: String(r.pos ?? '') })) } : null,
      standings: st,
      leaders: {
        points: top(sk, 'pts', (v) => `${v} PTS`), goals: top(sk, 'g', (v) => `${v} G`),
        svPct: top(gk, 'svPct', (v) => v.toFixed(3).replace(/^0/, ''), (x) => x.gp >= 2), wins: top(gk, 'w', (v) => `${v} W`),
      },
      articles,
      awards: awards.rows.map((r) => ({ id: String(r.id), awardType: String(r.t ?? ''), periodLabel: String(r.pl ?? ''), playerId: String(r.pid ?? ''), playerName: pname.get(String(r.pid ?? '')) ?? '', teamId: String(r.tid ?? ''), description: String(r.d ?? '') })),
      staff: staff.rows.map((r) => ({ id: String(r.id), name: String(r.name ?? ''), title: String(r.title ?? ''), photoUrl: String(r.photoUrl ?? ''), isSample: !!r.isSample })),
      featuredPlayers: [...sk].sort((a, b) => b.pts - a.pts).slice(0, 4).map((p) => ({ id: p.id, name: p.name, teamId: p.teamId, pos: p.pos, num: p.num, pts: p.pts, g: p.g, a: p.a })),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { ArticleCard, PUBLISHED, queryArticles } from '../lib/public';

export default createEndpoint({
  description: 'News: list published articles (search, category, paging) or fetch one article by slug',
  inputSchema: z.object({ slug: z.string().optional(), category: z.string().optional(), search: z.string().optional(), page: z.number().default(0), authorId: z.string().optional() }),
  outputSchema: z.object({
    articles: z.array(ArticleCard), total: z.number(),
    article: z.object({ id: z.string(), title: z.string(), slug: z.string(), category: z.string(), excerpt: z.string(), body: z.string(), heroImageUrl: z.string(), videoUrl: z.string(), authorName: z.string(), publishAt: z.string(), teamId: z.string(), gameId: z.string() }).nullable(),
    author: z.object({ id: z.string(), name: z.string(), title: z.string(), bio: z.string(), photoUrl: z.string() }).nullable(),
    related: z.array(ArticleCard),
  }),
  execute: async ({ input }) => {
    if (input.slug) {
      const { rows } = await zite.sql({ query: `SELECT id FROM "Articles" WHERE "slug" = $1 AND ${PUBLISHED} LIMIT 1`, params: [input.slug] });
      const a = rows[0] ? await zite.articles.findOne({ id: String(rows[0].id) }) : undefined;
      if (!a) throw new Error('Article not found');
      const author = a.authorStaffId ? await zite.leagueStaff.findOne({ id: a.authorStaffId }) : undefined;
      const related = await queryArticles(`"category" = $1 AND id::text <> $2`, [a.category ?? '', a.id], 3);
      return {
        articles: [], total: 0, related,
        article: { id: a.id, title: a.title ?? '', slug: a.slug ?? '', category: a.category ?? '', excerpt: a.excerpt ?? '', body: a.body ?? '', heroImageUrl: a.heroImageUrl ?? '', videoUrl: a.videoUrl ?? '', authorName: a.authorName ?? '', publishAt: a.publishAt ? new Date(a.publishAt).toISOString() : '', teamId: a.teamId ?? '', gameId: a.gameId ?? '' },
        author: author && author.isVisible ? { id: author.id, name: author.name ?? '', title: author.title ?? '', bio: author.bio ?? '', photoUrl: author.photoUrl ?? '' } : null,
      };
    }
    const where: string[] = ['TRUE'];
    const params: unknown[] = [];
    if (input.category) { params.push(input.category); where.push(`"category" = $${params.length}`); }
    if (input.search) { params.push(`%${input.search}%`); where.push(`("title" ILIKE $${params.length} OR "excerpt" ILIKE $${params.length})`); }
    if (input.authorId) { params.push(input.authorId); where.push(`"authorStaffId" = $${params.length}`); }
    const w = where.join(' AND ');
    const [articles, count] = await Promise.all([
      queryArticles(w, params, 12, input.page * 12),
      zite.sql({ query: `SELECT COUNT(*) AS c FROM "Articles" WHERE ${PUBLISHED} AND ${w}`, params }),
    ]);
    return { articles, total: Number(count.rows[0]?.c ?? 0), article: null, author: null, related: [] };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
