const Order = z.object({
  orderCode: z.string(), buyerName: z.string(), purchasedAt: z.string(), total: z.number(), game: GameSummary.nullable(),
  tickets: z.array(z.object({ id: z.string(), label: z.string(), section: z.string(), row: z.number(), seat: z.number(), price: z.number(), status: z.string() })),
});

export default createEndpoint({
  description: 'Looks up ticket orders by order code + email, or all orders of the signed-in fan',
  inputSchema: z.object({ orderCode: z.string().optional(), email: z.string().optional() }),
  outputSchema: z.object({ orders: z.array(Order) }),
  execute: async ({ input, context }) => {
    let where = '', params: unknown[] = [];
    if (input.orderCode && input.email) { where = `"orderCode" = $1 AND lower("buyerEmail") = $2`; params = [input.orderCode.trim().toUpperCase(), input.email.trim().toLowerCase()]; }
    else if (context.user) { where = `lower("buyerEmail") = $1`; params = [context.user.email.toLowerCase()]; }
    else return { orders: [] };
    const { rows } = await zite.sql({ query: `SELECT * FROM "Tickets" WHERE ${where} ORDER BY "autonumber_id" LIMIT 500`, params });
    const byOrder = new Map<string, Record<string, unknown>[]>();
    rows.forEach((r) => { const k = String(r.orderCode); byOrder.set(k, [...(byOrder.get(k) ?? []), r]); });
    const gameIds = [...new Set(rows.map((r) => String(r.gameId)))];
    const games = gameIds.length ? await queryGames(`g.id::text = ANY($1)`, [gameIds]) : [];
    const orders = [...byOrder.entries()].map(([code, ts]) => ({
      orderCode: code, buyerName: String(ts[0].buyerName ?? ''), purchasedAt: ts[0].created_at ? new Date(String(ts[0].created_at)).toISOString() : '',
      total: ts.filter((t) => t.status !== 'Refunded').reduce((s, t) => s + Number(t.price ?? 0), 0),
      game: games.find((g) => g.id === String(ts[0].gameId)) ?? null,
      tickets: ts.map((t) => ({ id: String(t.id), label: String(t.seatLabel ?? ''), section: String(t.section ?? ''), row: Number(t.row ?? 0), seat: Number(t.seatNumber ?? 0), price: Number(t.price ?? 0), status: String(t.status ?? 'Sold') })),
    })).sort((a, b) => b.purchasedAt.localeCompare(a.purchasedAt));
    return { orders };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getSettings } from '../lib/engine';
import { goalieStats, skaterStats } from '../lib/stats';

export default createEndpoint({
  description: 'Player profile: bio, season and career statistics, game-by-game log and awards',
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({
    player: z.object({ id: z.string(), name: z.string(), num: z.number(), pos: z.string(), teamId: z.string(), shoots: z.string(), height: z.string(), weight: z.number(), birthDate: z.string(), hometown: z.string(), bio: z.string(), photoUrl: z.string(), status: z.string(), isDemo: z.boolean() }),
    seasons: z.array(z.object({ seasonId: z.string(), seasonName: z.string(), stats: z.record(z.any()) })),
    career: z.record(z.any()).nullable(),
    gameLog: z.array(z.object({ gameId: z.string(), date: z.string(), opponentId: z.string(), home: z.boolean(), result: z.string(), g: z.number(), a: z.number(), sog: z.number(), pim: z.number(), sa: z.number(), sv: z.number(), ga: z.number() })),
    awards: z.array(z.object({ id: z.string(), awardType: z.string(), periodLabel: z.string(), description: z.string() })),
  }),
  execute: async ({ input }) => {
    const p = await zite.players.findOne({ id: input.id });
    if (!p) throw new Error('Player not found');
    const s = await getSettings();
    const isG = p.position === 'G';
    const seasons = (await zite.seasons.findAll({ limit: 100 })).records.sort((a, b) => String(b.name).localeCompare(String(a.name)));
    const perSeason = await Promise.all(seasons.map(async (se) => {
      const rows = isG ? await goalieStats(se.id, '', p.id) : await skaterStats(se.id, '', p.id);
      return { seasonId: se.id, seasonName: se.name ?? '', stats: rows[0] ?? {} };
    }));
    const withGames = perSeason.filter((x) => Number((x.stats as { gp?: number }).gp ?? 0) > 0 || x.seasonId === s.currentSeasonId);
    const career = (isG ? await goalieStats('', '', p.id) : await skaterStats('', '', p.id))[0] ?? null;
    const { rows } = await zite.sql({
      query: `
        SELECT g.id, g."scheduledStart" AS d, g."homeTeamId" AS h, g."awayTeamId" AS a, COALESCE(g."homeScore",0) AS hs, COALESCE(g."awayScore",0) AS vs, g."decision" AS dec, g."status" AS st,
          COUNT(e.id) FILTER (WHERE e."eventType" = 'Goal' AND e."playerId" = $1) AS g,
          COUNT(e.id) FILTER (WHERE e."eventType" = 'Goal' AND (e."assist1Id" = $1 OR e."assist2Id" = $1)) AS a2,
          COUNT(e.id) FILTER (WHERE e."eventType" IN ('Goal','Shot') AND e."playerId" = $1) AS sog,
          COALESCE(SUM(e."penaltyMinutes") FILTER (WHERE e."eventType" = 'Penalty' AND e."playerId" = $1), 0) AS pim,
          COUNT(e.id) FILTER (WHERE e."eventType" = 'Shot' AND e."goalieId" = $1) AS sv,
          COUNT(e.id) FILTER (WHERE e."eventType" = 'Goal' AND e."goalieId" = $1) AS ga
        FROM "Games" g JOIN "GameEvents" e ON e."gameId" = g.id::text AND COALESCE(e."isVoid", false) = false
        WHERE (g."homeTeamId" = $2 OR g."awayTeamId" = $2) AND g."status" IN ('Final','Live','Intermission','Overtime','Shootout')
        GROUP BY g.id ORDER BY g."scheduledStart" DESC LIMIT 60`,
      params: [p.id, p.teamId ?? ''],
    });
    const awards = await zite.awards.findAll({ filters: { playerId: p.id }, limit: 50 });
    return {
      player: { id: p.id, name: p.fullName ?? '', num: Number(p.jerseyNumber ?? 0), pos: p.position ?? '', teamId: p.teamId ?? '', shoots: p.shoots ?? '', height: p.height ?? '', weight: Number(p.weight ?? 0), birthDate: p.birthDate ?? '', hometown: p.hometown ?? '', bio: p.bio ?? '', photoUrl: p.photoUrl ?? '', status: p.status ?? '', isDemo: !!p.isDemo },
      seasons: withGames, career,
      gameLog: rows.filter((r) => !isG || Number(r.sv) + Number(r.ga) > 0).map((r) => {
        const home = r.h === p.teamId;
        const my = home ? Number(r.hs) : Number(r.vs), op = home ? Number(r.vs) : Number(r.hs);
        const result = r.st !== 'Final' ? 'LIVE' : `${my > op ? 'W' : my < op ? (r.dec === 'Regulation' ? 'L' : 'OTL') : 'T'} ${my}-${op}${r.dec && r.dec !== 'Regulation' ? (r.dec === 'Overtime' ? ' OT' : ' SO') : ''}`;
        return { gameId: String(r.id), date: r.d ? new Date(String(r.d)).toISOString() : '', opponentId: String(home ? r.a : r.h), home, result, g: Number(r.g), a: Number(r.a2), sog: Number(r.sog), pim: Number(r.pim), sa: Number(r.sv) + Number(r.ga), sv: Number(r.sv), ga: Number(r.ga) };
      }),
      awards: awards.records.map((a) => ({ id: a.id, awardType: a.awardType ?? '', periodLabel: a.periodLabel ?? '', description: a.description ?? '' })),
    };
  },
});

import { z } from 'zod';
