        .map((p) => ({ id: p.id, name: p.fullName ?? '', num: Number(p.jerseyNumber ?? 0), pos: p.position ?? '', teamId: p.teamId ?? '', hometown: p.hometown ?? '', status: p.status ?? '', photoUrl: p.photoUrl ?? '' }))
        .sort((a, b) => a.name.localeCompare(b.name)),
    };
