});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { GameSummary, queryGames } from '../lib/public';
import { layoutFor } from '../lib/seating';
import { getSettings } from '../lib/engine';

export default createEndpoint({
  description: 'Seat map for a game: venue layout plus which seats are already sold',
  inputSchema: z.object({ gameId: z.string() }),
  outputSchema: z.object({
    game: GameSummary, capacity: z.number(), onSale: z.boolean(),
    layout: z.object({ long: z.number(), end: z.number(), rows: z.object({ R: z.number(), L: z.number(), U: z.number() }) }),
    sold: z.array(z.string()),
  }),
  execute: async ({ input }) => {
    const [game] = await queryGames(`g.id::text = $1`, [input.gameId], 1);
    if (!game) throw new Error('Game not found');
    const v = await zite.sql({ query: `SELECT v."capacity" AS c FROM "Games" g LEFT JOIN "Venues" v ON v.id::text = g."venueId" WHERE g.id::text = $1`, params: [input.gameId] });
    const capacity = Number(v.rows[0]?.c ?? 0);
    const sold = await zite.sql({ query: `SELECT "seatId" FROM "Tickets" WHERE "gameId" = $1 AND COALESCE("status",'Sold') = 'Sold'`, params: [input.gameId] });
    const st = await getSettings();
    return {
      game, capacity, layout: layoutFor(capacity),
      onSale: st.ticketsOnSale && ['Scheduled', 'Warmup'].includes(game.status),
      sold: sold.rows.map((r) => String(r.seatId)),
    };
  },
});

import { z } from 'zod';
