  inputSchema: z.object({}),
  outputSchema: z.object({
    settings: z.object({ leagueName: z.string(), shortName: z.string(), tagline: z.string(), logoUrl: z.string(), contactEmail: z.string(), contactPhone: z.string(), address: z.string(), social: z.record(z.string()), demoMode: z.boolean(), currentSeasonId: z.string(), periodMinutes: z.number(), otMinutes: z.number(), announcement: z.string(), aboutText: z.string(), ticketsOnSale: z.boolean(), prices: z.object({ R: z.number(), L: z.number(), U: z.number() }) }),
    teams: z.array(z.object({ id: z.string(), name: z.string(), city: z.string(), nickname: z.string(), abbreviation: z.string(), conference: z.string(), primaryColor: z.string(), secondaryColor: z.string(), logoUrl: z.string(), venueId: z.string() })),
    seasons: z.array(z.object({ id: z.string(), name: z.string(), isCurrent: z.boolean() })),
    sponsors: z.array(z.object({ id: z.string(), name: z.string(), tier: z.string(), logoUrl: z.string(), website: z.string(), blurb: z.string() })),
    venues: z.array(z.object({ id: z.string(), name: z.string(), city: z.string() })),
  }),
  execute: async () => {
    const [s, teams, seasons, sponsors, venues] = await Promise.all([
      getSettings(), zite.teams.findAll({ limit: 200 }), zite.seasons.findAll({ limit: 100 }), zite.sponsors.findAll({ limit: 100 }), zite.venues.findAll({ limit: 200 }),
    ]);
    let social: Record<string, string> = {};
    try { social = JSON.parse(s.socialLinks || '{}'); } catch { social = {}; }
    return {
      settings: { leagueName: s.leagueName, shortName: s.shortName, tagline: s.tagline, logoUrl: s.logoUrl, contactEmail: s.contactEmail, contactPhone: s.contactPhone, address: s.address, social, demoMode: s.demoMode, currentSeasonId: s.currentSeasonId, periodMinutes: s.periodMinutes, otMinutes: s.otMinutes, announcement: s.announcement, aboutText: s.aboutText, ticketsOnSale: s.ticketsOnSale, prices: s.prices },
      teams: teams.records.map((t) => ({ id: t.id, name: t.name ?? '', city: t.city ?? '', nickname: t.nickname ?? '', abbreviation: t.abbreviation ?? '', conference: t.conference ?? '', primaryColor: t.primaryColor || '#0B2545', secondaryColor: t.secondaryColor || '#FFFFFF', logoUrl: t.logoUrl ?? '', venueId: t.venueId ?? '' })).sort((a, b) => a.name.localeCompare(b.name)),
      seasons: seasons.records.map((x) => ({ id: x.id, name: x.name ?? '', isCurrent: !!x.isCurrent })).sort((a, b) => b.name.localeCompare(a.name)),
      sponsors: sponsors.records.sort((a, b) => Number(a.sortOrder ?? 0) - Number(b.sortOrder ?? 0)).map((x) => ({ id: x.id, name: x.name ?? '', tier: x.tier ?? '', logoUrl: x.logoUrl ?? '', website: x.website ?? '', blurb: x.blurb ?? '' })),
      venues: venues.records.map((v) => ({ id: v.id, name: v.name ?? '', city: v.city ?? '' })),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { getSettings } from '../lib/engine';
import { standings } from '../lib/stats';
import { GameSummary, queryGames } from '../lib/public';

export default createEndpoint({
  description: 'Standings with the configured points system, plus the projected playoff bracket and playoff schedule',
  inputSchema: z.object({ seasonId: z.string().optional() }),
  outputSchema: z.object({
    seasonId: z.string(), points: z.record(z.number()), tiebreakers: z.array(z.string()),
    rows: z.array(z.record(z.any())), playoffGames: z.array(GameSummary),
  }),
  execute: async ({ input }) => {
    const s = await getSettings();
    const seasonId = input.seasonId || s.currentSeasonId;
    const [rows, playoffGames] = await Promise.all([
      standings(seasonId, s),
      queryGames(`g."gameType" IN ('Playoff','Championship') AND g."seasonId" = $1`, [seasonId]),
    ]);
    return { seasonId, points: s.points, tiebreakers: s.tiebreakers, rows, playoffGames };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getSettings } from '../lib/engine';
import { goalieStats, skaterStats } from '../lib/stats';

export default createEndpoint({
  description: 'Statistics center: skater and goaltender stats plus team totals, filterable by season and team',
  inputSchema: z.object({ seasonId: z.string().optional(), teamId: z.string().optional() }),
  outputSchema: z.object({
    seasonId: z.string(), skaters: z.array(z.record(z.any())), goalies: z.array(z.record(z.any())),
    teams: z.array(z.object({ teamId: z.string(), gp: z.number(), gf: z.number(), ga: z.number(), shots: z.number(), ppg: z.number(), ppo: z.number(), ppPct: z.number(), shg: z.number(), pim: z.number() })),
  }),
  execute: async ({ input }) => {
    const s = await getSettings();
    const seasonId = input.seasonId ?? s.currentSeasonId;
    const [skaters, goalies, teamRows] = await Promise.all([
      skaterStats(seasonId, input.teamId ?? ''), goalieStats(seasonId, input.teamId ?? ''),
      zite.sql({
        query: `
          WITH fg AS (SELECT id::text AS gid, "homeTeamId" AS h, "awayTeamId" AS a, COALESCE("homeScore",0) AS hs, COALESCE("awayScore",0) AS vs
            FROM "Games" WHERE "status" = 'Final' AND ($1 = '' OR "seasonId" = $1)),
          tg AS (SELECT h AS tid, hs AS gf, vs AS ga FROM fg UNION ALL SELECT a, vs, hs FROM fg),
          ev AS (SELECT e."gameId" AS gid, e."teamId" AS tid, e."eventType" AS t, e."strength" AS st, e."penaltyMinutes" AS pim, e."penaltyType" AS pt
            FROM "GameEvents" e JOIN fg ON fg.gid = e."gameId" WHERE COALESCE(e."isVoid", false) = false),
          opp AS (SELECT fg.gid, fg.h AS tid, fg.a AS oid FROM fg UNION ALL SELECT fg.gid, fg.a, fg.h FROM fg)
          SELECT tg.tid, COUNT(*) AS gp, SUM(tg.gf) AS gf, SUM(tg.ga) AS ga,
            (SELECT COUNT(*) FROM ev WHERE ev.tid = tg.tid AND ev.t IN ('Goal','Shot')) AS shots,
            (SELECT COUNT(*) FROM ev WHERE ev.tid = tg.tid AND ev.t = 'Goal' AND ev.st = 'Power Play') AS ppg,
            (SELECT COUNT(*) FROM ev WHERE ev.tid = tg.tid AND ev.t = 'Goal' AND ev.st = 'Shorthanded') AS shg,
            (SELECT COALESCE(SUM(ev.pim),0) FROM ev WHERE ev.tid = tg.tid AND ev.t = 'Penalty') AS pim,
            (SELECT COUNT(*) FROM ev JOIN opp ON opp.gid = ev.gid AND opp.oid = ev.tid WHERE opp.tid = tg.tid AND ev.t = 'Penalty' AND COALESCE(ev.pt,'Minor') IN ('Minor','Double Minor','Major')) AS ppo
          FROM tg GROUP BY tg.tid`,
        params: [seasonId],
      }),
    ]);
    return {
      seasonId, skaters, goalies,
      teams: teamRows.rows.map((r) => {
        const ppg = Number(r.ppg), ppo = Number(r.ppo);
        return { teamId: String(r.tid), gp: Number(r.gp), gf: Number(r.gf), ga: Number(r.ga), shots: Number(r.shots), ppg, ppo, ppPct: ppo ? +(ppg / ppo * 100).toFixed(1) : 0, shg: Number(r.shg), pim: Number(r.pim) };
      }),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { getSettings, tickDueGames } from '../lib/engine';
import { goalieStats, skaterStats, standings } from '../lib/stats';
import { ArticleCard, GameSummary, queryArticles, queryGames } from '../lib/public';

export default createEndpoint({
  description: 'Team profile: roster with stats, coaching staff, schedule, results, standing and news',
  inputSchema: z.object({ id: z.string() }),
  outputSchema: z.object({
    team: z.record(z.any()), venue: z.record(z.any()),
    skaters: z.array(z.record(z.any())), goalies: z.array(z.record(z.any())),
    roster: z.array(z.object({ id: z.string(), name: z.string(), num: z.number(), pos: z.string(), shoots: z.string(), height: z.string(), weight: z.number(), hometown: z.string(), birthDate: z.string(), status: z.string(), photoUrl: z.string() })),
    staff: z.array(z.object({ id: z.string(), name: z.string(), role: z.string(), bio: z.string(), photoUrl: z.string() })),
    games: z.array(GameSummary), standing: z.record(z.any()).nullable(), rank: z.number(), articles: z.array(ArticleCard),
  }),
  execute: async ({ input }) => {
    const team = await zite.teams.findOne({ id: input.id });
    if (!team) throw new Error('Team not found');
    const s = await getSettings();
    await tickDueGames(s);
    const [venue, players, staff, games, st, sk, gk, articles] = await Promise.all([
      team.venueId ? zite.venues.findOne({ id: team.venueId }) : Promise.resolve(undefined),
      zite.players.findAll({ filters: { teamId: team.id }, limit: 100 }),
      zite.teamStaff.findAll({ filters: { teamId: team.id }, limit: 50 }),
      queryGames(`(g."homeTeamId" = $1 OR g."awayTeamId" = $1) AND g."seasonId" = $2`, [team.id, s.currentSeasonId]),
      standings(s.currentSeasonId, s), skaterStats(s.currentSeasonId, team.id), goalieStats(s.currentSeasonId, team.id),
      queryArticles(`"teamId" = $1`, [team.id], 6),
    ]);
    const conf = st.filter((r) => r.conference === team.conference);
    return {
      team, venue: (venue ?? {}) as Record<string, any>, skaters: sk, goalies: gk,
      roster: players.records.sort((a, b) => Number(a.jerseyNumber ?? 0) - Number(b.jerseyNumber ?? 0)).map((p) => ({
        id: p.id, name: p.fullName ?? '', num: Number(p.jerseyNumber ?? 0), pos: p.position ?? '', shoots: p.shoots ?? '', height: p.height ?? '',
        weight: Number(p.weight ?? 0), hometown: p.hometown ?? '', birthDate: p.birthDate ?? '', status: p.status ?? 'Active', photoUrl: p.photoUrl ?? '',
      })),
      staff: staff.records.map((x) => ({ id: x.id, name: x.name ?? '', role: x.role ?? '', bio: x.bio ?? '', photoUrl: x.photoUrl ?? '' })),
      games, standing: st.find((r) => r.teamId === team.id) ?? null, rank: conf.findIndex((r) => r.teamId === team.id) + 1, articles,
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { tickDueGames } from '../lib/engine';
import { GameSummary, queryGames } from '../lib/public';

export default createEndpoint({
  description: 'Schedule and scores with filters for date range, team, venue, status and season',
  inputSchema: z.object({
    from: z.string().optional(), to: z.string().optional(), teamId: z.string().optional(),
    venueId: z.string().optional(), status: z.string().optional(), seasonId: z.string().optional(), gameType: z.string().optional(),
  }),
  outputSchema: z.object({ serverNow: z.number(), games: z.array(GameSummary) }),
  execute: async ({ input }) => {
    await tickDueGames();
    const where: string[] = ['TRUE'];
    const params: unknown[] = [];
    const add = (sql: string, v: unknown) => { params.push(v); where.push(sql.replace('?', `$${params.length}`)); };
    if (input.from) add(`g."scheduledStart" >= ?`, new Date(input.from).toISOString());
    if (input.to) add(`g."scheduledStart" < ?`, new Date(input.to).toISOString());
    if (input.teamId) { params.push(input.teamId); where.push(`(g."homeTeamId" = $${params.length} OR g."awayTeamId" = $${params.length})`); }
    if (input.venueId) add(`g."venueId" = ?`, input.venueId);
    if (input.seasonId) add(`g."seasonId" = ?`, input.seasonId);
    if (input.gameType) add(`g."gameType" = ?`, input.gameType);
    if (input.status === 'Live') where.push(`g."status" IN ('Live','Intermission','Overtime','Shootout','Suspended','Warmup')`);
    else if (input.status) add(`g."status" = ?`, input.status);
    return { serverNow: Date.now(), games: await queryGames(where.join(' AND '), params, 1000) };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

const ALERTS = ['Game Start', 'Goal', 'Penalty', 'Period End', 'Final Score'] as const;

export default createEndpoint({
  description: "Signed-in fan's favorites and alerts: list, follow/unfollow, set alert types, read and mark notifications",
  authenticated: true,
  inputSchema: z.object({
    action: z.enum(['list', 'follow', 'unfollow', 'setAlerts', 'markRead']),
    teamId: z.string().optional(), playerId: z.string().optional(), favoriteId: z.string().optional(),
    alerts: z.array(z.enum(ALERTS)).optional(),
  }),
  outputSchema: z.object({
    favorites: z.array(z.object({ id: z.string(), teamId: z.string(), playerId: z.string(), label: z.string(), alerts: z.array(z.string()) })),
    notifications: z.array(z.object({ id: z.string(), title: z.string(), body: z.string(), link: z.string(), kind: z.string(), isRead: z.boolean(), sentAt: z.string() })),
  }),
  execute: async ({ input, context }) => {
    const uid = context.user.id;
    const mineFav = async () => (await zite.favorites.findAll({ filters: { user: uid }, limit: 200 })).records;
    let favs = await mineFav();
    if (input.action === 'follow') {
      if (!input.teamId && !input.playerId) throw new Error('Choose a team or player to follow.');
      const exists = favs.find((f) => (input.teamId && f.teamId === input.teamId) || (input.playerId && f.playerId === input.playerId));
      if (!exists) {
        const label = input.teamId ? (await zite.teams.findOne({ id: input.teamId }))?.name : (await zite.players.findOne({ id: input.playerId! }))?.fullName;
        if (!label) throw new Error('Not found');
        await zite.favorites.create({ record: { user: uid, teamId: input.teamId ?? '', playerId: input.playerId ?? '', label, alerts: input.teamId ? ['Game Start', 'Goal', 'Final Score'] : ['Goal'] } as never });
      }
      favs = await mineFav();
    } else if (input.action === 'unfollow' || input.action === 'setAlerts') {
      const f = favs.find((x) => x.id === input.favoriteId || (input.teamId && x.teamId === input.teamId) || (input.playerId && x.playerId === input.playerId));
      if (!f) throw new Error('Favorite not found');
      if (input.action === 'unfollow') await zite.favorites.delete({ id: f.id });
      else await zite.favorites.update({ id: f.id, record: { alerts: input.alerts ?? [] } as never });
      favs = await mineFav();
    }
    const notes = (await zite.notifications.findAll({ filters: { user: uid }, limit: 200 })).records
      .sort((a, b) => String(b.sentAt).localeCompare(String(a.sentAt))).slice(0, 40);
    if (input.action === 'markRead') {
      for (const n of notes.filter((n) => !n.isRead)) await zite.notifications.update({ id: n.id, record: { isRead: true } as never });
      notes.forEach((n) => { n.isRead = true; });
    }
    return {
      favorites: favs.map((f) => ({ id: f.id, teamId: f.teamId ?? '', playerId: f.playerId ?? '', label: f.label ?? '', alerts: f.alerts ?? [] })),
      notifications: notes.map((n) => ({ id: n.id, title: n.title ?? '', body: n.body ?? '', link: n.link ?? '', kind: n.kind ?? '', isRead: !!n.isRead, sentAt: n.sentAt ?? '' })),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { audit } from '../lib/engine';

const Asg = z.object({
  id: z.string(), gameId: z.string(), code: z.string(), start: z.string(), venue: z.string(), homeTeamId: z.string(), awayTeamId: z.string(),
  position: z.string(), status: z.string(), gameStatus: z.string(), crew: z.array(z.object({ name: z.string(), position: z.string(), status: z.string() })),
});

export default createEndpoint({
  description: 'Officials Portal for the signed-in official: assignments, responses, availability, profile, evaluations and resources',
  authenticated: true,
  inputSchema: z.object({
    action: z.enum(['load', 'respond', 'availability', 'profile']),
    assignmentId: z.string().optional(), accept: z.boolean().optional(), note: z.string().optional(),
    date: z.string().optional(), status: z.enum(['Available', 'Limited', 'Unavailable', 'Clear']).optional(),
    phone: z.string().optional(), hometown: z.string().optional(), bio: z.string().optional(), photoUrl: z.string().optional(),
  }),
  outputSchema: z.object({
    official: z.object({ id: z.string(), name: z.string(), email: z.string(), phone: z.string(), type: z.string(), level: z.string(), hometown: z.string(), bio: z.string(), photoUrl: z.string(), years: z.number() }).nullable(),
    upcoming: z.array(Asg), history: z.array(Asg),
    availability: z.array(z.object({ id: z.string(), date: z.string(), status: z.string(), note: z.string() })),
    evaluations: z.array(z.object({ id: z.string(), title: z.string(), score: z.number(), feedback: z.string(), gameCode: z.string() })),
    resources: z.array(z.object({ id: z.string(), title: z.string(), kind: z.string(), body: z.string(), url: z.string(), date: z.string() })),
  }),
  execute: async ({ input, context }) => {
    const uid = context.user.id;
    const email = context.user.email.toLowerCase();
    const all = (await zite.officials.findAll({ limit: 1000 })).records;
    let off = all.find((o) => (Array.isArray(o.user) ? o.user.includes(uid) : o.user === uid)) ?? all.find((o) => (o.email ?? '').toLowerCase() === email);
    const empty = {
      official: null, upcoming: [] as z.infer<typeof Asg>[], history: [] as z.infer<typeof Asg>[],
      availability: [] as { id: string; date: string; status: string; note: string }[],
      evaluations: [] as { id: string; title: string; score: number; feedback: string; gameCode: string }[],
      resources: [] as { id: string; title: string; kind: string; body: string; url: string; date: string }[],
    };
    if (!off || off.active === false) return empty;
    if (!off.user || (Array.isArray(off.user) && !off.user.length)) await zite.officials.update({ id: off.id, record: { user: uid } as never });

    if (input.action === 'respond') {
      const a = input.assignmentId ? await zite.officialAssignments.findOne({ id: input.assignmentId }) : undefined;
      if (!a || a.officialId !== off.id) throw new Error('Assignment not found.');
      if (!['Pending', 'Accepted'].includes(a.status ?? '')) throw new Error('This assignment can no longer be changed.');
      const g = await zite.games.findOne({ id: a.gameId ?? '' });
      if (!g || Date.parse(g.scheduledStart ?? '') < Date.now()) throw new Error('This game has already started.');
      if (!input.accept && !input.note?.trim()) throw new Error('Please give a reason when declining.');
      await zite.officialAssignments.update({ id: a.id, record: { status: input.accept ? 'Accepted' : 'Declined', respondedAt: new Date().toISOString(), responseNote: input.note ?? '' } as never });
      await audit(email, input.accept ? 'Official accepted assignment' : 'Official declined assignment', 'OfficialAssignment', a.id, input.note ?? '');
    }
    if (input.action === 'availability') {
      if (!input.date || !/^\d{4}-\d{2}-\d{2}$/.test(input.date)) throw new Error('Choose a valid date.');
      const existing = (await zite.officialAvailability.findAll({ filters: { officialId: off.id, date: input.date } as never, limit: 5 })).records;
      for (const e of existing) await zite.officialAvailability.delete({ id: e.id });
      if (input.status && input.status !== 'Clear') {
        await zite.officialAvailability.create({ record: { label: `${off.name} · ${input.date}`, officialId: off.id, date: input.date, status: input.status, note: (input.note ?? '').slice(0, 300) } as never });
      }
    }
    if (input.action === 'profile') {
      const rec: Record<string, string> = {};
      if (input.phone !== undefined) rec.phone = input.phone.slice(0, 40);
      if (input.hometown !== undefined) rec.hometown = input.hometown.slice(0, 100);
      if (input.bio !== undefined) rec.bio = input.bio.slice(0, 3000);
      if (input.photoUrl !== undefined) rec.photoUrl = input.photoUrl.slice(0, 1000);
      await zite.officials.update({ id: off.id, record: rec as never });
      await audit(email, 'Official updated profile', 'Official', off.id, Object.keys(rec));
      off = (await zite.officials.findOne({ id: off.id }))!;
    }

    const [mine, avail, evals, res] = await Promise.all([
      zite.officialAssignments.findAll({ filters: { officialId: off.id }, limit: 1000 }),
      zite.officialAvailability.findAll({ filters: { officialId: off.id }, limit: 1000 }),
      zite.officialEvaluations.findAll({ filters: { officialId: off.id }, limit: 200 }),
      zite.officialResources.findAll({ limit: 200 }),
    ]);
    const relevant = mine.records.filter((a) => !['Replaced', 'Removed'].includes(a.status ?? ''));
    const gameIds = [...new Set(relevant.map((a) => a.gameId ?? '').concat(evals.records.map((e) => e.gameId ?? '')).filter(Boolean))];
    const [games, venues, crewAll] = await Promise.all([
      gameIds.length ? zite.games.findAll({ filters: { id: { in: gameIds } } as never, limit: 1000 }) : Promise.resolve({ records: [] as never[] }),
      zite.venues.findAll({ limit: 200 }),
      gameIds.length ? zite.officialAssignments.findAll({ filters: { gameId: { in: gameIds } } as never, limit: 2000 }) : Promise.resolve({ records: [] as never[] }),
    ]);
    const gmap = new Map<string, Record<string, unknown>>((games.records as { id: string }[]).map((g) => [g.id, g as Record<string, unknown>]));
    const vmap = new Map(venues.records.map((v) => [v.id, v.name ?? '']));
    const omap = new Map(all.map((o) => [o.id, o.name ?? '']));
    const toAsg = (a: (typeof relevant)[number]) => {
      const g = gmap.get(a.gameId ?? '') ?? ({} as Record<string, unknown>);
      return {
        id: a.id, gameId: a.gameId ?? '', code: String(g.gameCode ?? ''), start: g.scheduledStart ? new Date(String(g.scheduledStart)).toISOString() : '',
        venue: vmap.get(String(g.venueId ?? '')) ?? '', homeTeamId: String(g.homeTeamId ?? ''), awayTeamId: String(g.awayTeamId ?? ''),
        position: a.position ?? '', status: a.status ?? '', gameStatus: String(g.status ?? ''),
        crew: (crewAll.records as { gameId?: string; officialId?: string; position?: string; status?: string }[])
          .filter((c) => c.gameId === a.gameId && !['Replaced', 'Removed', 'Declined'].includes(c.status ?? ''))
          .map((c) => ({ name: omap.get(c.officialId ?? '') ?? '', position: c.position ?? '', status: c.status ?? '' })),
      };
    };
    const list = relevant.map(toAsg).sort((x, y) => x.start.localeCompare(y.start));
    const now = new Date().toISOString();
    return {
      official: { id: off.id, name: off.name ?? '', email: off.email ?? '', phone: off.phone ?? '', type: off.officialType ?? '', level: off.level ?? '', hometown: off.hometown ?? '', bio: off.bio ?? '', photoUrl: off.photoUrl ?? '', years: Number(off.yearsExperience ?? 0) },
      upcoming: list.filter((a) => a.start >= now && !['Canceled', 'Final'].includes(a.gameStatus)),
      history: list.filter((a) => a.start < now || a.gameStatus === 'Final').reverse(),
      availability: avail.records.map((v) => ({ id: v.id, date: v.date ?? '', status: v.status ?? '', note: v.note ?? '' })).sort((a, b) => a.date.localeCompare(b.date)),
      // Only approved feedback; confidential notes are never returned.
      evaluations: evals.records.filter((e) => e.approved).map((e) => ({ id: e.id, title: e.title ?? '', score: Number(e.overallScore ?? 0), feedback: e.feedback ?? '', gameCode: String(gmap.get(e.gameId ?? '')?.gameCode ?? '') })),
      resources: res.records.sort((a, b) => String(b.publishedDate).localeCompare(String(a.publishedDate))).map((r) => ({ id: r.id, title: r.title ?? '', kind: r.kind ?? '', body: r.body ?? '', url: r.url ?? '', date: r.publishedDate ?? '' })),
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';
import { PUBLISHED } from '../lib/public';

export default createEndpoint({
  description: 'Global site search across teams, players, news and staff',
  inputSchema: z.object({ q: z.string() }),
  outputSchema: z.object({ results: z.array(z.object({ kind: z.string(), title: z.string(), subtitle: z.string(), href: z.string() })) }),
  execute: async ({ input }) => {
    const q = input.q.trim();
    if (q.length < 2) return { results: [] };
    const like = `%${q}%`;
    const [teams, players, arts, staff] = await Promise.all([
      zite.sql({ query: `SELECT id, "name", "city" FROM "Teams" WHERE "name" ILIKE $1 OR "city" ILIKE $1 OR "abbreviation" ILIKE $1 LIMIT 5`, params: [like] }),
      zite.sql({ query: `SELECT p.id, p."fullName" AS n, p."position" AS pos, t."abbreviation" AS t FROM "Players" p LEFT JOIN "Teams" t ON t.id::text = p."teamId" WHERE p."fullName" ILIKE $1 LIMIT 8`, params: [like] }),
      zite.sql({ query: `SELECT "slug", "title", "category" FROM "Articles" WHERE ${PUBLISHED} AND ("title" ILIKE $1 OR "excerpt" ILIKE $1) LIMIT 5`, params: [like] }),
      zite.sql({ query: `SELECT "name", "title" FROM "LeagueStaff" WHERE "isVisible" = true AND ("name" ILIKE $1 OR "title" ILIKE $1) LIMIT 4`, params: [like] }),
    ]);
    return {
      results: [
        ...teams.rows.map((r) => ({ kind: 'Team', title: String(r.name), subtitle: String(r.city ?? ''), href: `/teams/${r.id}` })),
        ...players.rows.map((r) => ({ kind: 'Player', title: String(r.n), subtitle: `${r.pos ?? ''} · ${r.t ?? ''}`, href: `/players/${r.id}` })),
        ...arts.rows.map((r) => ({ kind: 'News', title: String(r.title), subtitle: String(r.category ?? ''), href: `/news/${r.slug}` })),
        ...staff.rows.map((r) => ({ kind: 'Staff', title: String(r.name), subtitle: String(r.title ?? ''), href: '/staff' })),
      ],
    };
  },
});

import { z } from 'zod';
import { createEndpoint } from 'zitejs/backend';
import { zite } from 'zitejs/db';

export default createEndpoint({
  description: 'Saves a message from the public contact form',
  inputSchema: z.object({ name: z.string(), email: z.string(), topic: z.string(), subject: z.string(), message: z.string() }),
  outputSchema: z.object({ ok: z.boolean() }),
  execute: async ({ input }) => {
    const v = z.object({
      name: z.string().trim().min(2).max(100), email: z.string().trim().email().max(200),
      topic: z.enum(['General', 'Media', 'Tickets', 'Partnerships', 'Officiating', 'Player Inquiry']),
      subject: z.string().trim().min(3).max(200), message: z.string().trim().min(10).max(5000),
    }).safeParse(input);
    if (!v.success) throw new Error('Please complete every field with valid information.');
    await zite.contactMessages.create({ record: { ...v.data, status: 'New' } as never });
    return { ok: true };
  },
});

