const ICON: Record<string, string> = { Goal: '🚨', Penalty: '⚠', 'Goalie Change': '🥅', 'Injury Stoppage': '✚', 'Official Review': '🔍', 'Disallowed Goal': '✕', 'Shootout Attempt': '◎' };

export function PlayByPlay({ d }: { d: GameData }) {
  const periods = [...new Set(d.events.map((e) => e.period))].sort((a, b) => b - a);
  if (!d.events.length) return <p className="text-sm text-muted-foreground">No events yet. This timeline updates automatically.</p>;
  return (
    <div className="space-y-6">
      {periods.map((p) => (
        <div key={p}>
          <h3 className="mb-2 font-display text-lg font-bold uppercase">{p ? `${periodLabel(p)}${p <= 3 ? ' Period' : p === 4 ? ' — Overtime' : ' — Shootout'}` : 'Pre-game'}</h3>
          <ol className="relative space-y-1 border-l-2 border-border pl-5">
            {d.events.filter((e) => e.period === p).reverse().map((e) => (
              <li key={e.id} className={cn('relative rounded-md p-2.5 text-sm', e.type === 'Goal' && 'bg-accent/10 font-semibold', ['Shot'].includes(e.type) && 'py-1 text-muted-foreground')}>
                <span className={cn('absolute -left-[27px] top-3.5 h-2.5 w-2.5 rounded-full border-2 border-background', e.type === 'Goal' ? 'bg-accent' : 'bg-muted-foreground/50')} />
                <div className="flex items-start gap-3">
                  <span className="w-12 shrink-0 text-xs font-semibold tabular text-muted-foreground">{fmtClock(e.elapsed)}</span>
                  {e.teamId && <TeamLogo teamId={e.teamId} size={20} />}
                  <span className="flex-1">{ICON[e.type] ? <span className="mr-1">{ICON[e.type]}</span> : null}{e.summary}</span>
                  {e.type === 'Goal' && e.strength && e.strength !== 'Even Strength' && <Badge variant="outline">{e.strength}</Badge>}
                  {e.isGameWinner && <Badge>GWG</Badge>}
                </div>
              </li>
            ))}
          </ol>
        </div>
      ))}
    </div>
  );
}

export function BoxScore({ d, compact }: { d: GameData; compact?: boolean }) {
  const { team } = useSite();
  const g = d.game;
  const so = g.period >= 5 || g.shootoutHome || g.shootoutAway;
  const row = (tid: string, key: 'Goals' | 'Shots', home: boolean) => {
    const vals = d.byPeriod.map((p) => (home ? p[`home${key}`] : p[`away${key}`]));
    return (
      <tr className="border-t">
        <td className="px-3 py-2"><span className="flex items-center gap-2 font-semibold"><TeamLogo teamId={tid} size={22} />{team(tid)?.abbreviation}</span></td>
        {vals.map((v, i) => <td key={i} className="text-center tabular">{v}</td>)}
        {so && key === 'Goals' && <td className="text-center tabular">{home ? g.shootoutHome : g.shootoutAway}</td>}
        {so && key === 'Shots' && <td />}
        <td className="pr-3 text-center font-bold tabular">{vals.reduce((a, b) => a + b, 0)}</td>
      </tr>
    );
  };
  const head = (label: string) => (
    <thead><tr className="bg-muted/60 text-[11px] uppercase text-muted-foreground"><th className="px-3 py-1.5 text-left">{label}</th>{d.byPeriod.map((p) => <th key={p.period}>{periodLabel(p.period)}</th>)}{so && <th>SO</th>}<th className="pr-3">T</th></tr></thead>
  );
  return (
    <div className={cn('grid gap-4', !compact && 'md:grid-cols-2')}>
      <div className="overflow-hidden rounded-lg border bg-card"><table className="w-full text-sm">{head('Goals')}<tbody>{row(g.awayTeamId, 'Goals', false)}{row(g.homeTeamId, 'Goals', true)}</tbody></table></div>
      <div className="overflow-hidden rounded-lg border bg-card"><table className="w-full text-sm">{head('Shots')}<tbody>{row(g.awayTeamId, 'Shots', false)}{row(g.homeTeamId, 'Shots', true)}</tbody></table></div>
      {!compact && (
        <div className="overflow-x-auto rounded-lg border bg-card md:col-span-2">
          <h3 className="px-3 pt-3 font-display text-lg font-bold uppercase">Penalties</h3>
          <table className="w-full text-sm"><tbody>
            {d.events.filter((e) => e.type === 'Penalty').map((e) => (
              <tr key={e.id} className="border-t"><td className="px-3 py-2 text-xs text-muted-foreground">{periodLabel(e.period)} {fmtClock(e.elapsed)}</td><td><TeamLogo teamId={e.teamId} size={20} /></td><td className="py-2">{e.summary}</td></tr>
            ))}
            {!d.events.some((e) => e.type === 'Penalty') && <tr><td className="px-3 py-3 text-muted-foreground">No penalties.</td></tr>}
          </tbody></table>
        </div>
      )}
