  );
}

export function TeamStats({ d, compact }: { d: GameData; compact?: boolean }) {
  const { team } = useSite();
  const { home, away } = d.teamStats;
  const rows: [string, (s: Record<string, number>) => string | number][] = [
    ['Shots on goal', (s) => s.shots], ['Power play', (s) => `${s.ppGoals}/${s.ppOpportunities}`], ['Shorthanded goals', (s) => s.shGoals],
    ['Penalties', (s) => s.penalties], ['Penalty minutes', (s) => s.pim], ['Saves', (s) => s.saves],
  ];
  return (
    <div className="rounded-lg border bg-card p-4">
      {compact && <h3 className="mb-2 font-display text-lg font-bold uppercase">Team stats</h3>}
      <div className="mb-2 flex justify-between font-display font-bold uppercase"><span>{team(d.game.awayTeamId)?.abbreviation}</span><span>{team(d.game.homeTeamId)?.abbreviation}</span></div>
      {rows.map(([label, f]) => {
        const a = Number(String(f(away)).split('/')[0]), h = Number(String(f(home)).split('/')[0]);
        const pct = a + h ? (a / (a + h)) * 100 : 50;
        return (
          <div key={label} className="py-1.5">
            <div className="flex justify-between text-sm"><span className="font-bold tabular">{f(away)}</span><span className="text-xs uppercase text-muted-foreground">{label}</span><span className="font-bold tabular">{f(home)}</span></div>
            <div className="mt-1 flex h-1.5 overflow-hidden rounded-full bg-muted"><div className="bg-primary" style={{ width: `${pct}%` }} /><div className="flex-1 bg-accent" /></div>
          </div>
        );
      })}
    </div>
  );
}

