function initials(name: string) { return name.split(' ').filter(Boolean).map((x) => x[0]).join('').slice(0, 2).toUpperCase(); }

function OfficialPhoto({ name, url }: { name: string; url: string }) {
  const [failed, setFailed] = useState(false);
  if (url && !failed) return <img src={url} alt={name} loading="lazy" onError={() => setFailed(true)} className="h-24 w-24 rounded-full object-cover ring-2 ring-border" />;
  return <span aria-label={name} className="flex h-24 w-24 items-center justify-center rounded-full bg-primary font-display text-3xl font-bold text-primary-foreground ring-2 ring-border">{initials(name)}</span>;
}

export function Officials({ d }: { d: GameData }) {
  if (!d.officials.length) return <p className="text-sm text-muted-foreground">Officials for this game have not been confirmed yet.</p>;
  return (
    <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
      {d.officials.map((o, i) => (
        <div key={`${o.id}-${i}`} className="flex flex-col items-center rounded-lg border bg-card p-5 text-center">
          <OfficialPhoto name={o.name} url={o.photoUrl} />
          <div className="mt-3 text-xs font-bold uppercase tracking-widest text-accent">{o.position}</div>
          <div className="mt-1 font-display text-xl font-bold uppercase leading-tight">{o.name}</div>
          {(o.level || o.hometown) && <div className="mt-1 text-xs text-muted-foreground">{[o.level, o.hometown].filter(Boolean).join(' · ')}</div>}
          {o.years > 0 && <div className="text-xs text-muted-foreground">{o.years} years officiating</div>}
        </div>
      ))}
    </div>
  );
}

const callText = (c: string) => (c === 'No Goal' ? 'No goal' : c === 'Good Goal' ? 'Good goal' : 'Under review');

