            <div className={cn('rounded px-3 py-2', r.callAfterReview === 'No Goal' ? 'bg-destructive/10' : r.callAfterReview === 'Good Goal' ? 'bg-emerald-500/10' : 'bg-accent/10')}><div className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Call after review</div><div className="font-semibold">{callText(r.callAfterReview)}</div></div>
