export type GameT = GetHomeOutputType['live'][number];

export default function GameTile({ g, now, compact = false }: { g: GameT; now: number; compact?: boolean }) {
  const { team } = useSite();
  const live = isLive(g.status);
  const showScore = g.status !== 'Scheduled' && g.status !== 'Postponed' && g.status !== 'Canceled';
  const row = (tid: string, score: number) => {
    const won = g.status === 'Final' && score > (tid === g.homeTeamId ? g.awayScore : g.homeScore);
    return (
      <div className="flex items-center gap-2.5">
        <TeamLogo teamId={tid} size={compact ? 26 : 32} />
        <span className={cn('flex-1 truncate font-display text-lg font-semibold uppercase leading-none', won && 'font-extrabold')}>{compact ? team(tid)?.abbreviation : team(tid)?.name}</span>
        {showScore && <span className={cn('font-display text-2xl font-bold tabular leading-none', !won && g.status === 'Final' && 'text-muted-foreground')}>{score}</span>}
      </div>
    );
  };
  return (
    <Link to={`/games/${g.id}`} className={cn('group block rounded-lg border bg-card p-3.5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md', live && 'border-accent/50 ring-1 ring-accent/30')}>
      <div className="mb-2.5 flex items-center justify-between text-[11px] font-semibold uppercase tracking-wider">
        <span className={cn('flex items-center gap-1.5', live ? 'text-accent' : 'text-muted-foreground')}>
          {live && <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-accent" />}
          {g.status === 'Scheduled' ? fmtDate(g.start) : null}{g.status === 'Scheduled' ? ' · ' : ''}{statusLine(g, now)}
        </span>
        <span className="text-muted-foreground">{g.gameType !== 'Regular Season' ? g.gameType : g.code}</span>
      </div>
      <div className="space-y-2">{row(g.awayTeamId, g.awayScore)}{row(g.homeTeamId, g.homeScore)}</div>
      {(g.note || g.originalStart || g.status === 'Postponed' || g.status === 'Canceled') && (
        <p className={cn('mt-2.5 truncate text-xs', ['Postponed', 'Canceled'].includes(g.status) ? 'font-semibold text-accent' : 'text-muted-foreground')}>
          {['Postponed', 'Canceled'].includes(g.status) ? `${g.status} · ` : ''}{g.note || (g.originalStart ? `Rescheduled from ${fmtDate(g.originalStart)}` : '')}
        </p>
      )}
    </Link>
  );
}

