import { useEffect, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { Bell } from 'lucide-react';
import { useAuth } from 'zitejs/auth';
import { myFavorites, type MyFavoritesOutputType } from 'zitejs/api';
import { Button } from '@project/components/ui/button';
import { Popover, PopoverContent, PopoverTrigger } from '@project/components/ui/popover';

type N = MyFavoritesOutputType['notifications'][number];

export default function NotificationBell() {
  const { user } = useAuth();
  const [items, setItems] = useState<N[]>([]);
  const seen = useRef<Set<string> | null>(null);
  useEffect(() => {
    if (!user) return;
    const load = () => myFavorites({ action: 'list' }).then((r) => {
      if (seen.current && typeof Notification !== 'undefined' && Notification.permission === 'granted') {
        r.notifications.filter((n) => !n.isRead && !seen.current!.has(n.id)).slice(0, 3).forEach((n) => new Notification(n.title, { body: n.body }));
      }
      seen.current = new Set(r.notifications.map((n) => n.id));
      setItems(r.notifications);
    }).catch(() => undefined);
    load();
    const t = setInterval(load, 30000);
    return () => clearInterval(t);
  }, [user]);
  if (!user) return null;
  const unread = items.filter((n) => !n.isRead).length;
  return (
    <Popover onOpenChange={(o) => { if (!o && unread) myFavorites({ action: 'markRead' }).then((r) => setItems(r.notifications)).catch(() => undefined); }}>
      <PopoverTrigger asChild>
        <Button size="icon" variant="ghost" className="relative text-primary-foreground hover:bg-white/10 hover:text-primary-foreground" aria-label="Alerts">
          <Bell className="h-5 w-5" />
          {unread > 0 && <span className="absolute right-1 top-1 flex h-4 min-w-4 items-center justify-center rounded-full bg-accent px-1 text-[10px] font-bold">{unread}</span>}
        </Button>
      </PopoverTrigger>
      <PopoverContent align="end" className="w-80 p-0">
        <div className="flex items-center justify-between border-b px-3 py-2"><span className="font-display font-bold uppercase">Alerts</span><Link to="/account" className="text-xs text-accent">Settings</Link></div>
        <div className="max-h-80 overflow-y-auto">
          {items.length === 0 && <p className="p-6 text-center text-sm text-muted-foreground">Follow teams or players to get game alerts.</p>}
          {items.map((n) => (
            <Link key={n.id} to={n.link || '/'} className={`block border-b px-3 py-2.5 text-sm last:border-0 hover:bg-muted ${n.isRead ? '' : 'bg-accent/5'}`}>
              <div className="font-semibold">{n.title}</div>
              <div className="text-xs text-muted-foreground">{n.body}</div>
            </Link>
          ))}
        </div>
      </PopoverContent>
    </Popover>
  );
}

