export default function PuckDropCountdown({ pd, now }: { pd: PD; now: number }) {
  const { team } = useSite();
  const g = pd.game;
  const ms = Math.max(0, Date.parse(g.start) - now);
  const s = Math.floor(ms / 1000);
  const [d, h, m, sec] = [Math.floor(s / 86400), Math.floor((s % 86400) / 3600), Math.floor((s % 3600) / 60), s % 60];
  const when = new Date(g.start).toLocaleString(undefined, { weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
  const away = team(g.awayTeamId), home = team(g.homeTeamId);
  return (
    <section className="relative overflow-hidden border-b bg-gradient-to-r from-primary to-primary/90 text-primary-foreground">
      <div className="mx-auto grid max-w-7xl items-center gap-6 px-4 py-6 lg:grid-cols-[1fr_auto_1fr]">
        <Link to={`/games/${g.id}`} className="flex items-center justify-center gap-4 lg:justify-start">
          <div className="flex flex-col items-center gap-1"><TeamLogo teamId={g.awayTeamId} size={52} /><span className="text-xs font-semibold">{away?.name}</span></div>
          <span className="font-display text-2xl font-bold text-accent">@</span>
          <div className="flex flex-col items-center gap-1"><TeamLogo teamId={g.homeTeamId} size={52} /><span className="text-xs font-semibold">{home?.name}</span></div>
        </Link>
        <div className="text-center">
          <div className="mb-2 text-xs font-bold uppercase tracking-[0.3em] text-accent">{ms > 0 ? 'Countdown to puck drop' : 'Puck drop!'}</div>
          <div className="flex justify-center gap-2">
            {d > 0 && <Unit v={d} label="Days" />}<Unit v={h} label="Hrs" /><Unit v={m} label="Min" /><Unit v={sec} label="Sec" />
          </div>
          <div className="mt-2 flex items-center justify-center gap-1 text-xs text-primary-foreground/75"><MapPin className="h-3 w-3" />{when}{g.venue && ` · ${g.venue}`}</div>
          {ms > 0 && <Link to={`/tickets/${g.id}`} className="mt-3 inline-block rounded-md bg-accent px-4 py-1.5 text-xs font-bold uppercase tracking-wider text-accent-foreground hover:bg-accent/90">Buy tickets</Link>}
        </div>
        <div className="text-center lg:text-right">
          <div className="mb-1 flex items-center justify-center gap-1 text-xs font-bold uppercase tracking-widest text-accent lg:justify-end"><Flag className="h-3 w-3" />Officiating crew</div>
          {pd.officials.length ? (
            <ul className="space-y-0.5 text-sm">
              {pd.officials.map((o) => <li key={o.position + o.name}><span className="text-primary-foreground/60">{o.position}:</span> <span className="font-semibold">{o.name}</span></li>)}
            </ul>
          ) : <p className="text-sm text-primary-foreground/60">To be announced</p>}
        </div>
      </div>
    </section>
  );
}

