import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDebouncedCallback } from 'use-debounce';
import { Loader2, Search } from 'lucide-react';
import { search, type SearchOutputType } from 'zitejs/api';
import { Dialog, DialogContent, DialogTitle } from '@project/components/ui/dialog';
import { Input } from '@project/components/ui/input';
import { Badge } from '@project/components/ui/badge';

export default function SearchDialog({ open, onOpenChange }: { open: boolean; onOpenChange: (o: boolean) => void }) {
  const [q, setQ] = useState('');
  const [res, setRes] = useState<SearchOutputType['results']>([]);
  const [loading, setLoading] = useState(false);
  const nav = useNavigate();
  const run = useDebouncedCallback((v: string) => {
    if (v.trim().length < 2) { setRes([]); setLoading(false); return; }
    search({ q: v }).then((r) => setRes(r.results)).catch(() => setRes([])).finally(() => setLoading(false));
  }, 300);
  useEffect(() => { if (!open) { setQ(''); setRes([]); } }, [open]);
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="top-[15%] translate-y-0 gap-0 p-0 sm:max-w-xl">
        <DialogTitle className="sr-only">Search</DialogTitle>
        <div className="flex items-center gap-2 border-b px-4">
          <Search className="h-4 w-4 text-muted-foreground" />
          <Input autoFocus value={q} onChange={(e) => { setQ(e.target.value); setLoading(true); run(e.target.value); }} placeholder="Search teams, players, news, staff…" className="h-14 border-0 shadow-none focus-visible:ring-0" />
          {loading && <Loader2 className="h-4 w-4 animate-spin" />}
        </div>
        <div className="max-h-96 overflow-y-auto p-2">
          {q.length >= 2 && !loading && res.length === 0 && <p className="p-6 text-center text-sm text-muted-foreground">No results for “{q}”.</p>}
          {res.map((r, i) => (
            <button key={i} onClick={() => { onOpenChange(false); nav(r.href); }} className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-left hover:bg-muted">
              <Badge variant="outline" className="w-16 justify-center">{r.kind}</Badge>
              <span className="flex-1 truncate font-medium">{r.title}</span>
              <span className="truncate text-xs text-muted-foreground">{r.subtitle}</span>
            </button>
          ))}
        </div>
      </DialogContent>
    </Dialog>
  );
}

import { memo } from 'react';
import { cn } from '@project/components/lib/utils';
import { seatId, SIDE_NAME, TIER_NAME, TIER_PRICE, type Layout, type Side, type Tier } from '../lib/seating';

type Props = { layout: Layout; sold: Set<string>; selected: Set<string>; onToggle: (id: string) => void; disabled?: boolean };

const TIER_STYLE: Record<Tier, string> = {
  R: 'bg-accent/80 hover:bg-accent',
  L: 'bg-sky-600/80 hover:bg-sky-600',
  U: 'bg-slate-400 hover:bg-slate-500',
};

// Tiers ordered from the ice outward.
const TIERS: Tier[] = ['R', 'L', 'U'];

function Seat({ id, tier, sold, selected, onToggle, disabled }: { id: string; tier: Tier; sold: boolean; selected: boolean; onToggle: (id: string) => void; disabled?: boolean }) {
  const [, , row, n] = id.split('-');
  return (
    <button
      type="button"
      disabled={sold || disabled}
      onClick={() => onToggle(id)}
      title={sold ? 'Sold' : `Row ${row}, Seat ${n} · $${TIER_PRICE[tier]}`}
      aria-label={`${id}${sold ? ' sold' : ''}`}
      className={cn('h-3.5 w-3.5 rounded-[3px] transition sm:h-4 sm:w-4',
        sold ? 'cursor-not-allowed bg-muted-foreground/25' : selected ? 'scale-110 bg-emerald-500 ring-2 ring-emerald-300' : TIER_STYLE[tier])}
    />
  );
}

function Block({ side, layout, ...p }: { side: Side } & Props) {
  const vertical = side === 'W' || side === 'E';
  const width = vertical ? layout.end : layout.long;
  // rows listed so the rinkside row touches the ice
  const rows = TIERS.flatMap((t) => Array.from({ length: layout.rows[t] }, (_, i) => ({ t, r: i + 1 })));
  const ordered = side === 'N' || side === 'W' ? [...rows].reverse() : rows;
  return (
    <div className={cn('flex gap-1', vertical ? 'flex-row' : 'flex-col', 'items-center justify-center')}>
      {ordered.map(({ t, r }) => (
        <div key={`${t}${r}`} className={cn('flex gap-1', vertical ? 'flex-col' : 'flex-row', (t === 'L' && r === 1) || (t === 'U' && r === 1) ? (side === 'N' ? 'mb-1.5' : side === 'S' ? 'mt-1.5' : side === 'W' ? 'mr-1.5' : 'ml-1.5') : '')}>
          {Array.from({ length: width }, (_, i) => {
            const id = seatId(side, t, r, i + 1);
            return <Seat key={id} id={id} tier={t} sold={p.sold.has(id)} selected={p.selected.has(id)} onToggle={p.onToggle} disabled={p.disabled} />;
          })}
        </div>
      ))}
    </div>
  );
}

