export type Col<T> = { key: string; label: string; render?: (r: T, i: number) => ReactNode; sortValue?: (r: T) => number | string; left?: boolean; title?: string };

export default function SortTable<T extends Record<string, any>>({ cols, rows, initial, desc = true, rowKey, pageSize = 0 }: { cols: Col<T>[]; rows: T[]; initial?: string; desc?: boolean; rowKey: (r: T) => string; pageSize?: number }) {
  const [sort, setSort] = useState<{ key: string; desc: boolean } | null>(initial ? { key: initial, desc } : null);
  const [page, setPage] = useState(0);
  const sorted = useMemo(() => {
    if (!sort) return rows;
    const col = cols.find((c) => c.key === sort.key);
    const v = (r: T) => (col?.sortValue ? col.sortValue(r) : r[sort.key]);
    return [...rows].sort((a, b) => { const x = v(a), y = v(b); const c = typeof x === 'number' && typeof y === 'number' ? x - y : String(x).localeCompare(String(y)); return sort.desc ? -c : c; });
  }, [rows, sort, cols]);
  const pages = pageSize ? Math.max(1, Math.ceil(sorted.length / pageSize)) : 1;
  const shown = pageSize ? sorted.slice(page * pageSize, page * pageSize + pageSize) : sorted;
  return (
    <div className="overflow-hidden rounded-lg border bg-card">
      <div className="overflow-x-auto">
        <table className="w-full text-sm">
          <thead>
            <tr className="bg-primary text-[11px] uppercase tracking-wider text-primary-foreground">
              {cols.map((c) => (
                <th key={c.key} title={c.title} className={cn('cursor-pointer select-none whitespace-nowrap px-2.5 py-2.5', c.left ? 'text-left' : 'text-center')} onClick={() => { setPage(0); setSort((s) => ({ key: c.key, desc: s?.key === c.key ? !s.desc : true })); }}>
                  <span className="inline-flex items-center gap-1">{c.label}{sort?.key === c.key && (sort.desc ? <ArrowDown className="h-3 w-3" /> : <ArrowUp className="h-3 w-3" />)}</span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {shown.map((r, i) => (
              <tr key={rowKey(r)} className="border-t transition-colors hover:bg-muted/50">
                {cols.map((c) => <td key={c.key} className={cn('whitespace-nowrap px-2.5 py-2 tabular', c.left ? 'text-left' : 'text-center', sort?.key === c.key && 'bg-muted/40 font-semibold')}>{c.render ? c.render(r, page * pageSize + i) : r[c.key]}</td>)}
              </tr>
            ))}
            {shown.length === 0 && <tr><td colSpan={cols.length} className="px-3 py-8 text-center text-muted-foreground">No data yet.</td></tr>}
          </tbody>
        </table>
      </div>
      {pages > 1 && (
        <div className="flex items-center justify-between border-t px-3 py-2 text-sm">
          <span className="text-muted-foreground">Page {page + 1} of {pages}</span>
          <span className="flex gap-2">
            <button className="rounded border px-3 py-1 disabled:opacity-40" disabled={page === 0} onClick={() => setPage((p) => p - 1)}>Prev</button>
            <button className="rounded border px-3 py-1 disabled:opacity-40" disabled={page >= pages - 1} onClick={() => setPage((p) => p + 1)}>Next</button>
          </span>
        </div>
      )}
    </div>
  );
}

