/** Loads data, optionally polls, and keeps the last good data through transient server errors. */
export function useLoad<T>(fn: () => Promise<T>, deps: unknown[], pollMs?: number) {
  const [data, setData] = useState<T | null>(null);
  const [error, setError] = useState<string | null>(null);
  const fnRef = useRef(fn);
  fnRef.current = fn;
  const load = useCallback(async () => {
    try { const d = await fnRef.current(); setData(d); setError(null); } catch (e) { setError(errMsg(e)); }
  }, []);
  useEffect(() => {
    setData(null); setError(null); load();
    if (!pollMs) return;
    const t = setInterval(load, pollMs);
    return () => clearInterval(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps);
  return { data, error, reload: load };
}

