export function FollowButton({ teamId, playerId, className }: { teamId?: string; playerId?: string; className?: string }) {
  const { user } = useAuth();
  const [following, setFollowing] = useState<boolean | null>(null);
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    if (!user) return;
    myFavorites({ action: 'list' }).then((r) => setFollowing(r.favorites.some((f) => (teamId && f.teamId === teamId) || (playerId && f.playerId === playerId)))).catch(() => undefined);
  }, [user, teamId, playerId]);
  const toggle = async () => {
    if (!user) return loginWithRedirect();
    setBusy(true);
    const next = !following;
    setFollowing(next);
    try { await myFavorites({ action: next ? 'follow' : 'unfollow', teamId, playerId }); toast(next ? 'Added to favorites — alerts on' : 'Removed from favorites'); }
    catch (e) { setFollowing(!next); toast.error(errMsg(e)); }
    finally { setBusy(false); }
  };
  return (
    <Button variant={following ? 'secondary' : 'outline'} size="sm" onClick={toggle} disabled={busy} className={className}>
      <Star className={`mr-1.5 h-4 w-4 ${following ? 'fill-accent text-accent' : ''}`} />{following ? 'Following' : 'Follow'}
    </Button>
  );
}

