  start: z.string(), originalStart: z.string(), status: z.string(), gameType: z.string(), playoffRound: z.string(),
  homeScore: z.number(), awayScore: z.number(), homeShots: z.number(), awayShots: z.number(),
  shootoutHome: z.number(), shootoutAway: z.number(),
  period: z.number(), clockRunning: z.boolean(), clockRemaining: z.number(), clockAnchorAt: z.string(),
  intermissionEndsAt: z.string(), decision: z.string(), note: z.string(), isDemo: z.boolean(),
});
export type GameSummaryT = z.infer<typeof GameSummary>;

const iso = (v: unknown) => (v ? new Date(String(v)).toISOString() : '');

export async function queryGames(where: string, params: unknown[] = [], limit = 500, order = 'ASC'): Promise<GameSummaryT[]> {
  const { rows } = await zite.sql({
    query: `SELECT g.id, g."gameCode" AS code, g."homeTeamId" AS h, g."awayTeamId" AS a, v."name" AS venue,
      g."scheduledStart" AS start, g."originalStart" AS ostart, g."status" AS status, g."gameType" AS gt, g."playoffRound" AS pr,
      g."homeScore" AS hs, g."awayScore" AS vs, g."homeShots" AS hsh, g."awayShots" AS ash, g."shootoutHomeGoals" AS soh, g."shootoutAwayGoals" AS soa,
      g."period" AS period, g."clockRunning" AS cr, g."clockRemaining" AS crem, g."clockAnchorAt" AS ca, g."intermissionEndsAt" AS ie,
      g."decision" AS decision, g."statusNote" AS note, g."isDemo" AS demo
      FROM "Games" g LEFT JOIN "Venues" v ON v.id::text = g."venueId"
      WHERE ${where} ORDER BY g."scheduledStart" ${order === 'DESC' ? 'DESC' : 'ASC'} LIMIT ${Math.min(limit, 2000)}`,
    params,
  });
  return rows.map((r) => ({
    id: String(r.id), code: String(r.code ?? ''), homeTeamId: String(r.h ?? ''), awayTeamId: String(r.a ?? ''), venue: String(r.venue ?? ''),
    start: iso(r.start), originalStart: iso(r.ostart), status: String(r.status ?? 'Scheduled'), gameType: String(r.gt ?? ''), playoffRound: String(r.pr ?? ''),
    homeScore: Number(r.hs ?? 0), awayScore: Number(r.vs ?? 0), homeShots: Number(r.hsh ?? 0), awayShots: Number(r.ash ?? 0),
    shootoutHome: Number(r.soh ?? 0), shootoutAway: Number(r.soa ?? 0),
    period: Number(r.period ?? 0), clockRunning: !!r.cr, clockRemaining: Number(r.crem ?? 0), clockAnchorAt: iso(r.ca),
    intermissionEndsAt: iso(r.ie), decision: String(r.decision ?? ''), note: String(r.note ?? ''), isDemo: !!r.demo,
  }));
}

