// Deterministic per-venue seat map, derived from the venue's capacity.
// Shared by the seat map UI and the purchase endpoint (validation + pricing).

export type Side = 'N' | 'S' | 'W' | 'E';
export type Tier = 'R' | 'L' | 'U';
export const TIER_PRICE: Record<Tier, number> = { R: 40, L: 25, U: 15 };
export const TIER_NAME: Record<Tier, string> = { R: 'Glass / Rinkside', L: 'Lower Bowl', U: 'Upper Bowl' };
export const SIDE_NAME: Record<Side, string> = { N: 'North', S: 'South', W: 'West End', E: 'East End' };

export type Layout = { long: number; end: number; rows: Record<Tier, number> };

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, Math.round(v)));

export function layoutFor(capacity: number): Layout {
  const cap = capacity > 0 ? capacity : 2500;
  const long = clamp(cap / 160, 12, 30);
  return { long, end: clamp(long * 0.5, 6, 16), rows: { R: 2, L: clamp(cap / 800, 3, 8), U: clamp(cap / 1000, 2, 7) } };
}

export const seatId = (side: Side, tier: Tier, row: number, n: number) => `${side}-${tier}-${row}-${n}`;

export function parseSeat(id: string, layout: Layout) {
  const [side, tier, r, s] = id.split('-');
  const row = Number(r), n = Number(s);
  if (!['N', 'S', 'W', 'E'].includes(side) || !['R', 'L', 'U'].includes(tier)) return null;
  const width = side === 'N' || side === 'S' ? layout.long : layout.end;
  if (!Number.isInteger(row) || !Number.isInteger(n) || row < 1 || row > layout.rows[tier as Tier] || n < 1 || n > width) return null;
  const t = tier as Tier, sd = side as Side;
  return {
    id, side: sd, tier: t, row, n, price: TIER_PRICE[t],
    section: `${SIDE_NAME[sd]} ${TIER_NAME[t]}`,
    label: `${SIDE_NAME[sd]} ${TIER_NAME[t]} · Row ${row} · Seat ${n}`,
  };
}

export const totalSeats = (l: Layout) => (l.rows.R + l.rows.L + l.rows.U) * (l.long * 2 + l.end * 2);

import { createContext, useContext, useEffect, useRef, useState, type ReactNode } from 'react';
import { getSite, type GetSiteOutputType } from 'zitejs/api';
import { TIER_PRICE } from './seating';

type Site = GetSiteOutputType;
type Team = Site['teams'][number];
const Ctx = createContext<{ site: Site | null; team: (id?: string) => Team | undefined }>({ site: null, team: () => undefined });

export function SiteProvider({ children }: { children: ReactNode }) {
  const [site, setSite] = useState<Site | null>(null);
  useEffect(() => {
    let tries = 0;
    const load = () => getSite({}).then((s) => { Object.assign(TIER_PRICE, s.settings.prices); setSite(s); }).catch(() => { if (tries++ < 5) setTimeout(load, 2000 * tries); });
    load();
  }, []);
  const team = (id?: string) => site?.teams.find((t) => t.id === id);
  return <Ctx.Provider value={{ site, team }}>{children}</Ctx.Provider>;
}
export const useSite = () => useContext(Ctx);

export const LIVE = ['Warmup', 'Live', 'Intermission', 'Overtime', 'Shootout', 'Suspended'];
export const isLive = (s: string) => LIVE.includes(s);

export const periodLabel = (p: number) => (p === 4 ? 'OT' : p >= 5 ? 'SO' : ['', '1st', '2nd', '3rd'][p] ?? '');
export const fmtClock = (sec: number) => { const t = Math.max(0, Math.ceil(sec)); return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`; };
export const tz = () => new Intl.DateTimeFormat(undefined, { timeZoneName: 'short' }).formatToParts(new Date()).find((p) => p.type === 'timeZoneName')?.value ?? '';
export const fmtTime = (iso: string) => (iso ? new Date(iso).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' }) : 'TBD');
export const fmtDate = (iso: string, opts: Intl.DateTimeFormatOptions = { weekday: 'short', month: 'short', day: 'numeric' }) => (iso ? new Date(iso).toLocaleDateString(undefined, opts) : '');
export const fmtDateTime = (iso: string) => (iso ? `${fmtDate(iso)} · ${fmtTime(iso)}` : 'TBD');

/** Keeps a server-synchronized "now" so every visitor computes the same clock. */
export function useServerNow(serverNow?: number) {
  const offset = useRef(0);
  const [now, setNow] = useState(Date.now());
  useEffect(() => { if (serverNow) offset.current = serverNow - Date.now(); }, [serverNow]);
  useEffect(() => { const t = setInterval(() => setNow(Date.now()), 500); return () => clearInterval(t); }, []);
  return now + offset.current;
}

export type ClockGame = { status: string; period: number; clockRunning: boolean; clockRemaining: number; clockAnchorAt: string; intermissionEndsAt: string; start: string };
export function liveRemaining(g: ClockGame, now: number) {
  if (g.status === 'Intermission' && g.intermissionEndsAt) return Math.max(0, (Date.parse(g.intermissionEndsAt) - now) / 1000);
  if (g.clockRunning && g.clockAnchorAt) return Math.max(0, g.clockRemaining - (now - Date.parse(g.clockAnchorAt)) / 1000);
  return g.clockRemaining;
}
export function statusLine(g: ClockGame & { decision?: string; note?: string }, now: number) {
  if (g.status === 'Final') return g.decision && g.decision !== 'Regulation' ? `Final/${g.decision === 'Overtime' ? 'OT' : 'SO'}` : 'Final';
  if (g.status === 'Scheduled') {
    const ms = Date.parse(g.start) - now;
    if (ms > 0 && ms < 6 * 3600000) { const s = Math.floor(ms / 1000); return `Starts in ${Math.floor(s / 3600) ? `${Math.floor(s / 3600)}h ` : ''}${Math.floor((s % 3600) / 60)}m ${s % 60}s`; }
    return fmtTime(g.start);
  }
  if (g.status === 'Intermission') return `${periodLabel(g.period)} INT · ${fmtClock(liveRemaining(g, now))}`;
  if (g.status === 'Shootout') return 'Shootout';
  if (['Live', 'Overtime'].includes(g.status)) return `${periodLabel(g.period)} · ${fmtClock(liveRemaining(g, now))}`;
  return g.status;
}

export function errMsg(e: unknown) {
  const x = e as { userFacingMessage?: string; message?: string };
  return x?.userFacingMessage || x?.message || 'Something went wrong';
}

export const IMG = {
  hero: 'https://images.fillout.com/890725/agiclmstru/generated-images/fg9m8pD6Vg6xD1BKGytbUd/img_ejxkiL3LWAkZRmGf.jpg',
};

export function fmtCountdown(ms: number) {
  if (ms <= 0) return '—';
  const s = Math.floor(ms / 1000);
  if (s >= 86400) return `${Math.floor(s / 86400)}d ${Math.floor((s % 86400) / 3600)}h`;
  const h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60), sec = s % 60;
  return `${h ? `${h}:` : ''}${h ? String(m).padStart(2, '0') : m}:${String(sec).padStart(2, '0')}`;
}

// Shared statistics + standings queries (same file in both NFHL apps: src/lib/stats.ts).
// Everything is computed from FINAL games and their recorded event log, so totals always agree.
import { zite } from 'zitejs/db';
import type { Settings } from './engine';

const n = (v: unknown) => Number(v ?? 0);

export async function skaterStats(seasonId: string, teamId = '', playerId = '') {
  const { rows } = await zite.sql({
    query: `
      WITH fg AS (
        SELECT id::text AS gid, "homeTeamId" AS h, "awayTeamId" AS a FROM "Games"
        WHERE "status" = 'Final' AND ($1 = '' OR "seasonId" = $1)
      ),
      ev AS (
        SELECT e."gameId" AS gid, e."eventType" AS t, e."playerId" AS pid, e."assist1Id" AS a1, e."assist2Id" AS a2,
          e."strength" AS st, e."penaltyMinutes" AS pim, e."isGameWinner" AS gw
        FROM "GameEvents" e JOIN fg ON fg.gid = e."gameId"
        WHERE COALESCE(e."isVoid", false) = false AND e."eventType" IN ('Goal','Shot','Penalty')
      ),
      tgp AS (SELECT tid, COUNT(*) AS gp FROM (SELECT h AS tid FROM fg UNION ALL SELECT a FROM fg) z GROUP BY tid)
      SELECT p.id, p."fullName" AS name, p."teamId" AS "teamId", p."position" AS pos, p."jerseyNumber" AS num,
        COALESCE(tgp.gp, 0) AS gp,
        COUNT(ev.t) FILTER (WHERE ev.t = 'Goal' AND ev.pid = p.id::text) AS g,
        COUNT(ev.t) FILTER (WHERE ev.t = 'Goal' AND (ev.a1 = p.id::text OR ev.a2 = p.id::text)) AS a,
        COUNT(ev.t) FILTER (WHERE ev.t = 'Goal' AND ev.pid = p.id::text AND ev.st = 'Power Play') AS ppg,
        COUNT(ev.t) FILTER (WHERE ev.t = 'Goal' AND ev.pid = p.id::text AND ev.st = 'Shorthanded') AS shg,
        COUNT(ev.t) FILTER (WHERE ev.t = 'Goal' AND ev.pid = p.id::text AND ev.gw = true) AS gwg,
        COUNT(ev.t) FILTER (WHERE ev.t IN ('Goal','Shot') AND ev.pid = p.id::text) AS shots,
        COALESCE(SUM(ev.pim) FILTER (WHERE ev.t = 'Penalty' AND ev.pid = p.id::text), 0) AS pim
      FROM "Players" p
      LEFT JOIN tgp ON tgp.tid = p."teamId"
      LEFT JOIN ev ON (ev.pid = p.id::text OR ev.a1 = p.id::text OR ev.a2 = p.id::text)
      WHERE p."position" <> 'G' AND ($2 = '' OR p."teamId" = $2) AND ($3 = '' OR p.id::text = $3)
      GROUP BY p.id, tgp.gp`,
    params: [seasonId, teamId, playerId],
  });
  return rows.map((r) => {
    const g = n(r.g), a = n(r.a), gp = n(r.gp);
    return {
      id: String(r.id), name: String(r.name ?? ''), teamId: String(r.teamId ?? ''), pos: String(r.pos ?? ''),
      num: n(r.num), gp, g, a, pts: g + a, ppg: n(r.ppg), shg: n(r.shg), gwg: n(r.gwg),
      shots: n(r.shots), pim: n(r.pim), ppgPerGame: gp ? +((g + a) / gp).toFixed(2) : 0,
    };
  });
}

export async function goalieStats(seasonId: string, teamId = '', playerId = '') {
  const { rows } = await zite.sql({
    query: `
      WITH fg AS (
        SELECT id::text AS gid, "winningGoalieId" AS wg, "losingGoalieId" AS lg, "decision" AS d,
          "homeGoalieId" AS hg, "awayGoalieId" AS ag, COALESCE("homeScore",0) AS hs, COALESCE("awayScore",0) AS vs
        FROM "Games" WHERE "status" = 'Final' AND ($1 = '' OR "seasonId" = $1)
      ),
      ev AS (
        SELECT e."gameId" AS gid, e."eventType" AS t, e."goalieId" AS gk, e."strength" AS st
        FROM "GameEvents" e JOIN fg ON fg.gid = e."gameId"
        WHERE COALESCE(e."isVoid", false) = false AND e."eventType" IN ('Goal','Shot')
      )
      SELECT p.id, p."fullName" AS name, p."teamId" AS "teamId", p."jerseyNumber" AS num,
        COUNT(DISTINCT ev.gid) AS gp,
        COUNT(ev.t) FILTER (WHERE ev.t = 'Shot') AS saves,
        COUNT(ev.t) FILTER (WHERE ev.t = 'Goal' AND COALESCE(ev.st,'') <> 'Empty Net') AS ga,
        (SELECT COUNT(*) FROM fg WHERE fg.wg = p.id::text) AS w,
        (SELECT COUNT(*) FROM fg WHERE fg.lg = p.id::text AND fg.d = 'Regulation') AS l,
        (SELECT COUNT(*) FROM fg WHERE fg.lg = p.id::text AND fg.d <> 'Regulation') AS otl,
        (SELECT COUNT(*) FROM fg WHERE fg.wg = p.id::text AND ((fg.hg = p.id::text AND fg.vs = 0) OR (fg.ag = p.id::text AND fg.hs = 0))) AS so
      FROM "Players" p
      LEFT JOIN ev ON ev.gk = p.id::text
      WHERE p."position" = 'G' AND ($2 = '' OR p."teamId" = $2) AND ($3 = '' OR p.id::text = $3)
      GROUP BY p.id`,
    params: [seasonId, teamId, playerId],
  });
  return rows.map((r) => {
    const saves = n(r.saves), ga = n(r.ga), gp = n(r.gp), sa = saves + ga;
    return {
      id: String(r.id), name: String(r.name ?? ''), teamId: String(r.teamId ?? ''), num: n(r.num),
      gp, w: n(r.w), l: n(r.l), otl: n(r.otl), so: n(r.so), saves, ga, sa,
      svPct: sa ? +(saves / sa).toFixed(3) : 0,
      gaa: gp ? +(ga / gp).toFixed(2) : 0,
    };
  });
}

export async function standings(seasonId: string, s: Settings) {
  const [{ rows }, teams] = await Promise.all([
    zite.sql({
      query: `
        WITH fg AS (
          SELECT "homeTeamId" AS h, "awayTeamId" AS a, COALESCE("homeScore",0) AS hg, COALESCE("awayScore",0) AS ag,
            COALESCE("decision",'Regulation') AS d, COALESCE("shootoutHomeGoals",0) AS shg, COALESCE("shootoutAwayGoals",0) AS sag,
            "scheduledStart" AS ts
          FROM "Games" WHERE "status" = 'Final' AND "gameType" = 'Regular Season' AND ($1 = '' OR "seasonId" = $1)
        ),
        r AS (
          SELECT h AS tid, hg AS gf, ag AS ga, d, (CASE WHEN d = 'Shootout' THEN shg > sag ELSE hg > ag END) AS won, ts FROM fg
          UNION ALL
          SELECT a AS tid, ag AS gf, hg AS ga, d, (CASE WHEN d = 'Shootout' THEN sag > shg ELSE ag > hg END) AS won, ts FROM fg
        )
        SELECT tid, COUNT(*) AS gp,
          COUNT(*) FILTER (WHERE won AND d = 'Regulation') AS rw,
          COUNT(*) FILTER (WHERE won AND d = 'Overtime') AS otw,
          COUNT(*) FILTER (WHERE won AND d = 'Shootout') AS sow,
          COUNT(*) FILTER (WHERE NOT won AND d = 'Regulation') AS rl,
          COUNT(*) FILTER (WHERE NOT won AND d = 'Overtime') AS otl,
          COUNT(*) FILTER (WHERE NOT won AND d = 'Shootout') AS sol,
          SUM(gf) AS gf, SUM(ga) AS ga,
          string_agg(CASE WHEN won THEN 'W' WHEN d = 'Regulation' THEN 'L' ELSE 'OTL' END, ',' ORDER BY ts DESC) AS form
        FROM r GROUP BY tid`,
      params: [seasonId],
    }),
    zite.teams.findAll({ limit: 200 }),
  ]);
  const byTeam = new Map(rows.map((r) => [String(r.tid), r]));
  const P = s.points;
  const list = teams.records.map((t) => {
    const r = byTeam.get(t.id) ?? {};
    const rw = n(r.rw), otw = n(r.otw), sow = n(r.sow), rl = n(r.rl), otl = n(r.otl), sol = n(r.sol), gp = n(r.gp);
    const points = rw * P.win + otw * P.otWin + sow * P.soWin + rl * P.regLoss + otl * P.otLoss + sol * P.soLoss;
    const maxPts = gp * Math.max(P.win, P.otWin, P.soWin);
    const gf = n(r.gf), ga = n(r.ga);
    return {
      teamId: t.id, name: t.name ?? '', abbreviation: t.abbreviation ?? '', logoUrl: t.logoUrl ?? '',
      conference: t.conference ?? '', primaryColor: t.primaryColor ?? '',
      gp, wins: rw + otw + sow, regulationWins: rw, losses: rl, otLosses: otl + sol, points,
      pointsPct: maxPts ? +(points / maxPts).toFixed(3) : 0, goalsFor: gf, goalsAgainst: ga, goalDiff: gf - ga,
      form: String(r.form ?? '').split(',').filter(Boolean).slice(0, 5),
    };
  });
  type Row = (typeof list)[number];
  const keyVal = (row: Row, k: string) => (k === 'gamesPlayedFewer' ? -row.gp : Number((row as Record<string, unknown>)[k] ?? 0));
  list.sort((a, b) => {
    for (const k of s.tiebreakers) {
      const d = keyVal(b, k) - keyVal(a, k);
      if (d) return d;
    }
    return a.name.localeCompare(b.name);
  });
  return list;
}

import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import './index.css';
import App from "./App";
import { ErrorBoundary } from 'react-error-boundary';
import { HammerIcon } from 'lucide-react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

const queryClient = new QueryClient();

function reloadApp() {
  if (window._ziteOnReload) {
    window._ziteOnReload();
  } else {
    location.reload();
  }
}

function RuntimeErrorFallback(props: { error: Error }) {
  const allowAiFix = window.__ziteAllowAiFix === true;

  return (
    <div className="fixed inset-0 grid place-items-center">
      <div className="relative w-full max-w-xl rounded border-t-4 border-t-red-500 bg-white p-4 shadow-lg">
        <h3 className="mb-2 flex items-center gap-2 font-medium">
          Issue rendering app
        </h3>
        <p className="mb-4 text-sm text-gray-600">
          {allowAiFix
            ? 'Try asking Zite to fix the issue or find a workaround.'
            : 'Something went wrong while loading this app. You can try reloading the page.'}
        </p>

        <pre className="overflow-auto rounded border-l-4 border-red-500 bg-red-50 p-4 font-mono text-sm text-red-900">
          {props.error.message}
        </pre>
        <div className="mt-4 flex gap-2">
          {allowAiFix ? (
            <button
              type="button"
              className="flex items-center gap-2 rounded border border-red-100 bg-red-50 px-2.5 py-1.5 text-sm font-medium text-red-500 transition hover:bg-red-100"
              onClick={() => window._ziteOnFixError?.(props.error)}
            >
              <HammerIcon className="h-4 w-4" />
              Fix it for me
            </button>
          ) : null}
          <button
            type="button"
            onClick={reloadApp}
            className="flex items-center gap-2 rounded border border-gray-200 bg-gray-50 px-2.5 py-1.5 text-sm font-medium text-gray-500 transition hover:bg-gray-100"
          >
            Reload
          </button>
        </div>
      </div>
    </div>
  );
}

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <ErrorBoundary
      fallbackRender={props => <RuntimeErrorFallback error={props.error} />}
    >
      <QueryClientProvider client={queryClient}>
        <App />
      </QueryClientProvider>
    </ErrorBoundary>
  </StrictMode>,
);

import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { toast } from 'sonner';
import { BellRing, Trash2 } from 'lucide-react';
import { useAuth, loginWithRedirect } from 'zitejs/auth';
import { myFavorites, type MyFavoritesOutputType } from 'zitejs/api';
import { Button } from '@project/components/ui/button';
import { Checkbox } from '@project/components/ui/checkbox';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import TeamLogo from '../components/TeamLogo';
import { Empty, Loading, PageHeader, SectionTitle } from '../components/ui';
import { errMsg, useSite } from '../lib/site';

const ALERTS = ['Game Start', 'Goal', 'Penalty', 'Period End', 'Final Score'] as const;

export default function Account() {
  const { user, isLoading } = useAuth();
  const { site } = useSite();
  const [d, setD] = useState<MyFavoritesOutputType | null>(null);
  const [add, setAdd] = useState('');
  const [perm, setPerm] = useState(typeof Notification !== 'undefined' ? Notification.permission : 'unsupported');
  const run = async (p: Parameters<typeof myFavorites>[0], msg?: string) => { try { setD(await myFavorites(p)); if (msg) toast(msg); } catch (e) { toast.error(errMsg(e)); } };
  useEffect(() => { if (user) run({ action: 'list' }); }, [user]);
  if (isLoading) return <Loading />;
  if (!user) return <div><PageHeader title="Favorites & Alerts" /><div className="py-16 text-center"><p className="text-muted-foreground">Sign in to follow teams and players and get game alerts.</p><Button className="mt-4" onClick={() => loginWithRedirect()}>Sign in</Button></div></div>;
  if (!d) return <Loading />;
  const toggle = (id: string, cur: string[], a: string) => {
    const next = cur.includes(a) ? cur.filter((x) => x !== a) : [...cur, a];
    setD({ ...d, favorites: d.favorites.map((f) => (f.id === id ? { ...f, alerts: next } : f)) });
    run({ action: 'setAlerts', favoriteId: id, alerts: next as (typeof ALERTS)[number][] });
  };
  return (
    <div>
      <PageHeader eyebrow={user.email} title="Favorites & Alerts" />
      <div className="mx-auto max-w-4xl space-y-10 px-4 py-8">
        <section className="flex flex-wrap items-center gap-4 rounded-lg border bg-card p-4">
          <BellRing className="h-6 w-6 text-accent" />
          <div className="flex-1 text-sm"><b>Browser notifications</b><p className="text-muted-foreground">Alerts appear in the bell menu. Enable browser notifications to get pop-ups while this site is open.</p></div>
          {perm === 'granted' ? <span className="text-sm font-semibold text-emerald-700">Enabled</span> : perm === 'unsupported' ? <span className="text-sm text-muted-foreground">Not supported</span> :
            <Button variant="outline" onClick={() => Notification.requestPermission().then(setPerm)}>Enable</Button>}
        </section>
        <section>
          <SectionTitle action={
            <div className="flex gap-2">
              <Select value={add} onValueChange={setAdd}><SelectTrigger className="w-52"><SelectValue placeholder="Follow a team…" /></SelectTrigger><SelectContent>{site?.teams.filter((t) => !d.favorites.some((f) => f.teamId === t.id)).map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent></Select>
              <Button disabled={!add} onClick={() => { run({ action: 'follow', teamId: add }, 'Team followed'); setAdd(''); }}>Follow</Button>
            </div>
          }>Following</SectionTitle>
          {d.favorites.length === 0 ? <Empty>You’re not following anyone yet. Follow teams here, or tap “Follow” on any team or player page.</Empty> : (
            <div className="space-y-3">
              {d.favorites.map((f) => (
                <div key={f.id} className="rounded-lg border bg-card p-4">
                  <div className="flex items-center gap-3">
                    {f.teamId ? <TeamLogo teamId={f.teamId} size={34} /> : <span className="flex h-9 w-9 items-center justify-center rounded-full bg-muted text-xs font-bold">P</span>}
                    <Link to={f.teamId ? `/teams/${f.teamId}` : `/players/${f.playerId}`} className="flex-1 font-display text-lg font-bold uppercase hover:text-accent">{f.label}</Link>
                    <Button size="icon" variant="ghost" aria-label="Unfollow" onClick={() => run({ action: 'unfollow', favoriteId: f.id }, 'Unfollowed')}><Trash2 className="h-4 w-4" /></Button>
                  </div>
                  <div className="mt-3 flex flex-wrap gap-4">
                    {ALERTS.map((a) => <label key={a} className="flex items-center gap-2 text-sm"><Checkbox checked={f.alerts.includes(a)} onCheckedChange={() => toggle(f.id, f.alerts, a)} />{a}</label>)}
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
}

import { useParams, Link } from 'react-router-dom';
