function embed(url: string) {
  const yt = url.match(/(?:youtu\.be\/|v=)([\w-]{11})/);
  if (yt) return `https://www.youtube.com/embed/${yt[1]}`;
  const vm = url.match(/vimeo\.com\/(\d+)/);
  return vm ? `https://player.vimeo.com/video/${vm[1]}` : '';
}

export default function Article() {
  const { slug = '' } = useParams();
  const { data, error, reload } = useLoad(() => getNews({ slug }), [slug]);
  if (!data) return error ? <ErrorState message={error} onRetry={reload} /> : <Loading />;
  const a = data.article!;
  const share = async () => {
    try { if (navigator.share) await navigator.share({ title: a.title, url: location.href }); else { await navigator.clipboard.writeText(location.href); toast('Link copied'); } } catch { /* cancelled */ }
  };
  const video = a.videoUrl ? embed(a.videoUrl) : '';
  return (
    <article>
      <div className="relative bg-primary text-primary-foreground">
        {a.heroImageUrl && <img src={a.heroImageUrl} alt="" className="absolute inset-0 h-full w-full object-cover opacity-40" />}
        <div className="absolute inset-0 bg-gradient-to-t from-primary via-primary/60 to-transparent" />
        <div className="relative mx-auto max-w-4xl px-4 pb-10 pt-24">
          <Link to="/news" className="mb-4 inline-flex items-center text-sm text-primary-foreground/80 hover:text-primary-foreground"><ArrowLeft className="mr-1 h-4 w-4" />All news</Link>
          <Badge className="mb-3 block w-fit bg-accent text-accent-foreground hover:bg-accent">{a.category}</Badge>
          <h1 className="font-display text-4xl font-extrabold uppercase leading-[0.95] md:text-6xl">{a.title}</h1>
          <div className="mt-4 flex items-center gap-4 text-sm text-primary-foreground/80">
            <span>By {a.authorName} · {fmtDate(a.publishAt, { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' })}</span>
            <Button size="sm" variant="ghost" onClick={share} className="text-primary-foreground hover:bg-white/10 hover:text-primary-foreground"><Share2 className="mr-1 h-4 w-4" />Share</Button>
          </div>
        </div>
      </div>
      <div className="mx-auto max-w-3xl px-4 py-10">
        {a.excerpt && <p className="mb-6 text-xl font-medium leading-relaxed">{a.excerpt}</p>}
        {video ? <div className="mb-8 aspect-video overflow-hidden rounded-lg"><iframe src={video} title={a.title} className="h-full w-full" allowFullScreen /></div> : a.videoUrl ? <a href={a.videoUrl} target="_blank" rel="noreferrer" className="mb-6 block font-semibold text-accent">Watch video →</a> : null}
        <Markdown className="prose prose-lg max-w-none prose-headings:font-display prose-headings:uppercase">{a.body}</Markdown>
        <div className="mt-8 flex flex-wrap gap-3">
          {a.gameId && <Button asChild variant="outline"><Link to={`/games/${a.gameId}`}>Game Center</Link></Button>}
          {a.teamId && <Button asChild variant="outline"><Link to={`/teams/${a.teamId}`}>Team page</Link></Button>}
        </div>
        {data.author && (
          <div className="mt-10 flex gap-4 rounded-lg border bg-card p-5">
            <span className="flex h-14 w-14 shrink-0 items-center justify-center rounded-full bg-primary font-display text-xl font-bold text-primary-foreground">{data.author.name.split(' ').map((x) => x[0]).join('').slice(0, 2)}</span>
            <div><div className="font-display text-lg font-bold uppercase">{data.author.name}</div><div className="text-sm text-accent">{data.author.title}</div><p className="mt-1 text-sm text-muted-foreground">{data.author.bio}</p></div>
          </div>
        )}
      </div>
      {data.related.length > 0 && (
        <div className="mx-auto max-w-7xl px-4 pb-10">
          <h2 className="mb-4 font-display text-2xl font-extrabold uppercase">Related</h2>
          <div className="grid gap-5 sm:grid-cols-3">{data.related.map((r) => <ArticleCard key={r.id} a={r} />)}</div>
        </div>
      )}
    </article>
  );
}

