import { useState } from 'react';
import { useSearchParams } from 'react-router-dom';
import { z } from 'zod';
import { toast } from 'sonner';
import { CheckCircle2, Loader2 } from 'lucide-react';
import { getContent, submitContact } from 'zitejs/api';
import { Button } from '@project/components/ui/button';
import { Input } from '@project/components/ui/input';
import { Label } from '@project/components/ui/label';
import { Textarea } from '@project/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@project/components/ui/accordion';
import { PageHeader, SectionTitle, useLoad } from '../components/ui';
import { errMsg, useSite } from '../lib/site';

const TOPICS = ['General', 'Media', 'Tickets', 'Partnerships', 'Officiating', 'Player Inquiry'] as const;
const schema = z.object({
  name: z.string().trim().min(2, 'Enter your name'), email: z.string().trim().email('Enter a valid email'),
  topic: z.enum(TOPICS), subject: z.string().trim().min(3, 'Add a subject'), message: z.string().trim().min(10, 'Message must be at least 10 characters'),
});
type F = z.infer<typeof schema>;

export default function Contact() {
  const [params] = useSearchParams();
  const { site } = useSite();
  const init = TOPICS.includes(params.get('topic') as F['topic']) ? (params.get('topic') as F['topic']) : 'General';
  const [f, setF] = useState<F>({ name: '', email: '', topic: init, subject: '', message: '' });
  const [touched, setTouched] = useState<Record<string, boolean>>({});
  const [busy, setBusy] = useState(false);
  const [sent, setSent] = useState(false);
  const { data } = useLoad(() => getContent({ section: 'faqs' }), []);
  const parsed = schema.safeParse(f);
  const errs = parsed.success ? {} : Object.fromEntries(parsed.error.issues.map((i) => [i.path[0], i.message]));
  const field = (k: keyof F, label: string, el: React.ReactNode) => (
    <div><Label htmlFor={k}>{label}</Label>{el}{touched[k] && errs[k] && <p className="mt-1 text-xs text-destructive">{errs[k]}</p>}</div>
  );
  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!parsed.success) { setTouched({ name: true, email: true, subject: true, message: true }); return; }
    setBusy(true);
    try { await submitContact(parsed.data); setSent(true); } catch (err) { toast.error(errMsg(err)); } finally { setBusy(false); }
  };
  const on = (k: keyof F) => ({ id: k, value: f[k], onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => setF({ ...f, [k]: e.target.value }), onBlur: () => setTouched({ ...touched, [k]: true }) });
  return (
    <div>
      <PageHeader eyebrow="Get in touch" title="Contact & FAQ" />
      <div className="mx-auto grid max-w-7xl gap-10 px-4 py-8 lg:grid-cols-[1.2fr_1fr]">
        <section>
          <SectionTitle>Send a message</SectionTitle>
          {sent ? (
            <div className="rounded-lg border bg-card p-8 text-center"><CheckCircle2 className="mx-auto h-10 w-10 text-emerald-600" /><p className="mt-3 font-semibold">Thanks — your message was received.</p><p className="text-sm text-muted-foreground">League staff typically reply within two business days.</p><Button variant="outline" className="mt-4" onClick={() => { setSent(false); setF({ ...f, subject: '', message: '' }); setTouched({}); }}>Send another</Button></div>
          ) : (
            <form onSubmit={submit} className="space-y-4 rounded-lg border bg-card p-5" noValidate>
              <div className="grid gap-4 sm:grid-cols-2">{field('name', 'Name', <Input {...on('name')} />)}{field('email', 'Email', <Input type="email" {...on('email')} />)}</div>
