          <Accordion type="single" collapsible className="rounded-lg border bg-card px-4">
            {(data?.faqs ?? []).map((q) => <AccordionItem key={q.id} value={q.id}><AccordionTrigger className="text-left">{q.question}</AccordionTrigger><AccordionContent className="text-muted-foreground">{q.answer}</AccordionContent></AccordionItem>)}
          </Accordion>
        </section>
      </div>
    </div>
  );
}

import { useParams, Link } from 'react-router-dom';
import { MapPin, Radio, Zap } from 'lucide-react';
import { getGame, type GetGameOutputType } from 'zitejs/api';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@project/components/ui/tabs';
import { Badge } from '@project/components/ui/badge';
import TeamLogo from '../components/TeamLogo';
import { ErrorState, Loading, useLoad } from '../components/ui';
import { fmtClock, fmtCountdown, fmtDateTime, isLive, liveRemaining, periodLabel, statusLine, tz, useServerNow, useSite } from '../lib/site';
import { PlayByPlay, BoxScore, TeamStats, PlayerStats, Officials, Reviews } from '../components/GameTabs';

export type GameData = GetGameOutputType;

export default function GameCenter() {
  const { id = '' } = useParams();
  const { data, error, reload } = useLoad(() => getGame({ id }), [id], 4000);
  const now = useServerNow(data?.serverNow);
  if (!data) return error ? <ErrorState message={error} onRetry={reload} /> : <Loading rows={5} />;
  return (
    <div>
      <Scoreboard d={data} now={now} />
      <div className="mx-auto max-w-7xl px-4 py-8">
        {error && <div className="mb-4 rounded-md border border-accent/40 bg-accent/5 px-3 py-2 text-sm">Connection interrupted — showing the last update. Retrying automatically…</div>}
        <Tabs defaultValue="overview">
          <TabsList className="h-auto w-full flex-wrap justify-start">
            {['overview', 'play-by-play', 'box score', 'team stats', 'player stats', 'officials'].map((t) => <TabsTrigger key={t} value={t} className="capitalize">{t}</TabsTrigger>)}
          </TabsList>
          <TabsContent value="overview" className="mt-6"><Overview d={data} /></TabsContent>
          <TabsContent value="play-by-play" className="mt-6"><PlayByPlay d={data} /></TabsContent>
          <TabsContent value="box score" className="mt-6"><BoxScore d={data} /></TabsContent>
          <TabsContent value="team stats" className="mt-6"><TeamStats d={data} /></TabsContent>
          <TabsContent value="player stats" className="mt-6"><PlayerStats d={data} /></TabsContent>
          <TabsContent value="officials" className="mt-6"><Officials d={data} /></TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

function Scoreboard({ d, now }: { d: GameData; now: number }) {
  const { team } = useSite();
  const g = d.game;
  const live = isLive(g.status);
  const pm = d.periodMinutes * 60;
  const before = g.period <= 1 ? 0 : Math.min(g.period - 1, 3) * pm;
  const len = g.period >= 4 ? d.otMinutes * 60 : pm;
  const remaining = liveRemaining(g, now);
  const nowAbs = g.status === 'Intermission' ? before + len : before + (len - remaining);
  const pens = d.penalties.map((p) => ({ ...p, left: p.expiresAbs - nowAbs })).filter((p) => p.left > 0);
  const name = (pid: string) => d.players.find((p) => p.id === pid)?.name ?? '';
  const ppTeam = (() => {
    const h = pens.filter((p) => p.teamId === g.homeTeamId).length, a = pens.filter((p) => p.teamId === g.awayTeamId).length;
    return h > a ? g.awayTeamId : a > h ? g.homeTeamId : '';
  })();
  const pre = g.status === 'Scheduled' || g.status === 'Warmup';
  const ms = Date.parse(g.start) - now;
  const side = (tid: string, score: number, shots: number, so: number) => (
    <div className="flex flex-1 flex-col items-center gap-3 text-center">
      <TeamLogo teamId={tid} size={84} link />
      <Link to={`/teams/${tid}`} className="font-display text-xl font-bold uppercase leading-none hover:text-accent md:text-2xl">{team(tid)?.name}</Link>
      {ppTeam === tid && live && <Badge className="animate-pulse bg-accent text-accent-foreground hover:bg-accent"><Zap className="mr-1 h-3 w-3" />Power play</Badge>}
      {!pre && <div className="text-xs uppercase tracking-widest text-primary-foreground/60">SOG {shots}{g.period >= 5 || so ? ` · SO ${so}` : ''}</div>}
    </div>
  );
  return (
    <section className="relative overflow-hidden bg-primary text-primary-foreground">
      <div className="ice-lines absolute inset-0" />
      <div className="relative mx-auto max-w-5xl px-4 py-8">
        <div className="mb-6 flex flex-wrap items-center justify-center gap-2 text-xs uppercase tracking-widest text-primary-foreground/70">
          <span>{g.gameType}{g.playoffRound ? ` · ${g.playoffRound}` : ''} · {g.code}</span>
          <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{g.venue}{g.venueCity ? `, ${g.venueCity}` : ''}</span>
          <span>{fmtDateTime(g.start)} {tz()}</span>
        </div>
        <div className="flex items-center gap-4">
          {side(g.awayTeamId, g.awayScore, g.awayShots, g.shootoutAway)}
          <div className="flex min-w-[180px] flex-col items-center">
            {pre ? (
              <>
                <div className="text-xs font-bold uppercase tracking-[0.3em] text-accent">{g.status === 'Warmup' ? 'Warmup' : ms > 0 ? 'Puck drop in' : 'Starting'}</div>
                <div className="font-display text-5xl font-bold tabular md:text-6xl">{fmtCountdown(ms)}</div>
              </>
            ) : (
              <>
                <div className="font-display text-6xl font-extrabold tabular leading-none md:text-8xl">{g.awayScore}<span className="mx-2 text-primary-foreground/30 md:mx-4">–</span>{g.homeScore}</div>
                <div className={`mt-3 flex items-center gap-2 rounded px-3 py-1 font-display text-lg font-bold uppercase ${live ? 'bg-accent text-accent-foreground' : 'bg-white/10'}`}>
                  {live && <Radio className="h-4 w-4 animate-pulse" />}{statusLine(g, now)}
                </div>
              </>
            )}
            {['Postponed', 'Canceled', 'Suspended'].includes(g.status) && <div className="mt-2 rounded bg-accent px-3 py-1 text-sm font-bold uppercase">{g.status}</div>}
            {g.note && <div className="mt-2 max-w-xs text-center text-xs text-primary-foreground/70">{g.note}</div>}
            {g.originalStart && <div className="mt-1 text-xs text-primary-foreground/60">Rescheduled from {fmtDateTime(g.originalStart)}</div>}
          </div>
          {side(g.homeTeamId, g.homeScore, g.homeShots, g.shootoutHome)}
        </div>
        {pens.length > 0 && (
          <div className="mx-auto mt-6 grid max-w-3xl gap-2 sm:grid-cols-2">
            {pens.map((p) => (
              <div key={p.id} className="flex items-center gap-2 rounded bg-white/10 px-3 py-1.5 text-sm">
                <TeamLogo teamId={p.teamId} size={20} /><span className="flex-1 truncate">{name(p.playerId) || 'Bench'} · {p.infraction} ({p.minutes})</span>
                <span className="font-display text-lg font-bold tabular text-accent">{fmtClock(p.left)}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

function Overview({ d }: { d: GameData }) {
  const g = d.game;
  const { team } = useSite();
  const goals = d.events.filter((e) => e.type === 'Goal');
  const recent = [...d.events].reverse().slice(0, 8);
  return (
    <div className="grid gap-6 lg:grid-cols-[1.4fr_1fr]">
      <div className="space-y-6">
        <BoxScore d={d} compact />
        <Reviews d={d} />
        <div className="rounded-lg border bg-card p-4">
          <h3 className="mb-3 font-display text-lg font-bold uppercase">Scoring summary</h3>
          {goals.length === 0 && <p className="text-sm text-muted-foreground">{g.status === 'Scheduled' ? 'Game has not started.' : 'No goals yet.'}</p>}
          {goals.map((e) => (
            <div key={e.id} className="flex items-start gap-3 border-t py-2 first:border-0 text-sm">
              <span className="w-14 shrink-0 text-xs font-semibold text-muted-foreground">{periodLabel(e.period)} {fmtClock(e.elapsed)}</span>
              <TeamLogo teamId={e.teamId} size={22} />
              <span className="flex-1">{e.summary}</span>
              {e.isGameWinner && <Badge variant="outline">GWG</Badge>}
            </div>
          ))}
        </div>
      </div>
      <div className="space-y-6">
        <div className="rounded-lg border bg-card p-4">
          <h3 className="mb-3 font-display text-lg font-bold uppercase">Latest events</h3>
          {recent.length === 0 && <p className="text-sm text-muted-foreground">Play-by-play begins at puck drop.</p>}
          {recent.map((e) => <div key={e.id} className="border-t py-2 text-sm first:border-0"><span className="mr-2 text-xs font-semibold text-muted-foreground">{e.period ? `${periodLabel(e.period)} ${fmtClock(e.elapsed)}` : ''}</span>{e.summary}</div>)}
        </div>
        <TeamStats d={d} compact />
        {d.articles.length > 0 && (
          <div className="rounded-lg border bg-card p-4">
            <h3 className="mb-2 font-display text-lg font-bold uppercase">Coverage</h3>
            {d.articles.map((a) => <Link key={a.slug} to={`/news/${a.slug}`} className="block py-1 text-sm font-semibold hover:text-accent">{a.category}: {a.title}</Link>)}
          </div>
        )}
        <p className="text-xs text-muted-foreground">{team(g.awayTeamId)?.name} at {team(g.homeTeamId)?.name}. Scores and events are entered live by league game operations staff.</p>
      </div>
    </div>
  );
}

import { listGames } from 'zitejs/api';
import GameTile from '../components/GameTile';
import { Empty, ErrorState, Loading, PageHeader, SectionTitle, useLoad } from '../components/ui';
import { isLive, useServerNow } from '../lib/site';

export default function GameCenterIndex() {
  const { data, error, reload } = useLoad(() => listGames({ from: new Date(Date.now() - 30 * 3600000).toISOString(), to: new Date(Date.now() + 7 * 86400000).toISOString() }), [], 10000);
  const now = useServerNow(data?.serverNow);
  const games = data?.games ?? [];
  const live = games.filter((g) => isLive(g.status));
  const upcoming = games.filter((g) => g.status === 'Scheduled').slice(0, 8);
  const final = games.filter((g) => g.status === 'Final').reverse();
  return (
    <div>
      <PageHeader eyebrow="Live" title="Game Center">Live scoreboards, play-by-play, box scores and stats — updated automatically.</PageHeader>
      <div className="mx-auto max-w-7xl space-y-10 px-4 py-8">
        {!data ? (error ? <ErrorState message={error} onRetry={reload} /> : <Loading />) : (
          <>
            <section><SectionTitle>Live now</SectionTitle>{live.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{live.map((g) => <GameTile key={g.id} g={g} now={now} />)}</div> : <Empty>No games in progress right now.</Empty>}</section>
            <section><SectionTitle>Coming up</SectionTitle>{upcoming.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{upcoming.map((g) => <GameTile key={g.id} g={g} now={now} />)}</div> : <Empty>No games in the next week.</Empty>}</section>
            {final.length > 0 && <section><SectionTitle>Final</SectionTitle><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{final.map((g) => <GameTile key={g.id} g={g} now={now} />)}</div></section>}
          </>
        )}
      </div>
    </div>
  );
}

