import { useState } from 'react';
import { Play } from 'lucide-react';
import { getContent } from 'zitejs/api';
import { Button } from '@project/components/ui/button';
import { Dialog, DialogContent, DialogTitle } from '@project/components/ui/dialog';
import { Empty, ErrorState, Loading, PageHeader, useLoad } from '../components/ui';

const embed = (url: string) => { const yt = url.match(/(?:youtu\.be\/|v=)([\w-]{11})/); if (yt) return `https://www.youtube.com/embed/${yt[1]}`; const vm = url.match(/vimeo\.com\/(\d+)/); return vm ? `https://player.vimeo.com/video/${vm[1]}` : ''; };

export default function Media() {
  const { data, error, reload } = useLoad(() => getContent({ section: 'media' }), []);
  const [type, setType] = useState('All');
  const [open, setOpen] = useState<string | null>(null);
  const items = (data?.media ?? []).filter((m) => type === 'All' || m.type === type);
  const sel = data?.media.find((m) => m.id === open);
  return (
    <div>
      <PageHeader eyebrow="Media" title="Photos & Video" />
      <div className="mx-auto max-w-7xl px-4 py-8">
        <div className="mb-6 flex gap-2">{['All', 'Photo', 'Video'].map((t) => <Button key={t} size="sm" variant={type === t ? 'default' : 'outline'} onClick={() => setType(t)}>{t}</Button>)}</div>
        {!data ? (error ? <ErrorState message={error} onRetry={reload} /> : <Loading />) : items.length === 0 ? <Empty>{type === 'Video' ? 'No video highlights have been posted yet.' : 'No media yet.'}</Empty> : (
          <div className="columns-1 gap-4 sm:columns-2 lg:columns-3">
            {items.map((m) => (
              <button key={m.id} onClick={() => setOpen(m.id)} className="group relative mb-4 block w-full overflow-hidden rounded-lg text-left">
                <img src={m.thumbnailUrl || m.url} alt={m.title} className="w-full transition duration-500 group-hover:scale-105" loading="lazy" />
                {m.type === 'Video' && <span className="absolute inset-0 flex items-center justify-center"><Play className="h-14 w-14 rounded-full bg-accent p-3 text-white" /></span>}
                <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 p-3 text-white"><div className="font-display text-lg font-bold uppercase">{m.title}</div><div className="text-xs text-white/80">{m.caption}</div></div>
              </button>
            ))}
          </div>
        )}
      </div>
      <Dialog open={!!sel} onOpenChange={(o) => !o && setOpen(null)}>
        <DialogContent className="max-w-4xl p-2">
          <DialogTitle className="sr-only">{sel?.title}</DialogTitle>
          {sel && (sel.type === 'Video' && embed(sel.url) ? <div className="aspect-video"><iframe src={embed(sel.url)} title={sel.title} className="h-full w-full" allowFullScreen /></div> : <img src={sel.url} alt={sel.title} className="w-full rounded" />)}
          {sel && <p className="px-2 pb-2 text-sm text-muted-foreground"><b className="text-foreground">{sel.title}</b> — {sel.caption}</p>}
        </DialogContent>
      </Dialog>
    </div>
  );
}

