export default function MyTickets() {
  const [params, setParams] = useSearchParams();
  const code = params.get('code') ?? '', email = params.get('email') ?? '';
  const { user, isLoading } = useAuth();
  const [form, setForm] = useState({ code, email });
  const { data } = useLoad(() => (code && email) || user ? getOrder(code && email ? { orderCode: code, email } : {}) : Promise.resolve({ orders: [] }), [code, email, user?.id]);
  const [busy] = useState(false);
  const lookup = () => { if (!form.code.trim() || !form.email.trim()) return toast.error('Enter your order code and email'); setParams({ code: form.code.trim().toUpperCase(), email: form.email.trim() }); };
  const justBought = !!code && !!data?.orders.length;
  return (
    <div>
      <PageHeader eyebrow="Box office" title="My Tickets" />
      <div className="mx-auto max-w-3xl space-y-6 px-4 py-8">
        {justBought && <div className="flex items-center gap-3 rounded-lg border border-emerald-300 bg-emerald-50 p-4 text-sm text-emerald-900"><CheckCircle2 className="h-5 w-5" /><span>You're all set! Show your order code at the door. Keep this page or write down <b className="font-mono">{code}</b>.</span></div>}
        <div className="flex flex-wrap items-end gap-2 rounded-lg border bg-card p-4">
          <div className="min-w-[140px] flex-1"><label className="text-xs font-semibold text-muted-foreground">Order code</label><Input value={form.code} onChange={(e) => setForm({ ...form, code: e.target.value })} placeholder="NF-XXXXXXX" /></div>
          <div className="min-w-[180px] flex-1"><label className="text-xs font-semibold text-muted-foreground">Email</label><Input value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} placeholder="you@example.com" /></div>
          <Button onClick={lookup} disabled={busy}>{busy && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Find order</Button>
          {data?.orders.length ? <Button variant="outline" onClick={() => window.print()}><Printer className="mr-2 h-4 w-4" />Print</Button> : null}
        </div>
        {!user && !isLoading && !code && <p className="text-sm text-muted-foreground"><button className="font-semibold text-accent underline" onClick={() => loginWithRedirect()}>Sign in</button> to see every order bought with your email.</p>}
        {!data ? <Loading rows={2} /> : data.orders.length === 0 ? <Empty>{code ? 'No order found with that code and email.' : 'No tickets yet.'} <Link to="/tickets" className="font-semibold text-accent">Buy tickets →</Link></Empty>
          : data.orders.map((o) => <OrderCard key={o.orderCode} o={o} highlight={o.orderCode === code} />)}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useDebounce } from 'use-debounce';
import { getNews } from 'zitejs/api';
import { Input } from '@project/components/ui/input';
import { Button } from '@project/components/ui/button';
import ArticleCard from '../components/ArticleCard';
import { Empty, ErrorState, Loading, PageHeader, useLoad } from '../components/ui';

const CATS = ['All', 'Recap', 'Preview', 'Announcement', 'Press Release', 'Spotlight', 'Interview', 'Transaction', 'Awards', 'Feature', 'Video'];

export default function News() {
  const [cat, setCat] = useState('All');
  const [q, setQ] = useState('');
  const [dq] = useDebounce(q, 350);
  const [page, setPage] = useState(0);
  const { data, error, reload } = useLoad(() => getNews({ category: cat === 'All' ? undefined : cat, search: dq || undefined, page }), [cat, dq, page]);
  const pages = Math.max(1, Math.ceil((data?.total ?? 0) / 12));
  return (
    <div>
      <PageHeader eyebrow="Newsroom" title="League News">Game recaps, previews, announcements, interviews and player spotlights.</PageHeader>
      <div className="mx-auto max-w-7xl px-4 py-8">
        <div className="mb-6 flex flex-wrap items-center gap-2">
          {CATS.map((c) => <Button key={c} size="sm" variant={cat === c ? 'default' : 'outline'} onClick={() => { setCat(c); setPage(0); }}>{c}</Button>)}
          <Input value={q} onChange={(e) => { setQ(e.target.value); setPage(0); }} placeholder="Search news…" className="ml-auto w-56" />
        </div>
        {!data ? (error ? <ErrorState message={error} onRetry={reload} /> : <Loading />) : data.articles.length === 0 ? <Empty>No articles found.</Empty> : (
          <>
            <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{data.articles.map((a) => <ArticleCard key={a.id} a={a} />)}</div>
            {pages > 1 && (
              <div className="mt-8 flex items-center justify-center gap-3">
                <Button variant="outline" disabled={page === 0} onClick={() => setPage((p) => p - 1)}>Newer</Button>
                <span className="text-sm text-muted-foreground">Page {page + 1} of {pages}</span>
                <Button variant="outline" disabled={page >= pages - 1} onClick={() => setPage((p) => p + 1)}>Older</Button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}

