import { useEffect, useState } from 'react';
import { useAuth, loginWithRedirect } from 'zitejs/auth';
import { officialsPortal, type OfficialsPortalOutputType, type OfficialsPortalInputType } from 'zitejs/api';
import { toast } from 'sonner';
import { Check, Loader2, X, ShieldCheck } from 'lucide-react';
import { Button } from '@project/components/ui/button';
import { Badge } from '@project/components/ui/badge';
import { Input } from '@project/components/ui/input';
import { Textarea } from '@project/components/ui/textarea';
import { Label } from '@project/components/ui/label';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@project/components/ui/tabs';
import { DatePicker } from '@project/components/ui/date-picker';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle } from '@project/components/ui/dialog';
import { format } from 'date-fns';
import TeamLogo from '../components/TeamLogo';
import ResourceDoc from '../components/ResourceDoc';
import { Empty, Loading, PageHeader } from '../components/ui';
import { errMsg, fmtDateTime, useSite } from '../lib/site';

type D = OfficialsPortalOutputType;
type A = D['upcoming'][number];

export default function OfficialsPortal() {
  const { user, isLoading } = useAuth();
  const [d, setD] = useState<D | null>(null);
  const [busy, setBusy] = useState(false);
  const call = async (input: OfficialsPortalInputType, ok?: string) => {
    setBusy(true);
    try { setD(await officialsPortal(input)); if (ok) toast.success(ok); return true; } catch (e) { toast.error(errMsg(e)); return false; } finally { setBusy(false); }
  };
  useEffect(() => { if (user) call({ action: 'load' }); }, [user]);
  if (isLoading) return <Loading />;
  if (!user) return (
    <div><PageHeader eyebrow="Officials" title="Officials Portal" />
      <div className="mx-auto max-w-md px-4 py-16 text-center">
        <ShieldCheck className="mx-auto h-12 w-12 text-accent" />
        <p className="mt-4 text-muted-foreground">Sign in with the email address the league has on file for you to view assignments, confirm games and manage availability.</p>
        <Button className="mt-6" onClick={() => loginWithRedirect()}>Sign in to the portal</Button>
      </div>
    </div>
  );
  if (!d) return <Loading />;
  if (!d.official) return (
    <div><PageHeader eyebrow="Officials" title="Officials Portal" />
      <div className="mx-auto max-w-md px-4 py-16 text-center text-muted-foreground">
        <p><b className="text-foreground">{user.email}</b> isn’t linked to an official profile.</p>
        <p className="mt-2">Contact the officiating department and ask them to add this email to your official record.</p>
      </div>
    </div>
  );
  const o = d.official;
  return (
    <div>
      <PageHeader eyebrow={`${o.type} · ${o.level}`} title={`Welcome, ${o.name.split(' ')[0]}`}>{d.upcoming.filter((a) => a.status === 'Pending').length} assignment(s) awaiting your response.</PageHeader>
      <div className="mx-auto max-w-6xl px-4 py-8">
        <Tabs defaultValue="assignments">
          <TabsList className="h-auto flex-wrap"><TabsTrigger value="assignments">Assignments</TabsTrigger><TabsTrigger value="availability">Availability</TabsTrigger><TabsTrigger value="history">History</TabsTrigger><TabsTrigger value="feedback">Feedback</TabsTrigger><TabsTrigger value="resources">Resources</TabsTrigger><TabsTrigger value="profile">Profile</TabsTrigger></TabsList>
          <TabsContent value="assignments" className="mt-6 space-y-3">{d.upcoming.length ? d.upcoming.map((a) => <AsgCard key={a.id} a={a} busy={busy} onRespond={(accept, note) => call({ action: 'respond', assignmentId: a.id, accept, note }, accept ? 'Assignment accepted' : 'Assignment declined')} />) : <Empty>No upcoming assignments.</Empty>}</TabsContent>
          <TabsContent value="availability" className="mt-6"><Availability d={d} busy={busy} onSave={(date, status, note) => call({ action: 'availability', date, status, note }, 'Availability updated')} /></TabsContent>
          <TabsContent value="history" className="mt-6 space-y-3">{d.history.length ? d.history.map((a) => <AsgCard key={a.id} a={a} busy past />) : <Empty>No past assignments.</Empty>}</TabsContent>
          <TabsContent value="feedback" className="mt-6 space-y-3">
            {d.evaluations.length ? d.evaluations.map((e) => (
              <div key={e.id} className="rounded-lg border bg-card p-4"><div className="flex items-center justify-between"><div className="font-semibold">{e.title}</div><Badge>{e.score}/5</Badge></div><div className="text-xs text-muted-foreground">{e.gameCode}</div><p className="mt-2 text-sm">{e.feedback}</p></div>
            )) : <Empty>No approved feedback yet.</Empty>}
          </TabsContent>
          <TabsContent value="resources" className="mt-6 grid gap-3 md:grid-cols-2">
            {d.resources.map((r) => <ResourceDoc key={r.id} r={r} />)}
          </TabsContent>
          <TabsContent value="profile" className="mt-6"><Profile o={o} busy={busy} onSave={(v) => call({ action: 'profile', ...v }, 'Profile saved')} /></TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

function AsgCard({ a, busy, past, onRespond }: { a: A; busy: boolean; past?: boolean; onRespond?: (accept: boolean, note?: string) => Promise<boolean> }) {
  const { team } = useSite();
  const [decline, setDecline] = useState(false);
  const [note, setNote] = useState('');
  return (
    <div className="rounded-lg border bg-card p-4">
      <div className="flex flex-wrap items-center gap-4">
        <div className="flex items-center gap-2"><TeamLogo teamId={a.awayTeamId} size={30} /><span className="text-xs text-muted-foreground">@</span><TeamLogo teamId={a.homeTeamId} size={30} /></div>
        <div className="min-w-0 flex-1">
          <div className="font-display text-lg font-bold uppercase">{team(a.awayTeamId)?.abbreviation} at {team(a.homeTeamId)?.abbreviation} · {a.position}</div>
          <div className="text-sm text-muted-foreground">{fmtDateTime(a.start)} · {a.venue} · {a.code}</div>
        </div>
        <Badge variant={a.status === 'Accepted' ? 'default' : a.status === 'Declined' ? 'destructive' : 'outline'}>{a.status}</Badge>
        {!past && onRespond && a.status === 'Pending' && (
          <div className="flex gap-2">
            <Button size="sm" disabled={busy} onClick={() => onRespond(true)}><Check className="mr-1 h-4 w-4" />Accept</Button>
            <Button size="sm" variant="outline" disabled={busy} onClick={() => setDecline(true)}><X className="mr-1 h-4 w-4" />Decline</Button>
          </div>
        )}
        {!past && onRespond && a.status === 'Accepted' && <Button size="sm" variant="ghost" disabled={busy} onClick={() => setDecline(true)}>Can’t make it</Button>}
      </div>
      {a.crew.length > 0 && <div className="mt-3 flex flex-wrap gap-2 border-t pt-3 text-xs">{a.crew.map((c, i) => <span key={i} className="rounded bg-muted px-2 py-1">{c.position}: <b>{c.name}</b>{c.status === 'Pending' ? ' (pending)' : ''}</span>)}</div>}
      <Dialog open={decline} onOpenChange={setDecline}>
        <DialogContent>
          <DialogHeader><DialogTitle>Decline assignment</DialogTitle></DialogHeader>
          <Label>Reason (required)</Label>
          <Textarea value={note} onChange={(e) => setNote(e.target.value)} placeholder="e.g. Work conflict" />
          <DialogFooter><Button variant="outline" onClick={() => setDecline(false)}>Cancel</Button><Button disabled={!note.trim() || busy} onClick={async () => { if (await onRespond!(false, note)) setDecline(false); }}>{busy && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Decline</Button></DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

function Availability({ d, busy, onSave }: { d: D; busy: boolean; onSave: (date: string, status: 'Available' | 'Limited' | 'Unavailable' | 'Clear', note: string) => void }) {
  const [date, setDate] = useState<Date | undefined>();
  const [status, setStatus] = useState<'Available' | 'Limited' | 'Unavailable' | 'Clear'>('Unavailable');
  const [note, setNote] = useState('');
  const upcoming = d.availability.filter((a) => a.date >= format(new Date(), 'yyyy-MM-dd'));
  return (
    <div className="grid gap-6 md:grid-cols-[1fr_1.2fr]">
      <div className="space-y-3 rounded-lg border bg-card p-4">
        <h3 className="font-display text-lg font-bold uppercase">Set a date</h3>
        <DatePicker value={date} onChange={setDate} />
        <Select value={status} onValueChange={(v) => setStatus(v as typeof status)}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{['Available', 'Limited', 'Unavailable', 'Clear'].map((s) => <SelectItem key={s} value={s}>{s === 'Clear' ? 'Clear entry' : s}</SelectItem>)}</SelectContent></Select>
        <Input value={note} onChange={(e) => setNote(e.target.value)} placeholder="Note (optional)" />
        <Button disabled={!date || busy} onClick={() => date && onSave(format(date, 'yyyy-MM-dd'), status, note)}>Save</Button>
      </div>
      <div className="space-y-2">
        <h3 className="font-display text-lg font-bold uppercase">Upcoming entries</h3>
        {upcoming.length ? upcoming.map((a) => (
          <div key={a.id} className="flex items-center gap-3 rounded border bg-card px-3 py-2 text-sm"><span className="w-28 font-semibold">{format(new Date(`${a.date}T12:00:00`), 'EEE, MMM d')}</span><Badge variant={a.status === 'Unavailable' ? 'destructive' : 'outline'}>{a.status}</Badge><span className="flex-1 truncate text-muted-foreground">{a.note}</span><Button size="sm" variant="ghost" disabled={busy} onClick={() => onSave(a.date, 'Clear', '')}>Clear</Button></div>
        )) : <Empty>You’re listed as available for all dates.</Empty>}
      </div>
    </div>
  );
}

function Profile({ o, busy, onSave }: { o: NonNullable<D['official']>; busy: boolean; onSave: (v: { phone: string; hometown: string; bio: string }) => void }) {
  const [v, setV] = useState({ phone: o.phone, hometown: o.hometown, bio: o.bio });
  return (
    <div className="max-w-xl space-y-4 rounded-lg border bg-card p-5">
      <div><Label>Email</Label><Input value={o.email} disabled /><p className="mt-1 text-xs text-muted-foreground">Private — only visible to league officiating staff.</p></div>
