      <div><Label>Hometown</Label><Input value={v.hometown} onChange={(e) => setV({ ...v, hometown: e.target.value })} /></div>
      <div><Label>Public bio</Label><Textarea rows={4} value={v.bio} onChange={(e) => setV({ ...v, bio: e.target.value })} /></div>
