  const cur = data.seasons[0]?.stats as unknown as Record<string, number> | undefined;
  const big: [string, string | number][] = isG
    ? [['GP', cur?.gp ?? 0], ['W', cur?.w ?? 0], ['SV%', pct(cur?.svPct ?? 0)], ['GAA', Number(cur?.gaa ?? 0).toFixed(2)]]
    : [['GP', cur?.gp ?? 0], ['G', cur?.g ?? 0], ['A', cur?.a ?? 0], ['PTS', cur?.pts ?? 0]];
