            <div className="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-sm text-white/80">
              <span>#{p.num} · {p.pos}</span>{p.shoots && <span>{isG ? 'Catches' : 'Shoots'} {p.shoots}</span>}{p.height && <span>{p.height}{p.weight ? ` · ${p.weight} lb` : ''}</span>}
