          <SectionTitle>Season by season</SectionTitle>
          <SortTable rowKey={(r) => r.seasonId} rows={[...data.seasons.map((s) => ({ seasonId: s.seasonId, season: s.seasonName, ...(s.stats as object) })), ...(data.career ? [{ seasonId: 'career', season: 'Career', ...data.career }] : [])] as Record<string, any>[]}
            cols={isG ? [{ key: 'season', label: 'Season', left: true }, { key: 'gp', label: 'GP' }, { key: 'w', label: 'W' }, { key: 'l', label: 'L' }, { key: 'otl', label: 'OTL' }, { key: 'sa', label: 'SA' }, { key: 'saves', label: 'SV' }, { key: 'svPct', label: 'SV%', render: (r) => pct(r.svPct) }, { key: 'gaa', label: 'GAA', render: (r) => Number(r.gaa ?? 0).toFixed(2) }, { key: 'so', label: 'SO' }]
