import { useMemo, useState } from 'react';
import { ChevronLeft, ChevronRight } from 'lucide-react';
import { addDays, addMonths, addWeeks, endOfMonth, endOfWeek, format, startOfDay, startOfMonth, startOfWeek } from 'date-fns';
import { listGames } from 'zitejs/api';
import { Button } from '@project/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Tabs, TabsList, TabsTrigger } from '@project/components/ui/tabs';
import GameTile from '../components/GameTile';
import { Empty, ErrorState, Loading, PageHeader, useLoad } from '../components/ui';
import { tz, useServerNow, useSite } from '../lib/site';

type View = 'day' | 'week' | 'month' | 'season';

export default function Schedule({ mode = 'schedule' }: { mode?: 'schedule' | 'scores' }) {
  const { site } = useSite();
  const [view, setView] = useState<View>(mode === 'scores' ? 'day' : 'week');
  const [anchor, setAnchor] = useState(() => startOfDay(new Date()));
  const [teamId, setTeamId] = useState('all');
  const [venueId, setVenueId] = useState('all');
  const [status, setStatus] = useState(mode === 'scores' ? 'all' : 'all');
  const [from, to] = useMemo(() => {
    if (view === 'day') return [anchor, addDays(anchor, 1)];
    if (view === 'week') return [startOfWeek(anchor), addDays(endOfWeek(anchor), 1)];
    if (view === 'month') return [startOfMonth(anchor), addDays(endOfMonth(anchor), 1)];
    return [null, null];
  }, [view, anchor]);
  const { data, error, reload } = useLoad(() => listGames({
    from: from?.toISOString(), to: to?.toISOString(), teamId: teamId === 'all' ? undefined : teamId, venueId: venueId === 'all' ? undefined : venueId,
    status: status === 'all' ? undefined : status, seasonId: view === 'season' ? site?.settings.currentSeasonId : undefined,
  }), [from?.getTime(), teamId, venueId, status, view, site?.settings.currentSeasonId], 15000);
  const now = useServerNow(data?.serverNow);
  const step = (d: number) => setAnchor((a) => (view === 'day' ? addDays(a, d) : view === 'week' ? addWeeks(a, d) : addMonths(a, d)));
  const groups = useMemo(() => {
    const m = new Map<string, NonNullable<typeof data>['games']>();
    (data?.games ?? []).forEach((g) => { const k = format(new Date(g.start), 'yyyy-MM-dd'); m.set(k, [...(m.get(k) ?? []), g]); });
    return [...m.entries()];
  }, [data]);
  const label = view === 'day' ? format(anchor, 'EEEE, MMMM d, yyyy') : view === 'week' ? `${format(from!, 'MMM d')} – ${format(addDays(to!, -1), 'MMM d, yyyy')}` : view === 'month' ? format(anchor, 'MMMM yyyy') : 'Full season';
  return (
    <div>
      <PageHeader eyebrow={mode === 'scores' ? 'Results & live' : site?.seasons.find((s) => s.id === site.settings.currentSeasonId)?.name ?? 'Season'} title={mode === 'scores' ? 'Scores' : 'Schedule'}>
        All times shown in your local time ({tz()}).
      </PageHeader>
      <div className="sticky top-[64px] z-30 border-b bg-background/95 backdrop-blur">
        <div className="mx-auto flex max-w-7xl flex-wrap items-center gap-3 px-4 py-3">
          <Tabs value={view} onValueChange={(v) => setView(v as View)}><TabsList>{(['day', 'week', 'month', 'season'] as View[]).map((v) => <TabsTrigger key={v} value={v} className="capitalize">{v}</TabsTrigger>)}</TabsList></Tabs>
          {view !== 'season' && (
            <div className="flex items-center gap-1">
              <Button size="icon" variant="outline" onClick={() => step(-1)} aria-label="Previous"><ChevronLeft className="h-4 w-4" /></Button>
              <Button variant="outline" onClick={() => setAnchor(startOfDay(new Date()))}>Today</Button>
              <Button size="icon" variant="outline" onClick={() => step(1)} aria-label="Next"><ChevronRight className="h-4 w-4" /></Button>
              <span className="ml-2 font-display text-lg font-bold uppercase">{label}</span>
            </div>
          )}
          <div className="ml-auto flex flex-wrap gap-2">
            <Select value={teamId} onValueChange={setTeamId}><SelectTrigger className="w-44"><SelectValue placeholder="Team" /></SelectTrigger><SelectContent><SelectItem value="all">All teams</SelectItem>{site?.teams.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent></Select>
            <Select value={venueId} onValueChange={setVenueId}><SelectTrigger className="w-44"><SelectValue placeholder="Venue" /></SelectTrigger><SelectContent><SelectItem value="all">All venues</SelectItem>{site?.venues.map((v) => <SelectItem key={v.id} value={v.id}>{v.name}</SelectItem>)}</SelectContent></Select>
            <Select value={status} onValueChange={setStatus}><SelectTrigger className="w-36"><SelectValue /></SelectTrigger><SelectContent>{['all', 'Scheduled', 'Live', 'Final', 'Postponed', 'Canceled'].map((s) => <SelectItem key={s} value={s}>{s === 'all' ? 'Any status' : s}</SelectItem>)}</SelectContent></Select>
          </div>
        </div>
      </div>
      <div className="mx-auto max-w-7xl px-4 py-8">
        {!data ? (error ? <ErrorState message={error} onRetry={reload} /> : <Loading />) : groups.length === 0 ? <Empty>No games match these filters for {label.toLowerCase()}.</Empty> : (
          <div className="space-y-8">
            {groups.map(([day, games]) => (
              <section key={day}>
                <h2 className="mb-3 font-display text-xl font-extrabold uppercase">{format(new Date(`${day}T12:00:00`), 'EEEE, MMMM d')}</h2>
                <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{games.map((g) => <GameTile key={g.id} g={g} now={now} />)}</div>
              </section>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

