  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [busy, setBusy] = useState(false);
  useEffect(() => { if (user) { setName((n) => n || user.name || ''); setEmail((e) => e || user.email); } }, [user]);

  const sold = useMemo(() => new Set(data?.sold ?? []), [data?.sold]);
  // Drop seats from the cart if someone else bought them meanwhile.
  useEffect(() => {
    setSelected((s) => { const lost = [...s].filter((id) => sold.has(id)); if (!lost.length) return s; toast.error('A seat in your selection was just sold.'); return new Set([...s].filter((id) => !sold.has(id))); });
  }, [sold]);

  const toggle = useCallback((id: string) => setSelected((s) => {
    const n = new Set(s);
    if (n.has(id)) n.delete(id); else if (n.size >= MAX) { toast.error(`You can buy up to ${MAX} seats per order.`); return s; } else n.add(id);
    return n;
  }), []);

  if (!data) return error ? <ErrorState message={error} onRetry={reload} /> : <Loading rows={5} />;
  const seats = [...selected].map((id) => parseSeat(id, data.layout)!).filter(Boolean);
  const total = seats.reduce((s, x) => s + x.price, 0);
  const capacity = totalSeats(data.layout);
  const emailOk = /^\S+@\S+\.\S+$/.test(email.trim());
  const g = data.game;

  const checkout = async () => {
    setBusy(true);
    try {
      const r = await buyTickets({ gameId, seatIds: [...selected], name, email });
      toast.success('Tickets booked!');
      nav(`/tickets/orders?code=${r.orderCode}&email=${encodeURIComponent(email.trim())}`);
    } catch (e) { toast.error(e instanceof Error ? e.message : 'Checkout failed'); reload(); }
    finally { setBusy(false); }
  };

  return (
    <div className="mx-auto max-w-7xl px-4 py-8">
      <Link to="/tickets" className="mb-4 inline-flex items-center gap-1 text-sm font-semibold text-muted-foreground hover:text-foreground"><ArrowLeft className="h-4 w-4" />All games</Link>
      <div className="mb-6 flex flex-wrap items-center gap-4">
        <TeamLogo teamId={g.awayTeamId} size={44} /><span className="font-display text-3xl font-extrabold uppercase">{team(g.awayTeamId)?.name}</span>
        <span className="text-muted-foreground">@</span>
        <TeamLogo teamId={g.homeTeamId} size={44} /><span className="font-display text-3xl font-extrabold uppercase">{team(g.homeTeamId)?.name}</span>
        <span className="w-full text-sm text-muted-foreground">{new Date(g.start).toLocaleString(undefined, { weekday: 'long', month: 'long', day: 'numeric', hour: 'numeric', minute: '2-digit' })} · {g.venue} · {capacity - sold.size} of {capacity} seats available</span>
      </div>
      {!data.onSale && <div className="mb-4 rounded-lg border border-accent/40 bg-accent/5 p-3 text-sm font-semibold text-accent">Tickets are no longer on sale for this game ({g.status}).</div>}
      <div className="grid gap-6 lg:grid-cols-[1fr_320px]">
        <div className="min-w-0 space-y-3">
          <Legend />
          <SeatMap layout={data.layout} sold={sold} selected={selected} onToggle={toggle} disabled={!data.onSale} />
          <p className="text-xs text-muted-foreground">Tap a seat to add it, tap again to remove it. The map refreshes automatically as seats sell.</p>
        </div>
        <aside className="h-fit space-y-4 rounded-xl border bg-card p-5 shadow-sm lg:sticky lg:top-24">
          <h2 className="flex items-center gap-2 font-display text-xl font-extrabold uppercase"><Ticket className="h-5 w-5 text-accent" />Your seats</h2>
          {seats.length === 0 ? <p className="text-sm text-muted-foreground">No seats selected yet.</p> : (
            <ul className="max-h-56 space-y-1.5 overflow-y-auto">
              {seats.map((s) => (
                <li key={s.id} className="flex items-center justify-between gap-2 rounded-md bg-muted/50 px-2.5 py-1.5 text-sm">
                  <span><span className="font-semibold">{s.section}</span><br /><span className="text-xs text-muted-foreground">Row {s.row} · Seat {s.n}</span></span>
                  <span className="flex items-center gap-1 font-semibold">${s.price}<button onClick={() => toggle(s.id)} aria-label="Remove" className="rounded p-0.5 text-muted-foreground hover:text-foreground"><X className="h-3.5 w-3.5" /></button></span>
                </li>
              ))}
            </ul>
          )}
          <div className="flex justify-between border-t pt-3 font-display text-xl font-bold uppercase"><span>Total</span><span>${total.toFixed(2)}</span></div>
          <div className="space-y-2">
            <div><Label className="text-xs">Name</Label><Input value={name} onChange={(e) => setName(e.target.value)} placeholder="Full name" /></div>
            <div><Label className="text-xs">Email</Label><Input type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="you@example.com" />{email && !emailOk && <p className="mt-1 text-xs text-destructive">Enter a valid email</p>}</div>
          </div>
          <Button className="w-full bg-accent text-accent-foreground hover:bg-accent/90" size="lg" disabled={busy || !seats.length || !name.trim() || !emailOk || !data.onSale} onClick={checkout}>
            {busy && <Loader2 className="mr-2 h-4 w-4 animate-spin" />}Complete purchase
          </Button>
          <p className="text-center text-[11px] text-muted-foreground">Demo checkout — seats are reserved, no payment is taken.</p>
        </aside>
      </div>
    </div>
  );
}

