type Row = Record<string, any>;
const LABEL: Record<string, string> = { points: 'Points', pointsPct: 'Points %', regulationWins: 'Regulation wins', wins: 'Total wins', goalDiff: 'Goal differential', goalsFor: 'Goals for', fewerGames: 'Fewer games played' };

export function useStandingCols(): Col<Row>[] {
  return [
    { key: 'rank', label: '#', render: (_r, i) => i + 1, sortValue: (r) => r.points },
    { key: 'name', label: 'Team', left: true, render: (r) => <Link to={`/teams/${r.teamId}`} className="flex items-center gap-2 font-semibold hover:text-accent"><TeamLogo teamId={r.teamId} size={24} /><span className="hidden sm:inline">{r.name}</span><span className="sm:hidden">{r.abbreviation}</span></Link> },
    { key: 'gp', label: 'GP', title: 'Games played' }, { key: 'wins', label: 'W' }, { key: 'losses', label: 'L' }, { key: 'otLosses', label: 'OTL', title: 'Overtime/shootout losses' },
    { key: 'points', label: 'PTS', render: (r) => <span className="font-bold">{r.points}</span> },
    { key: 'pointsPct', label: 'P%', render: (r) => Number(r.pointsPct).toFixed(3).replace(/^0/, '') },
    { key: 'regulationWins', label: 'RW', title: 'Regulation wins' }, { key: 'goalsFor', label: 'GF' }, { key: 'goalsAgainst', label: 'GA' },
    { key: 'goalDiff', label: 'DIFF', render: (r) => <span className={r.goalDiff > 0 ? 'text-emerald-700' : r.goalDiff < 0 ? 'text-accent' : ''}>{r.goalDiff > 0 ? '+' : ''}{r.goalDiff}</span> },
    { key: 'form', label: 'Last 5', render: (r) => <Form form={(r.form ?? []).slice(0, 5)} />, sortValue: (r) => (r.form ?? []).slice(0, 5).filter((f: string) => f === 'W').length },
  ];
}

export default function Standings() {
  const { site } = useSite();
  const [seasonId, setSeasonId] = useState('');
  const [view, setView] = useState('conference');
  const { data, error, reload } = useLoad(() => getStandings({ seasonId: seasonId || undefined }), [seasonId], 30000);
  const cols = useStandingCols();
  return (
    <div>
      <PageHeader eyebrow="Race to the Frontier Cup" title="Standings" />
      <div className="mx-auto max-w-7xl px-4 py-8">
        <div className="mb-6 flex flex-wrap items-center gap-3">
          <Tabs value={view} onValueChange={setView}><TabsList><TabsTrigger value="conference">Conference</TabsTrigger><TabsTrigger value="league">League</TabsTrigger></TabsList></Tabs>
          <Select value={seasonId || data?.seasonId || ''} onValueChange={setSeasonId}><SelectTrigger className="ml-auto w-44"><SelectValue placeholder="Season" /></SelectTrigger><SelectContent>{site?.seasons.map((s) => <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>)}</SelectContent></Select>
        </div>
        {!data ? (error ? <ErrorState message={error} onRetry={reload} /> : <Loading />) : (
          <div className="space-y-8">
            {view === 'league' ? <SortTable cols={cols} rows={data.rows} rowKey={(r) => r.teamId} /> :
              [...new Set(data.rows.map((r) => r.conference as string))].sort().map((c) => (
                <section key={c}><h2 className="mb-3 font-display text-2xl font-extrabold uppercase">{c} Conference</h2><SortTable cols={cols} rows={data.rows.filter((r) => r.conference === c)} rowKey={(r) => r.teamId} /></section>
              ))}
            <div className="rounded-lg border bg-card p-4 text-sm text-muted-foreground">
              <p><b className="text-foreground">Points system:</b> Win {data.points.win} · OT win {data.points.otWin} · SO win {data.points.soWin} · OT loss {data.points.otLoss} · SO loss {data.points.soLoss} · Regulation loss {data.points.regLoss}.</p>
              <p className="mt-1"><b className="text-foreground">Tiebreakers:</b> {data.tiebreakers.map((t) => LABEL[t] ?? t).join(' → ')}.</p>
              <p className="mt-1">Standings include finalized regular-season games only and update the moment a game goes final.</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

