import { useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { getStats } from 'zitejs/api';
import { Input } from '@project/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@project/components/ui/tabs';
import SortTable, { type Col } from '../components/SortTable';
import TeamLogo from '../components/TeamLogo';
import { ErrorState, Loading, PageHeader, useLoad } from '../components/ui';
import { useSite } from '../lib/site';

type R = Record<string, any>;
const pct = (v: number) => (v ? v.toFixed(3).replace(/^0/, '') : '—');

export default function Stats() {
  const { site, team } = useSite();
  const [seasonId, setSeasonId] = useState('');
  const [teamId, setTeamId] = useState('all');
  const [q, setQ] = useState('');
  const { data, error, reload } = useLoad(() => getStats({ seasonId: seasonId || undefined, teamId: teamId === 'all' ? undefined : teamId }), [seasonId, teamId], 60000);
  const player = (r: R) => <Link to={`/players/${r.id}`} className="flex items-center gap-2 font-semibold hover:text-accent"><TeamLogo teamId={r.teamId} size={20} />{r.name}</Link>;
  const sk: Col<R>[] = [
    { key: 'name', label: 'Player', left: true, render: player }, { key: 'teamId', label: 'Team', render: (r) => team(r.teamId)?.abbreviation, sortValue: (r) => team(r.teamId)?.abbreviation ?? '' },
    { key: 'pos', label: 'Pos' }, { key: 'gp', label: 'GP' }, { key: 'g', label: 'G' }, { key: 'a', label: 'A' }, { key: 'pts', label: 'PTS' },
    { key: 'ppg', label: 'PPG', title: 'Power-play goals' }, { key: 'shg', label: 'SHG', title: 'Shorthanded goals' }, { key: 'gwg', label: 'GWG', title: 'Game-winning goals' },
    { key: 'shots', label: 'SOG' }, { key: 'pim', label: 'PIM' }, { key: 'ppgPerGame', label: 'P/GP', render: (r) => Number(r.ppgPerGame).toFixed(2) },
  ];
  const gk: Col<R>[] = [
    { key: 'name', label: 'Goaltender', left: true, render: player }, { key: 'teamId', label: 'Team', render: (r) => team(r.teamId)?.abbreviation },
    { key: 'gp', label: 'GP' }, { key: 'w', label: 'W' }, { key: 'l', label: 'L' }, { key: 'otl', label: 'OTL' }, { key: 'sa', label: 'SA' }, { key: 'saves', label: 'SV' }, { key: 'ga', label: 'GA' },
    { key: 'svPct', label: 'SV%', render: (r) => pct(r.svPct) }, { key: 'gaa', label: 'GAA', render: (r) => Number(r.gaa).toFixed(2) }, { key: 'so', label: 'SO', title: 'Shutouts' },
  ];
  const tm: Col<R>[] = [
    { key: 'teamId', label: 'Team', left: true, render: (r) => <Link to={`/teams/${r.teamId}`} className="flex items-center gap-2 font-semibold hover:text-accent"><TeamLogo teamId={r.teamId} size={22} />{team(r.teamId)?.name}</Link> },
    { key: 'gp', label: 'GP' }, { key: 'gf', label: 'GF' }, { key: 'ga', label: 'GA' }, { key: 'shots', label: 'SOG' },
    { key: 'ppg', label: 'PPG' }, { key: 'ppo', label: 'PPO', title: 'Power-play opportunities' }, { key: 'ppPct', label: 'PP%', render: (r) => `${r.ppPct}%` }, { key: 'shg', label: 'SHG' }, { key: 'pim', label: 'PIM' },
  ];
  const filt = (rows: R[]) => rows.filter((r) => !q || String(r.name).toLowerCase().includes(q.toLowerCase()));
  const skaters = useMemo(() => filt(data?.skaters ?? []), [data, q]);
  const goalies = useMemo(() => filt(data?.goalies ?? []), [data, q]);
  return (
    <div>
      <PageHeader eyebrow="Statistics Center" title="Stats">Calculated from finalized games and recorded game events. Goals-against average is per game played.</PageHeader>
      <div className="mx-auto max-w-7xl px-4 py-8">
        <div className="mb-5 flex flex-wrap gap-2">
          <Input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Search player…" className="w-56" />
          <Select value={teamId} onValueChange={setTeamId}><SelectTrigger className="w-48"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">All teams</SelectItem>{site?.teams.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent></Select>
          <Select value={seasonId || data?.seasonId || ''} onValueChange={setSeasonId}><SelectTrigger className="w-44"><SelectValue placeholder="Season" /></SelectTrigger><SelectContent>{site?.seasons.map((s) => <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>)}</SelectContent></Select>
