            <TabsContent value="skaters" className="mt-4"><SortTable cols={sk} rows={skaters} initial="pts" rowKey={(r) => r.id} pageSize={25} /></TabsContent>
            <TabsContent value="goalies" className="mt-4"><SortTable cols={gk} rows={goalies} initial="w" rowKey={(r) => r.id} pageSize={25} /></TabsContent>
            <TabsContent value="teams" className="mt-4"><SortTable cols={tm} rows={data.teams} initial="gf" rowKey={(r) => r.teamId} /></TabsContent>
          </Tabs>
        )}
      </div>
    </div>
  );
}

import { useParams, Link } from 'react-router-dom';
import { MapPin, Users } from 'lucide-react';
import { getTeam } from 'zitejs/api';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@project/components/ui/tabs';
import GameTile from '../components/GameTile';
import ArticleCard from '../components/ArticleCard';
import SortTable from '../components/SortTable';
import TeamLogo from '../components/TeamLogo';
import { Empty, ErrorState, FollowButton, Loading, useLoad } from '../components/ui';
import { useServerNow } from '../lib/site';

export default function Team() {
  const { id = '' } = useParams();
  const { data, error, reload } = useLoad(() => getTeam({ id }), [id], 30000);
  const now = useServerNow();
  if (!data) return error ? <ErrorState message={error} onRetry={reload} /> : <Loading />;
  const t = data.team;
  const st = data.standing;
  const upcoming = data.games.filter((g) => g.status !== 'Final');
  const results = data.games.filter((g) => g.status === 'Final').reverse();
  const groups = ['C', 'LW', 'RW', 'D', 'G'];
  return (
    <div>
      <section className="relative overflow-hidden text-white" style={{ background: `linear-gradient(120deg, ${t.primaryColor ?? '#0f172a'} 0%, #0b1526 85%)` }}>
        <div className="ice-lines absolute inset-0 opacity-40" />
        <div className="relative mx-auto flex max-w-7xl flex-wrap items-center gap-6 px-4 py-12">
          <TeamLogo teamId={t.id} size={120} />
          <div className="flex-1">
            <div className="text-xs font-bold uppercase tracking-[0.3em] text-white/70">{t.conference} Conference · Est. {t.founded}</div>
            <h1 className="font-display text-5xl font-extrabold uppercase leading-none md:text-6xl">{t.name}</h1>
            <div className="mt-2 flex items-center gap-1 text-sm text-white/75"><MapPin className="h-4 w-4" />{data.venue.name}{data.venue.city ? `, ${data.venue.city}` : ''}</div>
          </div>
          <div className="flex gap-6 text-center">
            {[['Record', st ? `${st.wins}-${st.losses}-${st.otLosses}` : '0-0-0'], ['Points', st?.points ?? 0], ['Conf. rank', data.rank || '—']].map(([l, v]) => (
              <div key={l as string}><div className="font-display text-4xl font-extrabold tabular">{v}</div><div className="text-[10px] uppercase tracking-widest text-white/60">{l}</div></div>
            ))}
          </div>
          <FollowButton teamId={t.id} className="bg-white/10 text-white" />
        </div>
      </section>
      <div className="mx-auto max-w-7xl px-4 py-8">
        <Tabs defaultValue="roster">
          <TabsList className="h-auto flex-wrap">{['roster', 'schedule', 'stats', 'staff', 'news', 'about'].map((x) => <TabsTrigger key={x} value={x} className="capitalize">{x}</TabsTrigger>)}</TabsList>
          <TabsContent value="roster" className="mt-6 space-y-6">
            {groups.map((pos) => {
              const list = data.roster.filter((p) => p.pos === pos);
              if (!list.length) return null;
              return (
                <section key={pos}>
                  <h3 className="mb-2 font-display text-lg font-bold uppercase">{{ C: 'Centers', LW: 'Left wings', RW: 'Right wings', D: 'Defense', G: 'Goaltenders' }[pos]}</h3>
                  <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
                    {list.map((p) => (
                      <Link key={p.id} to={`/players/${p.id}`} className="flex items-center gap-3 rounded-lg border bg-card p-3 transition hover:shadow-md">
                        <span className="w-10 text-center font-display text-3xl font-black text-muted-foreground/50">{p.num}</span>
                        <div className="min-w-0 flex-1"><div className="truncate font-semibold">{p.name}</div><div className="truncate text-xs text-muted-foreground">{p.shoots ? `Shoots ${p.shoots} · ` : ''}{p.height} · {p.hometown}</div></div>
                        {p.status !== 'Active' && <span className="rounded bg-accent/10 px-2 py-0.5 text-[10px] font-bold uppercase text-accent">{p.status}</span>}
                      </Link>
                    ))}
                  </div>
                </section>
              );
            })}
          </TabsContent>
          <TabsContent value="schedule" className="mt-6 space-y-8">
            <section><h3 className="mb-3 font-display text-lg font-bold uppercase">Upcoming</h3>{upcoming.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{upcoming.map((g) => <GameTile key={g.id} g={g} now={now} />)}</div> : <Empty>No upcoming games.</Empty>}</section>
            <section><h3 className="mb-3 font-display text-lg font-bold uppercase">Results</h3>{results.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">{results.map((g) => <GameTile key={g.id} g={g} now={now} />)}</div> : <Empty>No completed games yet.</Empty>}</section>
          </TabsContent>
          <TabsContent value="stats" className="mt-6 space-y-6">
            <SortTable rows={data.skaters} initial="pts" rowKey={(r) => r.id} cols={[{ key: 'name', label: 'Skater', left: true, render: (r) => <Link to={`/players/${r.id}`} className="font-semibold hover:text-accent">#{r.num} {r.name}</Link> }, { key: 'pos', label: 'Pos' }, { key: 'gp', label: 'GP' }, { key: 'g', label: 'G' }, { key: 'a', label: 'A' }, { key: 'pts', label: 'PTS' }, { key: 'ppg', label: 'PPG' }, { key: 'shots', label: 'SOG' }, { key: 'pim', label: 'PIM' }]} />
            <SortTable rows={data.goalies} initial="w" rowKey={(r) => r.id} cols={[{ key: 'name', label: 'Goaltender', left: true, render: (r) => <Link to={`/players/${r.id}`} className="font-semibold hover:text-accent">#{r.num} {r.name}</Link> }, { key: 'gp', label: 'GP' }, { key: 'w', label: 'W' }, { key: 'l', label: 'L' }, { key: 'otl', label: 'OTL' }, { key: 'svPct', label: 'SV%', render: (r) => (r.svPct ? r.svPct.toFixed(3).replace(/^0/, '') : '—') }, { key: 'gaa', label: 'GAA', render: (r) => Number(r.gaa).toFixed(2) }, { key: 'so', label: 'SO' }]} />
          </TabsContent>
          <TabsContent value="staff" className="mt-6">
            {data.staff.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{data.staff.map((s) => (
              <div key={s.id} className="rounded-lg border bg-card p-4"><div className="text-xs font-bold uppercase tracking-widest text-accent">{s.role}</div><div className="font-display text-xl font-bold uppercase">{s.name}</div>{s.bio && <p className="mt-1 text-sm text-muted-foreground">{s.bio}</p>}</div>
            ))}</div> : <Empty><Users className="mx-auto mb-2 h-6 w-6" />Coaching staff not yet listed.</Empty>}
          </TabsContent>
          <TabsContent value="news" className="mt-6">{data.articles.length ? <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{data.articles.map((a) => <ArticleCard key={a.id} a={a} />)}</div> : <Empty>No team news yet.</Empty>}</TabsContent>
          <TabsContent value="about" className="mt-6 max-w-3xl space-y-3 text-muted-foreground">
            <p>{t.description || `${t.name} compete in the ${t.conference} Conference.`}</p>
            <p><b className="text-foreground">Home arena:</b> {data.venue.name}{data.venue.capacity ? ` · capacity ${Number(data.venue.capacity).toLocaleString()}` : ''}{data.venue.address ? ` · ${data.venue.address}` : ''}</p>
            {t.isDemo && <p className="text-xs font-semibold uppercase text-accent">Demonstration team</p>}
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

