import { useMemo, useState } from 'react';
import { Link } from 'react-router-dom';
import { listGames } from 'zitejs/api';
import { Ticket } from 'lucide-react';
import { Button } from '@project/components/ui/button';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@project/components/ui/select';
import TeamLogo from '../components/TeamLogo';
import { Empty, ErrorState, Loading, PageHeader, useLoad } from '../components/ui';
import { useSite } from '../lib/site';
import { TIER_NAME, TIER_PRICE } from '../lib/seating';

export default function Tickets() {
  const { site, team } = useSite();
  const [teamId, setTeamId] = useState('all');
  const from = useMemo(() => new Date().toISOString(), []);
  const { data, error, reload } = useLoad(() => listGames({ from, status: 'Scheduled' }), [from]);
  const games = (data?.games ?? []).filter((g) => teamId === 'all' || g.homeTeamId === teamId || g.awayTeamId === teamId).slice(0, 60);
  return (
    <div>
      <PageHeader eyebrow="Box office" title="Tickets">
        <p className="mt-3 max-w-xl text-primary-foreground/80">Pick a game, choose your exact seats on the arena map, and check out in seconds.</p>
        <div className="mt-4 flex flex-wrap gap-2 text-xs">
          {(['R', 'L', 'U'] as const).map((t) => <span key={t} className="rounded-full bg-white/10 px-3 py-1 font-semibold">{TIER_NAME[t]} · ${TIER_PRICE[t]}</span>)}
        </div>
      </PageHeader>
      <div className="mx-auto max-w-5xl space-y-4 px-4 py-8">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <h2 className="font-display text-2xl font-extrabold uppercase">Upcoming games</h2>
          <div className="flex gap-2">
            <Select value={teamId} onValueChange={setTeamId}>
              <SelectTrigger className="w-56"><SelectValue /></SelectTrigger>
              <SelectContent><SelectItem value="all">All teams</SelectItem>{site?.teams.map((t) => <SelectItem key={t.id} value={t.id}>{t.name}</SelectItem>)}</SelectContent>
            </Select>
            <Button asChild variant="outline"><Link to="/tickets/orders">My tickets</Link></Button>
          </div>
        </div>
        {!data ? (error ? <ErrorState message={error} onRetry={reload} /> : <Loading rows={4} />) : games.length === 0 ? <Empty>No upcoming games on sale.</Empty> : (
          <ul className="divide-y overflow-hidden rounded-lg border bg-card shadow-sm">
            {games.map((g) => (
              <li key={g.id} className="flex flex-wrap items-center gap-4 p-4 transition hover:bg-muted/40">
                <div className="w-28 shrink-0 text-sm">
                  <div className="font-display text-lg font-bold uppercase leading-none">{new Date(g.start).toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric' })}</div>
                  <div className="text-muted-foreground">{new Date(g.start).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' })}</div>
                </div>
                <div className="flex min-w-[220px] flex-1 items-center gap-2">
                  <TeamLogo teamId={g.awayTeamId} size={32} /><span className="font-semibold">{team(g.awayTeamId)?.name}</span>
                  <span className="text-muted-foreground">@</span>
                  <TeamLogo teamId={g.homeTeamId} size={32} /><span className="font-semibold">{team(g.homeTeamId)?.name}</span>
                </div>
                <div className="text-sm text-muted-foreground">{g.venue}</div>
                <Button asChild className="bg-accent text-accent-foreground hover:bg-accent/90"><Link to={`/tickets/${g.id}`}><Ticket className="mr-2 h-4 w-4" />Pick seats</Link></Button>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

