    if (!p) throw new Error("Player not found");
    const s = await getSettings();
    const isG = p.position === "G";
    const seasons = (await zite.seasons.findAll({ limit: 100 })).records.sort((a, b) => String(b.name).localeCompare(String(a.name)));
