    const { rows } = await zite.sql({
      query: `
        SELECT g.id, g."scheduledStart" AS d, g."homeTeamId" AS h, g."awayTeamId" AS a, COALESCE(g."homeScore",0) AS hs, COALESCE(g."awayScore",0) AS vs, g."decision" AS dec, g."status" AS st,
          COUNT(e.id) FILTER (WHERE e."eventType" = 'Goal' AND e."playerId" = $1) AS g,
          COUNT(e.id) FILTER (WHERE e."eventType" = 'Goal' AND (e."assist1Id" = $1 OR e."assist2Id" = $1)) AS a2,
          COUNT(e.id) FILTER (WHERE e."eventType" IN ('Goal','Shot') AND e."playerId" = $1) AS sog,
          COALESCE(SUM(e."penaltyMinutes") FILTER (WHERE e."eventType" = 'Penalty' AND e."playerId" = $1), 0) AS pim,
          COUNT(e.id) FILTER (WHERE e."eventType" = 'Shot' AND e."goalieId" = $1) AS sv,
          COUNT(e.id) FILTER (WHERE e."eventType" = 'Goal' AND e."goalieId" = $1) AS ga
        FROM "Games" g JOIN "GameEvents" e ON e."gameId" = g.id::text AND COALESCE(e."isVoid", false) = false
        WHERE (g."homeTeamId" = $2 OR g."awayTeamId" = $2) AND g."status" IN ('Final','Live','Intermission','Overtime','Shootout')
        GROUP BY g.id ORDER BY g."scheduledStart" DESC LIMIT 60`,
      params: [p.id, p.teamId ?? ""]
    });
    const awards = await zite.awards.findAll({ filters: { playerId: p.id }, limit: 50 });
    return {
      player: { id: p.id, name: p.fullName ?? "", num: Number(p.jerseyNumber ?? 0), pos: p.position ?? "", teamId: p.teamId ?? "", shoots: p.shoots ?? "", height: p.height ?? "", weight: Number(p.weight ?? 0), birthDate: p.birthDate ?? "", hometown: p.hometown ?? "", bio: p.bio ?? "", photoUrl: p.photoUrl ?? "", status: p.status ?? "", isDemo: !!p.isDemo },
      seasons: withGames,
