        const my = home ? Number(r.hs) : Number(r.vs), op = home ? Number(r.vs) : Number(r.hs);
        const result = r.st !== "Final" ? "LIVE" : `${my > op ? "W" : my < op ? r.dec === "Regulation" ? "L" : "OTL" : "T"} ${my}-${op}${r.dec && r.dec !== "Regulation" ? r.dec === "Overtime" ? " OT" : " SO" : ""}`;
        return { gameId: String(r.id), date: r.d ? new Date(String(r.d)).toISOString() : "", opponentId: String(home ? r.a : r.h), home, result, g: Number(r.g), a: Number(r.a2), sog: Number(r.sog), pim: Number(r.pim), sa: Number(r.sv) + Number(r.ga), sv: Number(r.sv), ga: Number(r.ga) };
      }),
